-- Catalog mở rộng Home & Living: 5 danh mục mới, ~280 sản phẩm, phân loại, ảnh, tồn kho, đánh giá mẫu.
-- Sinh tự động từ catalog.json; id sản phẩm >= 1001, phân loại >= 10001, ảnh >= 10001. Chạy lại an toàn.
SET NAMES 'utf8mb4' COLLATE 'utf8mb4_unicode_ci';

UPDATE category SET thumbnail = 'https://images.unsplash.com/photo-1765862835193-3c37388a409e?ixid=M3wxMDg3MDA0fDB8MXxzZWFyY2h8MXx8bWluaW1hbGlzdCUyMGJlZHJvb20lMjB3b29kZW4lMjBiZWR8ZW58MXwyfHx8MTc5MDY1ODk3NHww&ixlib=rb-4.1.0&w=800&h=800&fit=crop&crop=entropy&q=75&fm=jpg' WHERE id = 10 AND (thumbnail IS NULL OR thumbnail = '/images/placeholder-product.svg');
UPDATE category SET thumbnail = 'https://images.unsplash.com/photo-1745613999710-1aaf60145502?ixid=M3wxMDg3MDA0fDB8MXxzZWFyY2h8M3x8bGluZW4lMjBiZWRkaW5nJTIwbmV1dHJhbHxlbnwxfDJ8fHwxNzkwNjU4OTgyfDA&ixlib=rb-4.1.0&w=800&h=800&fit=crop&crop=entropy&q=75&fm=jpg' WHERE id = 11 AND (thumbnail IS NULL OR thumbnail = '/images/placeholder-product.svg');
UPDATE category SET thumbnail = 'https://images.unsplash.com/photo-1615471618985-97108e2ba478?ixid=M3wxMDg3MDA0fDB8MXxzZWFyY2h8M3x8bGl2aW5nJTIwcm9vbSUyMHJ1ZyUyMGN1cnRhaW5zfGVufDF8Mnx8fDE3OTA2NTg5OTB8MA&ixlib=rb-4.1.0&w=800&h=800&fit=crop&crop=entropy&q=75&fm=jpg' WHERE id = 12 AND (thumbnail IS NULL OR thumbnail = '/images/placeholder-product.svg');
UPDATE category SET thumbnail = 'https://images.unsplash.com/photo-1765745520336-88acf0b84fe4?ixid=M3wxMDg3MDA0fDB8MXxzZWFyY2h8MXx8bWluaW1hbGlzdCUyMGJhdGhyb29tJTIwdG93ZWxzfGVufDF8Mnx8fDE3OTA2NTg5OTd8MA&ixlib=rb-4.1.0&w=800&h=800&fit=crop&crop=entropy&q=75&fm=jpg' WHERE id = 13 AND (thumbnail IS NULL OR thumbnail = '/images/placeholder-product.svg');
UPDATE category SET thumbnail = 'https://images.unsplash.com/photo-1783538690031-d7f1bace437d?ixid=M3wxMDg3MDA0fDB8MXxzZWFyY2h8M3x8YmFsY29ueSUyMG91dGRvb3IlMjBmdXJuaXR1cmV8ZW58MXwyfHx8MTc5MDY1OTAwN3ww&ixlib=rb-4.1.0&w=800&h=800&fit=crop&crop=entropy&q=75&fm=jpg' WHERE id = 14 AND (thumbnail IS NULL OR thumbnail = '/images/placeholder-product.svg');



-- Ảnh: chạy lại sẽ thay ảnh mẫu bằng ảnh thật (không đè ảnh do quản trị viên tự tải lên vì id khác dải)
ON DUPLICATE KEY UPDATE path = VALUES(path), name = VALUES(name), content_type = VALUES(content_type), updated_at = NOW();


-- Tồn kho: thêm vào phiếu nhập đã hoàn tất (docket 1)

