INSERT IGNORE INTO category (id, created_at, updated_at, created_by, updated_by, name, slug, description, thumbnail, category_id, status) VALUES
(10, NOW(), NOW(), null, null, 'Phòng ngủ', 'phong-ngu', 'Giường gỗ, nệm, tủ quần áo và bàn trang điểm cho phòng ngủ yên tĩnh', 'https://images.unsplash.com/photo-1765862835193-3c37388a409e?ixid=M3wxMDg3MDA0fDB8MXxzZWFyY2h8MXx8bWluaW1hbGlzdCUyMGJlZHJvb20lMjB3b29kZW4lMjBiZWR8ZW58MXwyfHx8MTc5MDY1ODk3NHww&ixlib=rb-4.1.0&w=800&h=800&fit=crop&crop=entropy&q=75&fm=jpg', null, 1),
(11, NOW(), NOW(), null, null, 'Chăn ga gối', 'chan-ga-goi', 'Bộ chăn ga cotton, linen, gối ngủ và chăn mền mềm mại', 'https://images.unsplash.com/photo-1745613999710-1aaf60145502?ixid=M3wxMDg3MDA0fDB8MXxzZWFyY2h8M3x8bGluZW4lMjBiZWRkaW5nJTIwbmV1dHJhbHxlbnwxfDJ8fHwxNzkwNjU4OTgyfDA&ixlib=rb-4.1.0&w=800&h=800&fit=crop&crop=entropy&q=75&fm=jpg', null, 1),
(12, NOW(), NOW(), null, null, 'Rèm & thảm', 'rem-tham', 'Rèm cửa vải, rèm cuốn, thảm phòng khách và thảm cói tự nhiên', 'https://images.unsplash.com/photo-1615471618985-97108e2ba478?ixid=M3wxMDg3MDA0fDB8MXxzZWFyY2h8M3x8bGl2aW5nJTIwcm9vbSUyMHJ1ZyUyMGN1cnRhaW5zfGVufDF8Mnx8fDE3OTA2NTg5OTB8MA&ixlib=rb-4.1.0&w=800&h=800&fit=crop&crop=entropy&q=75&fm=jpg', null, 1),
(13, NOW(), NOW(), null, null, 'Phòng tắm', 'phong-tam', 'Khăn tắm cotton, kệ và phụ kiện phòng tắm tối giản', 'https://images.unsplash.com/photo-1765745520336-88acf0b84fe4?ixid=M3wxMDg3MDA0fDB8MXxzZWFyY2h8MXx8bWluaW1hbGlzdCUyMGJhdGhyb29tJTIwdG93ZWxzfGVufDF8Mnx8fDE3OTA2NTg5OTd8MA&ixlib=rb-4.1.0&w=800&h=800&fit=crop&crop=entropy&q=75&fm=jpg', null, 1),
(14, NOW(), NOW(), null, null, 'Ngoài trời & ban công', 'ngoai-troi', 'Bàn ghế ban công, ghế gỗ teak, chậu treo và đèn năng lượng mặt trời', 'https://images.unsplash.com/photo-1783538690031-d7f1bace437d?ixid=M3wxMDg3MDA0fDB8MXxzZWFyY2h8M3x8YmFsY29ueSUyMG91dGRvb3IlMjBmdXJuaXR1cmV8ZW58MXwyfHx8MTc5MDY1OTAwN3ww&ixlib=rb-4.1.0&w=800&h=800&fit=crop&crop=entropy&q=75&fm=jpg', null, 1);
INSERT IGNORE INTO product (id, created_at, updated_at, created_by, updated_by, name, code, slug, short_description, description, status, category_id, brand_id, supplier_id, unit_id, specifications, properties, weight, guarantee_id) VALUES
(1001, NOW(), NOW(), null, null, 'Ghế ăn gỗ sồi tự nhiên Necom lưng mây đan mắt cáo tinh tế', 'NEST-BG-1001', 'ghe-an-go-soi-tu-nhien-necom-lung-may-dan-mat-cao-tinh-te', 'Ghế ăn gỗ sồi lưng tựa mây đan mắt cáo thoáng mát mang lại cảm giác dễ chịu và nét mộc mạc cho bàn ăn.', 'Ghế ăn chế tác từ khung gỗ sồi tự nhiên chắc chắn kết hợp lưng tựa mây mắt cáo đan thủ công thông thoáng. Đường nét uốn lượn nhẹ nhàng ôm lấy vòm lưng giúp bạn ngồi lâu mà không mỏi mệt. Thiết kế thanh thoát phù hợp bố trí trong phòng ăn căn hộ hay quán cà phê phong cách mộc mạc tinh tế. Lớp sơn mờ bảo vệ bề mặt chống bám bẩn nhẹ và tôn lên thớ vân gỗ tự nhiên ấm cúng. Khi vệ sinh bạn chỉ cần dùng khăn mềm ẩm vắt ráo lau chùi nhẹ và tránh để nơi có ánh nắng chiếu trực tiếp liên tục.', 1, 1, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên, mây mắt cáo đan thủ công"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "48 x 52 x 82 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Gỗ sồi màu tự nhiên", "Gỗ sồi lau màu óc chó"]}], "totalElements": 1}', 5500, 2),
(1002, NOW(), NOW(), null, null, 'Bàn ăn gỗ tần bì chân vát tối giản Bắc Âu kéo dài linh hoạt', 'NEST-BG-1002', 'ban-an-go-tan-bi-chan-vat-toi-gian-bac-au-keo-dai-linh-hoat', 'Bàn ăn gỗ tần bì tự nhiên mặt phẳng mịn màng tạo điểm nhấn ấm áp và hiện đại cho gian bếp gia đình.', 'Mẫu bàn ăn tinh tế sở hữu mặt gỗ tần bì tự nhiên sáng màu cùng hệ khung chân vát góc cứng cáp. Bề mặt sản phẩm được xử lý mài nhẵn mịn màng mang đến cảm giác chạm êm ái mát lành mỗi bữa cơm gia đình quây quần. Kiểu dáng thanh mảnh đặc trưng Bắc Âu giúp tối ưu hóa diện tích cho gian bếp chung cư hoặc phòng ăn gia đình hiện đại. Bạn nên sử dụng tấm lót cách nhiệt khi đặt xoong nồi nóng và dùng khăn ẩm lau sạch ngay các vết dầu mỡ để giữ màu gỗ luôn tươi mới dài lâu.', 1, 1, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tần bì tự nhiên, sơn phủ mờ chống thấm"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "140 x 80 x 75 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["140 x 80 cm", "160 x 80 cm"]}], "totalElements": 1}', 28000, 2),
(1003, NOW(), NOW(), null, null, 'Ghế đôn tròn bọc vải Linen chân gỗ cao su phong cách tối giản', 'NEST-BG-1003', 'ghe-don-tron-boc-vai-linen-chan-go-cao-su-phong-cach-toi-gian', 'Ghế đôn tròn đệm vải linen êm ái chân gỗ tự nhiên nhỏ gọn tiện lợi di chuyển cho mọi góc phòng.', 'Ghế đôn tròn nhỏ gọn với khung chân gỗ cao su tiện tròn vững chãi nâng đỡ đệm mút êm ái bọc vải linen dày dặn. Mặt đệm có độ đàn hồi cao mang lại sự thoải mái khi làm ghế phụ tiếp khách ngồi thay giày tại lối vào hoặc góc trang điểm. Gam màu trang nhã dung hòa hoàn hảo với không gian phòng khách nhỏ hay phòng ngủ tối giản. Để giữ gìn đôn luôn sạch đẹp bạn nên hút bụi định kỳ trên bề mặt vải và lau chân gỗ bằng khăn mềm, tránh để nước đổ ngấm sâu vào lớp mút xốp bên trong.', 1, 1, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ cao su tự nhiên, đệm mút D40 bọc vải thô linen"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "35 x 35 x 42 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu be cát", "Màu xám tro", "Màu nâu đất"]}], "totalElements": 1}', 3200, 2),
(1004, NOW(), NOW(), null, null, 'Ghế bar chân sắt sơn tĩnh điện mặt gỗ ash bo cong Japandi', 'NEST-BG-1004', 'ghe-bar-chan-sat-son-tinh-dien-mat-go-ash-bo-cong-japandi', 'Ghế bar mặt gỗ tần bì chân sắt sơn tĩnh điện dáng cao thanh thoát cho quầy bar và đảo bếp hiện đại.', 'Ghế bar thiết kế tối giản giao thoa giữa nét thanh thoát của phong cách Nhật Bản và tính ứng dụng Bắc Âu. Phần mặt ngồi gỗ tần bì tiện cong nguyên khối tạo tư thế ngồi ôm trọn thoải mái kết hợp khung thép sơn tĩnh điện chống gỉ sét bền bỉ. Mẫu ghế là điểm nhấn lý tưởng cho quầy đảo bếp gia đình, quầy pha chế hoặc ban công ngắm cảnh thoáng đãng. Bạn nên định kỳ kiểm tra siết lại ốc vít liên kết và lau chùi bề mặt kim loại bằng khăn khô mềm, hạn chế dùng hóa chất tẩy rửa mạnh gây mòn lớp sơn bề mặt.', 1, 1, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Khung thép sơn tĩnh điện sần, mặt ngồi gỗ tần bì tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "42 x 44 x 75 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "bếp"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Cao mặt ngồi 65 cm", "Cao mặt ngồi 75 cm"]}], "totalElements": 1}', 4800, 2),
(1005, NOW(), NOW(), null, null, 'Ghế thư giãn bập bênh khung gỗ bạch dương kèm đệm nỉ êm ái', 'NEST-BG-1005', 'ghe-thu-gian-bap-benh-khung-go-bach-duong-kem-dem-ni-em-ai', 'Ghế bập bênh thư giãn khung gỗ uốn cong êm ái nâng đỡ cơ thể trọn vẹn sau ngày dài bận rộn.', 'Ghế bập bênh mang kết cấu khung gỗ bạch dương uốn cong nhẹ nhàng với độ đàn hồi tự nhiên nâng niu trọn vẹn cột sống. Đệm ngồi bọc vải nỉ cotton dày xốp tạo cảm giác bồng bềnh êm dịu giúp bạn thả lỏng tối đa khi đọc sách xem phim hay ru bé ngủ. Sản phẩm tô điểm nét ấm cúng cho góc ban công phòng ngủ hoặc phòng khách phong cách Scandinavian hiện đại. Bạn có thể tháo rời vỏ đệm giặt tay nhẹ nhàng với nước giặt trung tính và lau phần khung gỗ bằng khăn ẩm sạch để sản phẩm luôn như mới.', 1, 1, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ bạch dương uốn nhiệt, nệm mút bọc vải cotton nỉ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "68 x 82 x 95 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng kem", "Xám nhạt"]}], "totalElements": 1}', 9200, 2),
(1006, NOW(), NOW(), null, null, 'Bàn console lối vào gỗ tự nhiên ngăn kéo mây đan phong cách mộc', 'NEST-BG-1006', 'ban-console-loi-vao-go-tu-nhien-ngan-keo-may-dan-phong-cach-moc', 'Bàn console gỗ tự nhiên ngăn kéo mây đan tinh xảo tạo điểm nhấn trang nhã cho khu vực huyền quan lối vào.', 'Chiếc bàn console kết hợp khung gỗ tự nhiên vững chãi cùng mặt ngăn kéo đan mây mộc mạc mang đậm tinh thần Wabi-Sabi. Mặt bàn rộng rãi là nơi lý tưởng đặt bình hoa gốm, tranh nghệ thuật hay chìa khóa mỗi khi bước vào nhà tạo cảm giác đón chào ấm áp. Thiết kế mỏng gọn giúp tối ưu không gian hành lang tiền sảnh phòng khách hay phòng làm việc thanh lịch. Vệ sinh bàn đơn giản bằng chổi lông mềm quét bụi khe mây và lau mặt gỗ bằng khăn mềm vắt ráo, giữ sản phẩm ở nơi khô ráo thoáng khí.', 1, 1, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tràm phủ veneer sồi, mây mắt cáo tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "100 x 35 x 80 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu gỗ mộc", "Màu nâu cánh gián"]}], "totalElements": 1}', 14000, 2),
(1007, NOW(), NOW(), null, null, 'Bàn trà tròn đôi mặt đá thiêu kết chân gỗ sồi khối điêu khắc', 'NEST-BG-1007', 'ban-tra-tron-doi-mat-da-thieu-ket-chan-go-soi-khoi-dieu-khac', 'Bàn trà tròn mặt đá thiêu kết vân mây kết hợp chân gỗ sồi sang trọng cho phòng khách Japandi ấm cúng.', 'Bàn trà sở hữu mặt đá thiêu kết chống trầy xước chống thấm ố vượt trội đặt trên chân trụ gỗ sồi điêu khắc bề thế. Cảm giác vuốt ve bề mặt đá mịn mát cùng hình khối điêu khắc bo tròn mềm mại tạo điểm nhấn nghệ thuật tĩnh lặng cho không gian. Bàn phù hợp bài trí tại trung tâm phòng khách chung cư hay nhà phố theo phong cách Japandi đương đại. Bạn có thể dễ dàng lau sạch mọi vết trà cà phê đổ ra bằng khăn ướt thông thường mà không lo ố vàng, tránh va chạm cạnh cứng nhọn vào viền đá.', 1, 1, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Đá thiêu kết vân mây mờ, chân trụ gỗ sồi tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "70 x 70 x 42 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Bàn đơn đường kính 70 cm", "Bộ đôi đường kính 70 và 50 cm"]}], "totalElements": 1}', 16500, 2),
(1008, NOW(), NOW(), null, null, 'Băng ghế dài gỗ cao su bo tròn góc đa năng cho bàn ăn lối vào', 'NEST-BG-1008', 'bang-ghe-dai-go-cao-su-bo-tron-goc-da-nang-cho-ban-an-loi-vao', 'Băng ghế dài gỗ cao su tự nhiên góc bo tròn an toàn tối ưu diện tích cho bàn ăn hoặc tiền sảnh.', 'Băng ghế dài chế tác từ chất liệu gỗ cao su tự nhiên tuyển chọn được bo vát cạnh tỉ mỉ tạo cảm giác tiếp xúc an toàn thân thiện. Bề mặt gỗ láng mịn giữ trọn vẹn đường vân tự nhiên mộc mạc mang lại chỗ ngồi rộng rãi vững chãi cho hai đến ba người. Thiết kế đa năng ứng dụng linh hoạt làm ghế bàn ăn băng ghế thay giày lối vào hoặc đặt cuối đuôi giường ngủ. Bảo quản ghế bằng cách lau bụi thường xuyên bằng vải cotton khô ráo, tránh kéo lê chân trên sàn và không đặt vật quá nhiệt trực tiếp lên mặt gỗ.', 1, 1, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ cao su tự nhiên nguyên tấm xử lý sấy tiêu chuẩn"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "110 x 36 x 45 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dài 110 cm", "Dài 130 cm"]}], "totalElements": 1}', 8500, 2),
(1009, NOW(), NOW(), null, null, 'Ghế ăn gỗ Teak tự nhiên bọc đệm nỉ Necom chuẩn Bắc Âu', 'NEST-BG-1009', 'ghe-an-go-teak-tu-nhien-boc-dem-ni-necom-chuan-bac-au', 'Ghế ăn gỗ teak thanh thoát kết hợp đệm ngồi êm ái mang đến không gian dùng bữa ấm cúng chuẩn Bắc Âu.', 'Khung ghế chế tác từ gỗ teak nguyên khối đã qua sấy tẩm chống cong vênh mối mọt, kết hợp cùng tựa lưng cong nhẹ ôm trọn tư thế ngồi. Đệm mút D40 bọc nỉ thoáng khí mang lại cảm giác dễ chịu ngay cả khi dùng bữa lâu cùng gia đình. Sản phẩm hoàn hảo cho phòng ăn chung cư, nhà phố hoặc góc làm việc nhỏ gọn. Vệ sinh định kỳ bằng khăn mềm vắt ráo nước và máy hút bụi cầm tay cho phần đệm nỉ, tránh ánh nắng trực tiếp.', 1, 1, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ teak tự nhiên, đệm mút bọc vải nỉ cao cấp"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "48 x 52 x 78 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Indonesia"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Ghi xám", "Be sáng", "Xanh rêu"]}], "totalElements": 1}', 6500, 2),
(1010, NOW(), NOW(), null, null, 'Bàn ăn tròn gỗ sồi chân trụ gân sọc phong cách Japandi', 'NEST-BG-1010', 'ban-an-tron-go-soi-chan-tru-gan-soc-phong-cach-japandi', 'Bàn ăn tròn chân trụ nan sọc điêu khắc tinh tế giúp tối ưu hóa diện tích căn hộ và gắn kết gia đình.', 'Mặt bàn tròn bo viền mềm mại từ gỗ sồi Mỹ tự nhiên vân sáng, nâng đỡ bởi hệ chân trụ nan sọc điêu khắc thủ công mang đậm âm hưởng thiền định Japandi. Bề mặt sơn mờ thẩm thấu giữ trọn vẹn thớ gỗ mộc mạc và chống thấm nước hiệu quả. Thiết kế bàn tròn rất phù hợp cho căn hộ hiện đại và phòng ăn ấm cúng 3 đến 5 người. Để bảo quản, nên lau bằng khăn ẩm mềm và dùng lót ly đế nồi khi đặt vật nóng.', 1, 1, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi Mỹ nhập khẩu, sơn phủ gốc nước an toàn"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "100 x 100 x 75 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Đường kính 90cm", "Đường kính 110cm"]}], "totalElements": 1}', 26000, 2),
(1011, NOW(), NOW(), null, null, 'Ghế đôn chữ nhật gỗ tần bì bọc vải boucle kem mịn Necom', 'NEST-BG-1011', 'ghe-don-chu-nhat-go-tan-bi-boc-vai-boucle-kem-min-necom', 'Ghế đôn chữ nhật bọc vải lông cừu mềm mịn làm điểm nhấn trang nhã cho bàn phấn hoặc góc ngồi thư thả.', 'Đôn chữ nhật nhỏ gọn với kết cấu chân gỗ tần bì thanh mảnh nhưng chịu lực vững chãi. Bề mặt bọc vải xù boucle cao cấp mềm mịn như mây kết hợp đệm mút đàn hồi cao tạo sự thư thái khi ngồi xỏ giày hoặc trang điểm mỗi sớm. Mẫu ghế đôn này vừa vặn đặt cạnh bàn trà, phòng ngủ hay tiền sảnh căn hộ. Nên hút bụi định kỳ nhẹ nhàng trên bề mặt vải và lau chân gỗ bằng sáp dưỡng nội thất định kỳ 6 tháng.', 1, 1, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tần bì, vải lông cừu Boucle, mút xốp nguyên sinh"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "42 x 30 x 42 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng kem", "Nâu hạt dẻ"]}], "totalElements": 1}', 3800, 2),
(1012, NOW(), NOW(), null, null, 'Ghế quầy bar gỗ dẻ gai tựa thấp nâng hạ tối giản Bắc Âu', 'NEST-BG-1012', 'ghe-quay-bar-go-de-gai-tua-thap-nang-ha-toi-gian-bac-au', 'Ghế quầy bar tựa lưng thấp hiện đại với chuyển động xoay êm ái nâng tầm quầy đảo bếp nhà bạn.', 'Khung chân kim loại sơn tĩnh điện chống trầy xước nâng đỡ mặt ngồi gỗ dẻ gai ép uốn cong công thái học, giúp nâng đỡ xương cụt dễ chịu suốt thời gian trò chuyện. Chiều cao tiêu chuẩn phù hợp quầy bar gia đình, đảo bếp chung cư hoặc quán cà phê phong cách Scandinavia thanh lịch. Vòng tròn gác chân tạo điểm tựa thoải mái khi thả lỏng chân. Vệ sinh nhanh chóng bằng khăn mềm ẩm, tránh dùng hóa chất tẩy rửa mạnh để giữ lớp sơn bền màu.', 1, 1, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ dẻ gai uốn cong, thép sơn tĩnh điện"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "44 x 44 x 85 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "bếp"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Mặt gỗ dẻ gai tự nhiên", "Mặt sơn đen mờ"]}], "totalElements": 1}', 5500, 2),
(1013, NOW(), NOW(), null, null, 'Ghế thư giãn khung mây gỗ sồi tựa nghiêng phong cách mộc', 'NEST-BG-1013', 'ghe-thu-gian-khung-may-go-soi-tua-nghieng-phong-cach-moc', 'Ghế thư giãn dáng thấp ngả lưng thoải mái giúp bạn đắm chìm trọn vẹn vào những trang sách cuối tuần.', 'Thiết kế phom dáng thấp ngả lưng 105 độ hoàn hảo hỗ trợ giải tỏa áp lực cột sống sau ngày dài bận rộn. Khung gỗ sồi chắc nịch phối hợp tựa lưng mây mắt cáo đan tay truyền thống mang đến nét duyên dáng hoài niệm cho không gian Japandi. Đệm vải bố thô thoáng khí, có thể tháo vỏ giặt dễ dàng. Rất lý tưởng đặt tại góc đọc sách phòng khách, phòng ngủ hoặc ban công kín gió. Bảo quản nơi khô ráo, tránh ngâm nước bề mặt mây tre.', 1, 1, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên, mây mắt cáo đan tay, nệm vải bố thô"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "68 x 82 x 74 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Mộc mạc"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu sồi tự nhiên", "Màu nâu hạt dẻ"]}], "totalElements": 1}', 11500, 2),
(1014, NOW(), NOW(), null, null, 'Bàn console bán nguyệt gỗ óc chó hai tầng tiền sảnh sang', 'NEST-BG-1014', 'ban-console-ban-nguyet-go-oc-cho-hai-tang-tien-sanh-sang', 'Bàn console bán nguyệt thanh thoát tôn vinh vẻ đẹp trang nhã khu vực huyền quan và lối vào căn hộ.', 'Đường cong bán nguyệt dịu dàng che khuyết điểm các góc tường góc cạnh, đồng thời tối ưu khoảng trống di chuyển tại hành lang. Sản phẩm phủ veneer óc chó trầm ấm với hệ hai tầng kệ tiện lợi để đặt bình hoa, chìa khóa và tranh ảnh kỷ niệm gia đình. Kết cấu chân thon gọn nhưng vững chãi, rất phù hợp hành lang căn hộ, tiền sảnh hoặc làm bàn trang trí sau lưng sofa. Lau bụi hàng tuần bằng khăn khô sợi microfiber mịn màng.', 1, 1, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ óc chó veneer, khung gỗ thông nguyên khối"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "95 x 35 x 82 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Hiện đại"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Chiều dài 95cm", "Chiều dài 115cm"]}], "totalElements": 1}', 14500, 2),
(1015, NOW(), NOW(), null, null, 'Bàn trà sofa mặt gỗ xoài nguyên tấm chân sắt uốn wabi sabi', 'NEST-BG-1015', 'ban-tra-sofa-mat-go-xoai-nguyen-tam-chan-sat-uon-wabi-sabi', 'Bàn trà sofa hình dáng phi đối xứng tôn vinh chất mộc nguyên bản đầy chất thơ cho phòng khách.', 'Mặt bàn giữ trọn cạnh mép tự nhiên bất quy tắc của thân gỗ xoài già tuổi, mang dấu ấn triết lý Wabi-Sabi tôn trọng vẻ đẹp không hoàn hảo của tự nhiên. Chân sắt uốn mỹ thuật thanh mảnh tạo khoảng hở thoáng đãng phía dưới gầm, dễ lau chùi bằng robot hút bụi. Thích hợp bày trí cạnh sofa nỉ trung tính trong phòng khách nhỏ hoặc căn hộ studio. Bạn chỉ cần lau sạch vết nước trà bằng khăn mềm và hạn chế đặt đồ sắc nhọn trực tiếp.', 1, 1, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ xoài tự nhiên nguyên tấm, chân thép sơn mờ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "90 x 55 x 40 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Ấn Độ"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Mặt gỗ mộc sáng", "Mặt gỗ hun khói"]}], "totalElements": 1}', 12000, 2),
(1016, NOW(), NOW(), null, null, 'Băng ghế chân vát gỗ dầu bọc nệm da simili cổ điển nhẹ', 'NEST-BG-1016', 'bang-ghe-chan-vat-go-dau-boc-nem-da-simili-co-dien-nhe', 'Băng ghế dài bọc da simili êm ái tiện dụng làm ghế phụ bàn ăn hoặc ghế ngồi xỏ giày cuối giường.', 'Khung gỗ dầu chắc khỏe liên kết bằng mộng truyền thống kết hợp chân choãi vát góc kiên cố, chịu tải trọng ấn tượng lên đến 220kg. Mặt đệm bọc da simili chống thấm nước giúp bạn hoàn toàn an tâm khi nhà có trẻ nhỏ hoặc vật nuôi. Sản phẩm vừa vặn bổ sung thêm chỗ ngồi linh hoạt quanh bàn ăn, làm đôn cuối giường phòng ngủ hoặc ghế đổi giày tại tiền sảnh. Vệ sinh cực kỳ tiện lợi chỉ với khăn ẩm và nước lau nhẹ.', 1, 1, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ dầu tự nhiên, nệm mút, da simili cao cấp"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "110 x 38 x 45 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Nâu da bò vintage", "Đen than chì", "Xanh rêu olive"]}], "totalElements": 1}', 9800, 2),
(1017, NOW(), NOW(), null, null, 'Ghế ăn gỗ cao su tựa cong bọc vải bố Necom tối giản', 'NEST-BG-1017', 'ghe-an-go-cao-su-tua-cong-boc-vai-bo-necom-toi-gian', 'Ghế ăn gỗ cao su tự nhiên với tựa lưng uốn cong mềm mại cùng đệm vải bố êm ái, mang lại vẻ ấm cúng cho góc bếp hiện đại.', 'Sản phẩm hoàn thiện từ gỗ cao su tuyển chọn qua xử lý sấy nhiệt, chống mối mọt và hạn chế cong vênh tối đa. Phần tựa lưng uốn cong nhẹ nhàng ôm trọn cột sống, kết hợp cùng đệm ngồi lót vải bố thoáng khí tạo cảm giác nâng đỡ êm ái khi dùng bữa hàng ngày. Mẫu ghế ăn mang kiểu dáng thanh lịch này thích hợp cho căn hộ chung cư, nhà phố hoặc góc làm việc tối giản. Khi bảo quản, bạn chỉ cần lau sạch khung gỗ bằng khăn ẩm mềm và hạn chế đặt gần nơi có ánh nắng chiếu trực tiếp.', 1, 1, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ cao su tự nhiên, đệm mút bọc vải bố"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "48 x 52 x 78 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu Gỗ Tự Nhiên", "Màu Nâu Óc Chó"]}], "totalElements": 1}', 5500, 2),
(1018, NOW(), NOW(), null, null, 'Bàn ăn chữ nhật gỗ sồi nga bo tròn cạnh kiểu Bắc Âu', 'NEST-BG-1018', 'ban-an-chu-nhat-go-soi-nga-bo-tron-canh-kieu-bac-au', 'Bàn ăn chữ nhật gỗ sồi Nga màu sáng ấm áp, các góc bo tròn an toàn tối đa cho tổ ấm gia đình bạn.', 'Mẫu bàn ăn chữ nhật được chế tác từ gỗ sồi Nga tự nhiên với đường vân sóng mềm mại và sắc màu sáng ấm áp. Bề mặt phủ lớp dầu lau thực vật an toàn, các cạnh bàn được bo tròn kỹ lưỡng tạo sự an tâm tuyệt đối cho gia đình có trẻ nhỏ. Bàn phù hợp bài trí tại phòng ăn phong cách Bắc Âu hoặc khu bếp liền phòng khách hiện đại. Để giữ độ bền đẹp theo thời gian, bạn nên dùng miếng lót ly khi để đồ nóng và lau bụi nhẹ nhàng bằng khăn mềm vắt ráo nước.', 1, 1, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi Nga tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "140 x 80 x 75 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dài 140cm", "Dài 160cm"]}], "totalElements": 1}', 28000, 2),
(1019, NOW(), NOW(), null, null, 'Ghế đôn gỗ thông xếp chồng gọn nhẹ phong cách Muji', 'NEST-BG-1019', 'ghe-don-go-thong-xep-chong-gon-nhe-phong-cach-muji', 'Ghế đôn tròn gỗ thông tự nhiên thiết kế xếp chồng thông minh, giải pháp tiết kiệm không gian hoàn hảo cho căn hộ nhỏ.', 'Chiếc ghế đôn mộc mạc làm từ gỗ thông tự nhiên với kết cấu mộng truyền thống vô cùng chắc chắn và bền bỉ. Thiết kế thông minh cho phép người dùng xếp chồng nhiều ghế lên nhau giúp giải phóng không gian hiệu quả sau khi sử dụng. Ghế đôn rất linh hoạt, vừa vặn làm ghế bàn phấn, ghế ngồi mang giày tiền sảnh hay chỗ ngồi phụ phòng khách. Vệ sinh định kỳ bằng chổi lông gà hoặc khăn khô mềm, tránh lau bằng hóa chất tẩy rửa mạnh làm phai màu gỗ mộc.', 1, 1, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ thông tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "33 x 33 x 45 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Gỗ Mộc Tự Nhiên", "Gỗ Sơn Trắng Mờ"]}], "totalElements": 1}', 2200, 2),
(1020, NOW(), NOW(), null, null, 'Ghế quầy bar gỗ sồi tự nhiên không tựa chuẩn Japandi', 'NEST-BG-1020', 'ghe-quay-bar-go-soi-tu-nhien-khong-tua-chuan-japandi', 'Ghế bar gỗ sồi dáng thanh mảnh không tựa lưng, tạo góc đảo bếp thoáng đãng và tinh tế chuẩn tinh thần Nhật Bản.', 'Mẫu ghế quầy bar được gia công từ chất liệu gỗ sồi tự nhiên với mặt ngồi lõm nhẹ tạo cảm giác ngồi vững chãi và cân bằng. Chân ghế có giằng để chân tiện lợi giúp bạn ngồi lâu trò chuyện hoặc thưởng thức đồ uống mà không bị mỏi gối. Thiết kế không tựa nhỏ gọn giúp dễ dàng cất giấu dưới mặt bàn đảo bếp hay quầy bar gia đình kiểu Japandi. Bạn nên vệ sinh bề mặt định kỳ bằng sáp dưỡng gỗ chuyên dụng và tránh kéo lê ghế trực tiếp trên sàn nhà.', 1, 1, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "38 x 38 x 75 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "bếp"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Cao 65cm", "Cao 75cm"]}], "totalElements": 1}', 4500, 2),
(1021, NOW(), NOW(), null, null, 'Ghế thư giãn gỗ dẻ gai lót da bò sáp nằm nghỉ êm ái', 'NEST-BG-1021', 'ghe-thu-gian-go-de-gai-lot-da-bo-sap-nam-nghi-em-ai', 'Ghế tựa thư giãn khung gỗ dẻ gai bọc đệm da bò sáp cao cấp, nâng niu trọn vẹn từng khoảnh khắc nghỉ ngơi sau ngày dài.', 'Ghế thư giãn sở hữu bộ khung gỗ dẻ gai nhập khẩu uốn lượn sắc sảo cùng bề mặt bọc da bò sáp cao cấp mang lại nét đẹp sang trọng. Lớp đệm mút đàn hồi cao ôm trọn cơ thể, tạo cảm giác thư thái tuyệt đối khi đọc sách hay nghe nhạc cuối tuần. Sản phẩm là điểm nhấn đắt giá cho phòng khách, phòng ngủ master hay góc đọc sách tĩnh lặng. Bảo quản da bằng dung dịch dưỡng da chuyên dụng mỗi sáu tháng và đặt ghế ở nơi khô ráo, thoáng mát.', 1, 1, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ dẻ gai, đệm bọc da bò sáp"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "68 x 82 x 78 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Nâu Bò Vintage", "Đen Mờ Lịch Lãm"]}], "totalElements": 1}', 11500, 2),
(1022, NOW(), NOW(), null, null, 'Bàn console khung kim loại mặt gỗ sồi hai ngăn kéo', 'NEST-BG-1022', 'ban-console-khung-kim-loai-mat-go-soi-hai-ngan-keo', 'Bàn console dáng thanh mảnh kết hợp mặt gỗ sồi và chân sắt, điểm nhấn tinh tế cho khu vực hành lang hoặc lối vào.', 'Bàn console là sự phối hợp hài hòa giữa khung sắt sơn tĩnh điện thanh mảnh và mặt bàn gỗ sồi vân tự nhiên bắt mắt. Hai ngăn kéo kín đáo cung cấp nơi cất giữ chìa khóa, hóa đơn và phụ kiện nhỏ gọn gàng, giữ cho lối đi luôn ngăn nắp. Bàn rất thích hợp đặt tại tiền sảnh, hành lang hay sát vách tường phòng khách để trưng bày bình gốm và tranh ảnh. Cách chăm sóc đơn giản là lau bụi thường xuyên bằng khăn vi sợi khô và tránh để nước đọng lâu.', 1, 1, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên, khung sắt sơn tĩnh điện"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "100 x 30 x 80 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Hiện đại"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Gỗ Sồi Tự Nhiên Chân Đen", "Gỗ Màu Nâu Chân Đen"]}], "totalElements": 1}', 13000, 2),
(1023, NOW(), NOW(), null, null, 'Bàn trà sofa hình hạt đậu gỗ tần bì uốn cong tinh tế', 'NEST-BG-1023', 'ban-tra-sofa-hinh-hat-dau-go-tan-bi-uon-cong-tinh-te', 'Bàn trà sofa dáng hạt đậu cong tự nhiên với chất liệu gỗ tần bì ấm cúng, đem lại nét mềm mại cho không gian tiếp khách.', 'Bàn trà sofa dáng hạt đậu độc đáo được làm từ gỗ tần bì tự nhiên mang vẻ đẹp hữu cơ uyển chuyển, phá bỏ sự đơn điệu cho không gian tiếp khách. Mặt bàn láng mịn, cạnh vát tinh tế chống va đập, chân bàn gỗ đặc liên kết mộng vững vàng chịu lực tốt. Sản phẩm hòa hợp hoàn hảo với sofa bọc vải trong phòng khách Japandi hoặc Wabi-Sabi tinh tế. Để bảo quản lớp sơn bảo vệ, hãy sử dụng lót đế cốc nước nóng và tránh để vật sắc nhọn cọ xát trực tiếp.', 1, 1, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tần bì tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "100 x 50 x 42 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Chiều dài 90cm", "Chiều dài 110cm"]}], "totalElements": 1}', 8000, 2),
(1024, NOW(), NOW(), null, null, 'Băng ghế dài gỗ sồi đan dây dù thủ công phong cách mộc', 'NEST-BG-1024', 'bang-ghe-dai-go-soi-dan-day-du-thu-cong-phong-cach-moc', 'Băng ghế dài gỗ sồi mặt đan dây dù chắc chắn, giải pháp ngồi đa năng tiện ích cho bàn ăn hoặc tiền sảnh nhà bạn.', 'Băng ghế dài gây ấn tượng với mặt ngồi đan dây dù chịu lực thủ công tỉ mỉ trên khung sườn gỗ sồi nguyên khối vững chãi. Độ đàn hồi từ sợi dây đan kết hợp cùng vân gỗ ấm áp mang lại sự thoải mái khi ngồi xỏ giày hoặc dùng bữa quây quần. Băng ghế dễ dàng kết hợp cùng bàn ăn gia đình hoặc đặt dọc hành lang và lối vào nhà. Bạn chỉ cần dùng máy hút bụi cầm tay hút sạch bụi bám trên dây đan và lau khung gỗ bằng khăn mềm ẩm.', 1, 1, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên, dây dù bện thủ công"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "120 x 38 x 45 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Mộc mạc"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dài 110cm", "Dài 130cm"]}], "totalElements": 1}', 9000, 2),
(1025, NOW(), NOW(), null, null, 'Ghế bar gỗ Teak tự nhiên đan dây kraft tối giản Necom', 'NEST-BG-1025', 'ghe-bar-go-teak-tu-nhien-dan-day-kraft-toi-gian-necom', 'Ghế bar gỗ teak mộc mạc đan dây cói kraft thủ công, mang lại điểm nhấn ấm áp và thanh lịch cho quầy đảo bếp hiện đại.', 'Chế tác từ khung gỗ teak tự nhiên bền bỉ kết hợp mặt ngồi đan dây kraft dẻo dai theo kỹ thuật đan chéo thủ công tinh xảo. Ghế mang lại cảm giác ngồi êm ái, thoáng khí và nâng đỡ hông rất tốt mà không cần đệm mút dày. Thiết kế chân thon gọn cùng thanh để chân tiện lợi giúp bạn thoải mái khi trò chuyện hay thưởng thức đồ uống. Phù hợp cho đảo bếp căn hộ, quầy bar gia đình hoặc quán cà phê phong cách mộc Japandi. Bảo quản bằng cách lau khăn khô mềm và tránh ẩm ướt kéo dài.', 1, 1, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ teak tự nhiên, dây kraft bện phủ sáp"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "42 x 40 x 75 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Indonesia"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "bếp"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu gỗ tự nhiên đan dây be", "Màu nâu hạt dẻ đan dây nâu"]}], "totalElements": 1}', 5200, 2),
(1026, NOW(), NOW(), null, null, 'Bàn trà vuông gỗ sồi hai tầng mặt kính gân sọc Necom', 'NEST-BG-1026', 'ban-tra-vuong-go-soi-hai-tang-mat-kinh-gan-soc-necom', 'Bàn trà sofa gỗ sồi tự nhiên với mặt kính sọc mờ hai tầng tiện dụng, tôn lên vẻ đẹp thanh thoát chuẩn phong cách Bắc Âu.', 'Sở hữu khung gỗ sồi trắng nhập khẩu cứng cáp cùng bề mặt kết hợp kính sọc mờ tao nhã, chiếc bàn trà vuông tạo hiệu ứng thị giác nhẹ nhàng cho phòng khách. Thiết kế hai tầng thông minh giúp bạn cất gọn tạp chí, remote hay khay trà bên dưới nhằm giữ mặt bàn luôn ngăn nắp. Bề mặt gỗ được hoàn thiện bằng dầu lau an toàn, làm nổi bật đường vân tự nhiên mộc mạc. Sản phẩm hòa hợp tuyệt đối với không gian Scandinavian và Japandi. Vệ sinh nhẹ nhàng bằng khăn mềm vắt ráo nước.', 1, 1, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi trắng tự nhiên, kính cường lực gân sọc"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "65 x 65 x 42 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["65 x 65 x 42 cm", "75 x 75 x 42 cm"]}], "totalElements": 1}', 12500, 2),
(1027, NOW(), NOW(), null, null, 'Sofa văng gỗ sồi bọc vải Linen 3 chỗ tối giản Necom', 'NEST-SF-1027', 'sofa-vang-go-soi-boc-vai-linen-3-cho-toi-gian-necom', 'Sofa văng 3 chỗ khung gỗ sồi bọc vải linen thoáng khí mang phong cách tối giản thanh lịch cho phòng khách gia đình.', 'Sofa văng chế tác từ khung gỗ sồi nguyên khối kết hợp lớp đệm mút D40 bọc vải linen dệt thô mộc mạc. Sản phẩm mang lại cảm giác ngồi êm ái, thoáng khí và có độ đàn hồi vượt trội suốt thời gian dài sử dụng. Thiết kế tay vịn phẳng vuông vức đặc trưng của phong cách Japandi, dễ dàng bố trí cho phòng khách căn hộ hoặc nhà phố khiêm tốn diện tích. Để sofa luôn mới mẻ, gia chủ nên hút bụi định kỳ mỗi tuần, giặt khô vỏ nệm tháo rời và tránh tiếp xúc trực tiếp ánh nắng gay gắt.', 1, 2, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên, mút D40, vải linen"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "180 x 82 x 78 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Ghi sáng", "Be cát", "Xanh rêu"]}], "totalElements": 1}', 38000, 2),
(1028, NOW(), NOW(), null, null, 'Sofa băng đôi vải nỉ boucle tròn trĩnh kiểu Bắc Âu', 'NEST-SF-1028', 'sofa-bang-doi-vai-ni-boucle-tron-trinh-kieu-bac-au', 'Sofa đôi nhỏ gọn bọc nỉ boucle mềm mại bo góc duyên dáng, lý tưởng cho không gian chung cư hiện đại.', 'Mẫu sofa băng đôi sở hữu những đường bo cong mềm mại bọc vải lông xù boucle ấm cúng và chân gỗ dẻ gai thanh lịch. Lớp nệm lò xo túi độc lập êm ru giúp giải tỏa căng thẳng sau một ngày dài làm việc bận rộn. Kích thước nhỏ gọn là lựa chọn hoàn hảo cho phòng khách mini, căn hộ studio hay góc đọc sách lãng mạn. Bạn nên vệ sinh bề mặt lông bằng máy hút bụi đầu chải mềm và lau nhẹ vết bẩn tức thì bằng khăn ẩm thấm xà phòng loãng.', 1, 2, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ dẻ gai, lò xo túi, vải nỉ boucle"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "150 x 78 x 75 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng kem", "Vàng mù tạt"]}], "totalElements": 1}', 32000, 2),
(1029, NOW(), NOW(), null, null, 'Sofa góc chữ l gỗ tần bì đệm rời kháng nước Japandi', 'NEST-SF-1029', 'sofa-goc-chu-l-go-tan-bi-dem-roi-khang-nuoc-japandi', 'Sofa góc L nệm mút D40 bọc vải kháng nước tiện nghi, đem đến phút giây thư giãn trọn vẹn cho cả nhà.', 'Sofa góc L với khung chịu lực bằng gỗ tần bì sấy khô nhập khẩu, bọc nỉ công nghệ kháng thấm nước cao cấp hạn chế bám bẩn. Đệm ngồi hai tầng êm ái mang đến không gian sinh hoạt, ngả lưng xem phim thoải mái cho cả gia đình đông người. Phù hợp tuyệt đối với phòng khách hiện đại, căn hộ duplex rộng thoáng hoặc nhà vườn xanh mát. Bảo quản bằng cách vệ sinh khăn vi sợi, hút bụi thường xuyên và xoay đều gối tựa định kỳ để đệm luôn giữ phom dáng chuẩn.', 1, 2, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tần bì, đệm bọt biển cao cấp, vải sợi kháng nước"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "240 x 155 x 80 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Góc trái - Xám tiêu", "Góc phải - Xám tiêu", "Góc phải - Xanh navy"]}], "totalElements": 1}', 62000, 2),
(1030, NOW(), NOW(), null, null, 'Sofa giường gấp gọn khung thép bọc nỉ phong cách Muji', 'NEST-SF-1030', 'sofa-giuong-gap-gon-khung-thep-boc-ni-phong-cach-muji', 'Sofa giường gấp gọn thông minh chuyển đổi linh hoạt chỉ bằng thao tác kéo trượt nhẹ nhàng và chắc chắn.', 'Sofa giường đa năng tích hợp ray trượt thép carbon sơn tĩnh điện bền bỉ, dễ dàng chuyển đổi từ ghế ngồi sang giường nằm êm ái chỉ trong vài thao tác. Vải nỉ bố sợi dệt mật độ cao chống xù lông, lót nệm mút ép dày nâng đỡ cột sống tối ưu. Sản phẩm là giải pháp cứu cánh thông minh cho phòng khách nhỏ, phòng làm việc kết hợp phòng ngủ phụ khi có khách ghé thăm. Vệ sinh bằng cách tháo lớp bọc ngoài đem giặt và tra dầu bảo dưỡng khớp kim loại sáu tháng một lần.', 1, 2, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Khung thép carbon, mút ép tỷ trọng cao, vải nỉ bố"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "190 x 90 x 82 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Rộng 1m2", "Rộng 1m5"]}], "totalElements": 1}', 42000, 2),
(1031, NOW(), NOW(), null, null, 'Ghế sofa đơn khung gỗ tự nhiên bọc đệm bố thoáng khí', 'NEST-SF-1031', 'ghe-sofa-don-khung-go-tu-nhien-boc-dem-bo-thoang-khi', 'Sofa đơn khung gỗ tự nhiên bọc vải bố dày dặn, hỗ trợ tư thế ngồi thoải mái cho góc đọc sách thư thái.', 'Ghế sofa đơn gây ấn tượng nhờ khung gỗ cao su uốn lượn tinh tế cùng đệm bọc vải bố tự nhiên tạo nét mộc mạc Wabi-Sabi. Góc nghiêng tựa lưng 105 độ tiêu chuẩn tạo điểm tựa thoải mái tuyệt đối cho phần lưng và cổ khi ngồi đọc sách hay thưởng trà. Chiếc ghế thích hợp làm điểm nhấn cho phòng ngủ, phòng khách hoặc góc ban công có mái che. Nên dùng chổi lông mềm phủi bụi nhẹ nhàng, tránh đặt gần nguồn nhiệt cao và lau khung gỗ bằng dầu dưỡng chuyên dụng mỗi năm.', 1, 2, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ cao su tự nhiên, đệm foam D35, vải bố canvas"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "78 x 75 x 74 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu be tự nhiên", "Màu xám tro"]}], "totalElements": 1}', 15000, 2),
(1032, NOW(), NOW(), null, null, 'Sofa văng 3 chỗ bọc da microfiber cao cấp hiện đại', 'NEST-SF-1032', 'sofa-vang-3-cho-boc-da-microfiber-cao-cap-hien-dai', 'Sofa văng da microfiber cao cấp sang trọng, đệm lông vũ êm ái chống bám bẩn hiệu quả cho căn hộ tiện nghi.', 'Sofa da 3 chỗ được phủ lớp da microfiber cao cấp mô phỏng độ mềm mịn của da thật nhưng chống trầy xước và thấm nước vượt bậc. Đệm bọt biển nguyên khối kết hợp lông vũ nhân tạo đem lại trải nghiệm lún êm dịu, không bị xẹp lún sau nhiều năm sử dụng. Ghế tôn vinh vẻ đẹp sang trọng, tinh gọn chuẩn Bắc Âu cho phòng khách rộng hoặc sảnh chờ văn phòng trang nhã. Bạn chỉ cần dùng khăn mềm vắt ráo nước lau sạch bụi bẩn và dùng kem dưỡng bề mặt da chuyên dụng định kỳ.', 1, 2, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Da microfiber, khung gỗ thông, đệm lông vũ nhân tạo"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "210 x 88 x 80 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Hiện đại"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Nâu da bò", "Đen khói", "Xanh rêu đậm"]}], "totalElements": 1}', 52000, 2),
(1033, NOW(), NOW(), null, null, 'Đôn sofa chữ nhật khung gỗ sồi nệm nỉ dày bền bỉ', 'NEST-SF-1033', 'don-sofa-chu-nhat-khung-go-soi-nem-ni-day-ben-bi', 'Ghế đôn sofa khung sồi nệm nỉ êm ái đa năng, vừa làm ghế phụ vừa làm đôn gác chân thư giãn tiện ích.', 'Đôn sofa chữ nhật sở hữu kết cấu khung gỗ sồi Nga vững chắc cùng nệm mút kháng lún bọc nỉ thô bền chắc. Sản phẩm mang lại sự tiện nghi khi vừa làm ghế phụ tiếp khách, đôn gác chân thư giãn hoặc khay để tạp chí gọn gàng. Kiểu dáng tối giản hòa hợp cùng nhiều phong cách nội thất, rất lý tưởng cho phòng khách gia đình, phòng ngủ hay hành lang thay giày. Giữ đôn sạch đẹp bằng cách hút bụi mặt vải mỗi tuần và tránh làm đổ chất lỏng sẫm màu trực tiếp lên bề mặt.', 1, 2, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi Nga, mút D30, vải nỉ thô"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "80 x 50 x 42 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Xám nhạt", "Vàng nghệ"]}], "totalElements": 1}', 9500, 2),
(1034, NOW(), NOW(), null, null, 'Ghế sofa đơn thư giãn bọc da sáp chân gỗ dẻ gai Necom', 'NEST-SF-1034', 'ghe-sofa-don-thu-gian-boc-da-sap-chan-go-de-gai-necom', 'Sofa đơn da sáp chân gỗ dẻ gai bo tròn ấm cúng, nâng đỡ cơ thể hoàn hảo trong từng giây phút nghỉ ngơi.', 'Chiếc sofa đơn thư giãn kết hợp hài hòa khung gỗ dẻ gai cùng chất da sáp mềm mịn mang hơi thở phong trần hoài niệm. Tựa lưng đệm phồng êm ái ôm trọn vóc dáng, giúp thả lỏng cơ thể khi nghe nhạc, đọc sách hay nhâm nhi tách cà phê sớm. Ghế là điểm nhấn đầy cá tính cho góc làm việc tại nhà, phòng ngủ master hay phòng khách mang phong cách Japandi trầm ấm. Bảo dưỡng da bằng sáp chuyên biệt mỗi quý một lần, hạn chế vật sắc nhọn tác động và tránh ánh nắng gay gắt.', 1, 2, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Da sáp dầu cao cấp, khung gỗ dẻ gai, nệm mút đúc"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "76 x 80 x 85 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Nâu caramel", "Nâu đen cổ điển"]}], "totalElements": 1}', 18000, 2),
(1035, NOW(), NOW(), null, null, 'Sofa văng 3 chỗ vải nỉ thô khung gỗ sồi Bắc Âu tối giản', 'NEST-SF-1035', 'sofa-vang-3-cho-vai-ni-tho-khung-go-soi-bac-au-toi-gian', 'Sofa văng 3 chỗ dáng thanh thoát bọc nỉ thô êm ái mang lại nét bình yên cho phòng khách.', 'Vỏ bọc vải nỉ thô sợi dệt chéo thoáng khí kết hợp khung sườn gỗ sồi tự nhiên qua tẩm sấy chống mối mọt. Nệm mút D40 êm ái đàn hồi cao giúp cơ thể thả lỏng tối đa khi tựa lưng trò chuyện hay đọc sách. Thiết kế văng thanh thoát lý tưởng cho phòng khách căn hộ chung cư hoặc nhà phố hiện đại. Để ghế luôn sạch đẹp, bạn nên hút bụi định kỳ hàng tuần bằng đầu chổi mềm và giặt khô vỏ nệm tháo rời khi cần.', 1, 2, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Khung gỗ sồi, mút D40, vải nỉ thô"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "210 x 85 x 78 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu Be Sữa", "Màu Xám Nhạt"]}], "totalElements": 1}', 45000, 2),
(1036, NOW(), NOW(), null, null, 'Sofa góc chữ l bọc vải Linen cao cấp phong cách Japandi', 'NEST-SF-1036', 'sofa-goc-chu-l-boc-vai-linen-cao-cap-phong-cach-japandi', 'Sofa góc chữ L đệm dày êm ái, bọc vải linen mộc mạc tối ưu góc nhà ấm cúng.', 'Khung gỗ dầu chịu lực cao phối nệm lò xo túi êm ái, bọc bên ngoài lớp vải linen dệt thô mộc thấm hút mồ hôi tốt. Kiểu dáng góc chữ L rộng rãi tạo điểm tựa thư giãn thoải mái cho cả gia đình quây quần sau một ngày dài bận rộn. Băng ghế dài thích hợp đặt tại góc phòng khách mở hoặc biệt thự phong cách Bắc Âu. Hãy dùng khăn ẩm lau sạch ngay các vết đổ lỏng và tránh ánh nắng chiếu trực tiếp để vải bền màu.', 1, 2, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Khung gỗ dầu, đệm lò xo túi, vải linen"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "260 x 160 x 82 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Góc Trái Be Cát", "Góc Phải Be Cát"]}], "totalElements": 1}', 68000, 2),
(1037, NOW(), NOW(), null, null, 'Sofa giường đa năng gấp gọn khung thép đệm mút dày dặn', 'NEST-SF-1037', 'sofa-giuong-da-nang-gap-gon-khung-thep-dem-mut-day-dan', 'Sofa giường biến đổi linh hoạt chỉ bằng thao tác kéo gập nhẹ nhàng, tiết kiệm diện tích.', 'Khung thép sơn tĩnh điện chống gỉ sét kết hợp nệm bọt biển mật độ cao đàn hồi tốt không xẹp lún. Thao tác ngả lưng thông minh giúp chuyển đổi từ ghế sofa sang giường nằm êm ái chỉ trong vài giây rất tiện lợi. Đây là giải pháp nội thất lý tưởng cho căn hộ studio, phòng làm việc hoặc phòng ngủ cho khách phụ. Bạn nên vệ sinh bề mặt định kỳ bằng máy hút bụi và tra dầu vào các khớp trượt mỗi năm một lần.', 1, 2, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Khung thép tĩnh điện, đệm bọt biển, vải poly cotton"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "180 x 90 x 80 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Hiện đại"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Rộng 1m2 Xám Đậm", "Rộng 1m5 Xám Đậm"]}], "totalElements": 1}', 38000, 2),
(1038, NOW(), NOW(), null, null, 'Ghế sofa đơn thư giãn bọc vải boucle lông cừu chân gỗ', 'NEST-SF-1038', 'ghe-sofa-don-thu-gian-boc-vai-boucle-long-cuu-chan-go', 'Ghế sofa đơn bọc vải boucle bồng bềnh tựa mây ôm trọn cơ thể khi nghỉ ngơi.', 'Lớp vải dệt boucle mềm mịn như lông cừu bọc trọn phần đệm bọt biển dày dặn, kết hợp chân gỗ tần bì thon gọn vững chãi. Tựa lưng bo cong ôm sát cơ thể mang lại sự thư thái tuyệt vời khi bạn đọc sách, nhâm nhi tách trà sớm. Mẫu ghế đơn này là điểm nhấn trang nhã cho phòng khách nhỏ, phòng ngủ master hay góc thư viện gia đình. Bạn nên chải nhẹ lông vải bằng lược chổi chuyên dụng và lau vết bẩn nhỏ bằng khăn microfiber ẩm.', 1, 2, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải boucle, đệm foam cao cấp, chân gỗ tần bì"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "80 x 75 x 76 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng Kem", "Vàng Nhạt"]}], "totalElements": 1}', 14000, 2),
(1039, NOW(), NOW(), null, null, 'Đôn sofa tròn bọc vải dệt thô chân gỗ tần bì tiện dụng', 'NEST-SF-1039', 'don-sofa-tron-boc-vai-det-tho-chan-go-tan-bi-tien-dung', 'Đôn tròn chân gỗ nhỏ gọn, vừa làm chỗ gác chân vừa làm ghế ngồi phụ thanh lịch.', 'Đôn tròn bọc vải bố dệt sợi đan chắc chắn, nâng đỡ bằng khung gỗ thông và bốn chân gỗ tần bì nguyên khối cứng cáp. Bề mặt đệm nảy nhẹ nhàng đem đến chỗ gác chân thư giãn hoặc làm ghế ngồi phụ linh hoạt khi nhà có khách ghé thăm. Kích thước nhỏ gọn dễ dàng bố trí cạnh sofa chính trong phòng khách hoặc phòng thay đồ ngủ. Giữ vệ sinh đôn bằng cách phủi bụi định kỳ, tránh để chân gỗ tiếp xúc trực tiếp với nước đọng lâu ngày.', 1, 2, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tần bì, gỗ thông, vải bố dệt thô"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "45 x 45 x 42 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu Ghi Xám", "Màu Xanh Cổ Vịt"]}], "totalElements": 1}', 4500, 2),
(1040, NOW(), NOW(), null, null, 'Sofa da bò tiếp xúc 3 chỗ đệm lông vũ phong cách mộc', 'NEST-SF-1040', 'sofa-da-bo-tiep-xuc-3-cho-dem-long-vu-phong-cach-moc', 'Sofa da bò cao cấp êm ái với lớp đệm lông vũ mềm mại tôn vinh vẻ đẹp sang trọng.', 'Lớp da bò tiếp xúc bề mặt mềm mướt được xử lý vân tự nhiên kết hợp lõi đệm lông vũ phối mút xốp êm ái. Càng sử dụng lâu, lớp da càng bóng mịn tạo nên nét đẹp hoài niệm, sang trọng và ấm cúng cho không gian sinh hoạt chung. Sản phẩm hoàn hảo cho phòng khách rộng lớn, căn hộ duplex hay phòng chờ phong cách Wabi-Sabi tinh tế. Bạn nên dưỡng ẩm da định kỳ 6 tháng một lần bằng sáp chuyên dụng và tránh vật sắc nhọn cọ xát.', 1, 2, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Da bò thật tiếp xúc, đệm lông vũ, khung gỗ tràm"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "220 x 92 x 82 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Nâu Bò Cổ Điển", "Nâu Cà Phê Mờ"]}], "totalElements": 1}', 56000, 2),
(1041, NOW(), NOW(), null, null, 'Sofa gỗ sồi tự nhiên 2 chỗ ngồi đệm rời vải bố tối giản', 'NEST-SF-1041', 'sofa-go-soi-tu-nhien-2-cho-ngoi-dem-roi-vai-bo-toi-gian', 'Khung gỗ sồi mộc mạc kèm đệm nỉ rời thông thoáng chuẩn phong cách nội thất Nhật Bản.', 'Khung ghế làm từ gỗ sồi Nga nguyên khối với các đường vân sáng ấm, kèm bộ đệm rời bọc vải bố dày dặn không bai dão. Dáng ghế hai chỗ nhỏ nhắn mang lại tư thế ngồi chuẩn công thái học, giúp nâng đỡ cột sống một cách thư thái và nhẹ nhàng. Phù hợp bày trí trong phòng khách tối giản, góc ban công kính hoặc phòng đọc sách yên tĩnh. Khi bảo quản, bạn chỉ cần tháo vỏ áo đệm để giặt phơi ở nơi thoáng gió và lau khung gỗ bằng khăn mềm.', 1, 2, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên, đệm mút ép, vải bố cotton"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "150 x 78 x 75 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Đệm Xám Tro", "Đệm Xanh Rêu"]}], "totalElements": 1}', 29000, 2),
(1042, NOW(), NOW(), null, null, 'Ghế bành sofa đơn khung gỗ uốn tựa mây đan chuẩn Japandi', 'NEST-SF-1042', 'ghe-banh-sofa-don-khung-go-uon-tua-may-dan-chuan-japandi', 'Ghế sofa đơn tựa lưng mây mắt cáo kết hợp đệm ngồi êm dịu cho không gian thư thái.', 'Khung gỗ uốn cong mềm mại theo kỹ thuật hơi nước, lưng tựa đan mây mắt cáo thủ công thoáng khí kèm đệm lót nỉ êm dịu. Sự phối hợp mộc mạc giữa mây và gỗ tạo cảm giác an yên, xoa dịu mệt mỏi mỗi khi bạn ngả lưng nghỉ ngơi. Ghế là điểm nhấn đầy chất thơ cho góc ban công, phòng khách Japandi hay phòng ngủ ấm cúng. Tránh đặt ghế ở nơi có độ ẩm quá cao và vệ sinh mắt mây bằng chổi lông mềm nhẹ nhàng.', 1, 2, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tần bì uốn nhiệt, mây tự nhiên, nệm vải nỉ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "72 x 70 x 74 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Gỗ Tự Nhiên Nệm Be", "Gỗ Lau Dầu Óc Chó Nệm Be"]}], "totalElements": 1}', 11000, 2),
(1043, NOW(), NOW(), null, null, 'Sofa văng 2 chỗ bọc vải nhung tăm chân gỗ tần bì ấm cúng', 'NEST-SF-1043', 'sofa-vang-2-cho-boc-vai-nhung-tam-chan-go-tan-bi-am-cung', 'Sofa văng 2 chỗ bọc vải nhung tăm ấm áp kết hợp chân gỗ tần bì tự nhiên, mang nét đẹp thanh lịch chuẩn Bắc Âu.', 'Chiếc sofa văng 2 chỗ sở hữu khung gỗ tần bì đã sấy khô chống mối mọt kết hợp lớp đệm mút nguyên khối êm ái chống xẹp lún. Bề mặt bọc vải nhung tăm dày dặn, sờ êm mịn và thoáng khí, mang lại trải nghiệm thư giãn ấm áp khi đọc sách hay xem phim. Kiểu dáng gọn gàng cùng tông màu trang nhã đặc biệt lý tưởng cho phòng khách chung cư hoặc phòng làm việc nhỏ gọn. Bạn nên hút bụi thường xuyên bằng đầu chổi mềm và lau sạch vết bẩn bằng khăn ẩm vắt khô.', 1, 2, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Khung gỗ tần bì tự nhiên, đệm mút D40, vải nhung tăm cao cấp"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 82 x 78 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu Be Sữa", "Màu Xanh Rêu Nhạt", "Màu Nâu Đất"]}], "totalElements": 1}', 32000, 2),
(1044, NOW(), NOW(), null, null, 'Ghế đôn sofa chữ nhật đệm dày khung gỗ sồi tự nhiên', 'NEST-SF-1044', 'ghe-don-sofa-chu-nhat-dem-day-khung-go-soi-tu-nhien', 'Đôn sofa chữ nhật đệm dày êm ái bọc vải bố thô mộc, vừa làm ghế phụ vừa kê chân tiện lợi cho phòng khách Japandi.', 'Ghế đôn sofa chữ nhật được chế tác từ khung gỗ sồi tự nhiên chắc chắn kết hợp lớp đệm mút đàn hồi cao bọc vải bố dệt thô mộc mạc. Thiết kế thanh thoát với các góc bo tròn nhẹ nhàng, mang lại cảm giác an toàn và thoải mái tối đa khi sử dụng làm ghế ngồi phụ hoặc đôn gác chân thư giãn. Sản phẩm phù hợp bài trí tại phòng khách, sảnh chờ hay chân giường ngủ. Để duy trì độ bền, hãy định kỳ hút bụi nhẹ nhàng và tránh để nước đọng lâu trên bề mặt.', 1, 2, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên, đệm mút foam, vải bố dệt thô"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "80 x 45 x 42 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu Be Cát", "Màu Xám Tro"]}], "totalElements": 1}', 8500, 2),
(1045, NOW(), NOW(), null, null, 'Kệ tivi gỗ sồi cánh nan trượt tối giản phong cách Japandi', 'NEST-TK-1045', 'ke-tivi-go-soi-canh-nan-truot-toi-gian-phong-cach-japandi', 'Kệ tivi gỗ sồi tự nhiên với hệ cánh lùa nan gỗ thanh lịch, tối ưu không gian giải trí cho phòng khách.', 'Sản phẩm chế tác từ gỗ sồi tự nhiên nhập khẩu kết hợp lớp phủ sơn lau dầu mờ tôn vân gỗ ấm áp. Thiết kế cánh trượt nan dọc giúp cất giấu thiết bị gọn gàng mà không cản sóng điều khiển từ xa. Khoang chứa đồ rộng rãi cùng lỗ luồn dây điện thông minh giữ mặt kệ luôn ngăn nắp. Rất thích hợp cho phòng khách chung cư phong cách Japandi hoặc Bắc Âu. Bảo quản bằng khăn ẩm mềm và tránh tiếp xúc ánh nắng gắt.', 1, 3, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên (White Oak)"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 40 x 50 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dài 1m6 - Tự nhiên", "Dài 1m8 - Tự nhiên"]}], "totalElements": 1}', 28000, 2),
(1046, NOW(), NOW(), null, null, 'Kệ sách đứng nhiều tầng gỗ cao su khung bậc thang tối giản', 'NEST-TK-1046', 'ke-sach-dung-nhieu-tang-go-cao-su-khung-bac-thang-toi-gian', 'Kệ sách đứng bậc thang thoáng đãng giúp bài trí sách và phụ kiện decor nhẹ nhàng tinh tế.', 'Chiếc kệ được đóng bằng gỗ cao su xuất khẩu đã qua sấy chống mối mọt cong vênh hiệu quả. Cấu trúc mở dạng bậc thang bậc tiến tạo cảm giác thông thoáng cho căn phòng mà vẫn chịu tải ấn tượng. Từng đợt gỗ được gia công nhẵn mịn, bo nhẹ góc cạnh an toàn tuyệt đối. Món đồ hoàn hảo cho phòng làm việc, góc đọc sách hoặc làm vách ngăn mở trong căn hộ studio. Vệ sinh định kỳ bằng chổi lông gà hoặc khăn khô sạch.', 1, 3, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ cao su tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "80 x 32 x 150 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu gỗ tự nhiên", "Màu nâu hạt dẻ"]}], "totalElements": 1}', 16000, 2),
(1047, NOW(), NOW(), null, null, 'Tủ đầu giường gỗ tần bì ngăn kéo mây mắt cáo Bắc Âu Necom', 'NEST-TK-1047', 'tu-dau-giuong-go-tan-bi-ngan-keo-may-mat-cao-bac-au-necom', 'Tủ tab đầu giường nhỏ gọn với điểm nhấn mặt mây đan mộc mạc, tiện dụng cho góc nghỉ ngơi.', 'Mẫu tab đầu giường sở hữu khung gỗ tần bì chắc chắn kết hợp mặt hộc kéo đan mây tự nhiên kiểu mắt cáo thông thoáng. Thiết kế một ngăn kéo đóng êm cùng kệ hở phía dưới cho phép lưu trữ sách đọc dở, đồng hồ hay đèn ngủ gọn gàng. Sản phẩm mang lại xúc cảm thư thái, đậm chất Wabi-Sabi mộc mạc cho phòng ngủ hiện đại. Lau chùi bụi bẩn bằng khăn ẩm vắt khô, tránh để chất lỏng đọng lâu trên bề mặt mây.', 1, 3, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tần bì, mây mắt cáo tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "45 x 38 x 52 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu gỗ sồi sáng", "Màu nâu óc chó"]}], "totalElements": 1}', 8500, 2),
(1048, NOW(), NOW(), null, null, 'Tủ giày cửa lật siêu mỏng gỗ công nghiệp phủ melamine Muji', 'NEST-TK-1048', 'tu-giay-cua-lat-sieu-mong-go-cong-nghiep-phu-melamine-muji', 'Tủ để giày dép thông minh cánh lật giúp tiết kiệm diện tích tối đa cho tiền sảnh hẹp.', 'Tủ giày thiết kế thông minh với hệ cánh lật đa tầng giúp sức chứa lên đến mười lăm đôi giày dù chiều sâu chỉ hẹp hai mươi tư centimet. Bề mặt phủ melamine kháng ẩm, chống trầy xước và bám bẩn vượt trội, dễ dàng lau sạch sau ngày mưa. Màu sắc tao nhã cùng tay nắm vát âm tối giản giúp lối vào nhà luôn thanh thoát, ngăn nắp chuẩn phong cách Nhật. Chỉ cần vệ sinh mặt tủ bằng khăn ẩm mềm và giữ khu vực thông gió tốt.', 1, 3, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ MDF lõi xanh chống ẩm phủ Melamine"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "80 x 24 x 118 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["2 tầng - Rộng 80cm", "3 tầng - Rộng 80cm"]}], "totalElements": 1}', 22000, 2),
(1049, NOW(), NOW(), null, null, 'Tủ trưng bày hai cánh kính gân khung gỗ tần bì hiện đại', 'NEST-TK-1049', 'tu-trung-bay-hai-canh-kinh-gan-khung-go-tan-bi-hien-dai', 'Tủ kính đứng tinh tế lưu trữ ly chén, đồ gốm sứ sang trọng và ngăn ngừa bụi hiệu quả.', 'Chiếc tủ tạo ấn tượng sâu sắc nhờ kết cấu gỗ tần bì dẻo dai kết hợp hai cánh kính sọc mờ tạo hiệu ứng thị giác nửa kín nửa hở sang trọng. Bên trong chia ba tầng đợt chịu lực cao, lý tưởng trưng bày bộ sưu tập đồ gốm, ly rượu hoặc sách nghệ thuật quý giá. Sản phẩm mang lại vẻ đẹp đương đại thanh lịch cho phòng ăn lẫn phòng khách. Để giữ thẩm mỹ, nên xịt nước lau kính chuyên dụng và tránh va đập mạnh lên cánh tủ.', 1, 3, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tần bì tự nhiên, kính sọc cường lực"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "90 x 40 x 140 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu gỗ Ash sáng", "Màu nâu Walnut"]}], "totalElements": 1}', 36000, 2),
(1050, NOW(), NOW(), null, null, 'Kệ treo tường thanh ngang gỗ dẻ gai bo cạnh tối giản JYSK', 'NEST-TK-1050', 'ke-treo-tuong-thanh-ngang-go-de-gai-bo-canh-toi-gian-jysk', 'Kệ gắn tường thanh ngang tối giản giúp tận dụng diện tích và tạo điểm nhấn decor sinh động.', 'Kệ thanh ngang làm từ gỗ dẻ gai đặc khối với đường phay bo cong mềm mại ở viền, toát lên tinh thần thủ công mộc mạc. Hệ ngàm bas âm tường bằng kim loại cứng cáp giấu kín hoàn toàn, cho cảm giác chiếc kệ lơ lửng nhẹ nhàng trên mảng tường trống. Phù hợp đặt khung ảnh lưu niệm, nến thơm, chậu sen đá nhỏ tại phòng khách, hành lang hoặc phòng ngủ. Khi dùng chỉ cần lau nhẹ bằng khăn khô và không đặt vật quá tải trọng cho phép.', 1, 3, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ dẻ gai (Beech) tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "80 x 18 x 4 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Chiều dài 60cm", "Chiều dài 80cm", "Chiều dài 100cm"]}], "totalElements": 1}', 2800, 2),
(1051, NOW(), NOW(), null, null, 'Tủ ngăn kéo gỗ sồi 4 tầng tay cầm khoét âm phong cách mộc', 'NEST-TK-1051', 'tu-ngan-keo-go-soi-4-tang-tay-cam-khoet-am-phong-cach-moc', 'Tủ ngăn kéo 4 tầng rộng rãi giúp phân loại trang phục và vật dụng gọn gàng, tiện lợi.', 'Mẫu tủ gồm bốn ngăn kéo rộng rãi sử dụng ray trượt kim loại giảm chấn êm ái, đóng mở nhẹ nhàng không gây tiếng ồn. Thân tủ gia công từ gỗ sồi Mỹ tuyển chọn kỹ lưỡng, đường vân uốn lượn sắc nét cùng các mép vát âm thay thế tay nắm truyền thống. Khả năng cất trữ quần áo gấp, tài liệu hay phụ kiện sinh hoạt cực kỳ tiện ích cho phòng ngủ. Bảo quản tủ ở nơi khô thoáng, tránh kéo giật mạnh khi ngăn chứa đã đầy ắp đồ đạc.', 1, 3, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi trắng tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "85 x 45 x 105 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Mộc mạc"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu mộc tự nhiên", "Màu nâu hun khói"]}], "totalElements": 1}', 34000, 2),
(1052, NOW(), NOW(), null, null, 'Kệ để đồ khung thép mặt gỗ thông ghép thanh kiểu công nghiệp nhẹ', 'NEST-TK-1052', 'ke-de-do-khung-thep-mat-go-thong-ghep-thanh-kieu-cong-nghiep-nhe', 'Kệ mở đa năng khung thép thanh mảnh chịu lực tốt, tối ưu góc bếp hay ban công có mái che.', 'Sự hòa quyện giữa khung thép sơn tĩnh điện màu đen mờ và các đợt gỗ thông tự nhiên mang lại vẻ đẹp phóng khoáng, hiện đại. Khoảng cách giữa các tầng thoáng đãng, mặt kệ chịu lực cao thích hợp đặt lò vi sóng, chậu cây cảnh hoặc bình nước uống. Món đồ linh hoạt cho căn bếp mở, góc ban công hay phòng sinh hoạt chung nhỏ gọn. Cần vệ sinh bề mặt định kỳ bằng giẻ khô và kiểm tra siết lại ốc vít định vị sau thời gian dài sử dụng.', 1, 3, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Khung thép sơn tĩnh điện, mặt gỗ thông ghép"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "70 x 35 x 120 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Hiện đại"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "bếp"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Khung Đen Mặt Gỗ Tự Nhiên", "Khung Trắng Mặt Gỗ Sáng"]}], "totalElements": 1}', 14500, 2),
(1053, NOW(), NOW(), null, null, 'Kệ tivi gỗ tần bì treo tường bo tròn phong cách Bắc Âu', 'NEST-TK-1053', 'ke-tivi-go-tan-bi-treo-tuong-bo-tron-phong-cach-bac-au', 'Kệ tivi gắn tường bo góc an toàn giúp tiết kiệm tối đa diện tích sàn và tạo vẻ đẹp thanh lịch.', 'Sản phẩm gia công từ gỗ tần bì nhập khẩu kết hợp cốt chống ẩm phủ veneer cao cấp, sở hữu đường cong bo viền mềm mại an toàn. Thiết kế gắn tường giải phóng sàn nhà, mang lại cảm giác rộng rãi thoáng đãng cho tổ ấm nhỏ. Tủ chia hộc khoa học để đầu thu hoặc phụ kiện giải trí tiện lợi. Phù hợp hoàn hảo cho phòng khách hiện đại hoặc phòng ngủ chung cư. Khi sử dụng chỉ cần lau khăn ẩm mềm định kỳ và tránh treo quá tải trọng quy định.', 1, 3, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tần bì tự nhiên và ván MDF chống ẩm phủ veneer ash"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 35 x 25 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dài 160 cm", "Dài 180 cm"]}], "totalElements": 1}', 22000, 2),
(1054, NOW(), NOW(), null, null, 'Kệ sách gỗ sồi 5 tầng phối khung tròn tối giản Japandi', 'NEST-TK-1054', 'ke-sach-go-soi-5-tang-phoi-khung-tron-toi-gian-japandi', 'Kệ sách đứng năm tầng thanh thoát bằng gỗ sồi tự nhiên mang đến vẻ đẹp gọn gàng cho góc đọc.', 'Kệ sách năm tầng chế tác từ gỗ sồi tự nhiên bền chắc, phủ lớp sơn lau sinh học an toàn giữ trọn vân gỗ sáng màu mộc mạc. Thiết kế thanh thoát với khung bo tròn tinh tế mang đến nét yên ả, ấm cúng và ngăn nắp cho góc học tập. Sản phẩm đáp ứng nhu cầu lưu trữ sách vở, chậu cây nhỏ xinh tại phòng làm việc hoặc phòng khách Japandi. Nên kê kệ ở nơi khô ráo, tránh ánh nắng chiếu trực tiếp và lau chùi bụi bẩn bằng khăn khô.', 1, 3, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi trắng tự nhiên phủ sơn lau gốc dầu"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "80 x 30 x 175 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu gỗ tự nhiên", "Màu nâu óc chó"]}], "totalElements": 1}', 26000, 2),
(1055, NOW(), NOW(), null, null, 'Tủ đầu giường tròn gỗ sồi một ngăn kéo tối giản Necom', 'NEST-TK-1055', 'tu-dau-giuong-tron-go-soi-mot-ngan-keo-toi-gian-necom', 'Tủ đầu giường dáng tròn mềm mại với ngăn kéo ẩn kín đáo cho không gian nghỉ ngơi thư thái.', 'Tủ đầu giường hình trụ tròn độc đáo được tiện thủ công từ gỗ sồi nguyên khối, mang nét tối giản đậm chất thiền định. Bề mặt gỗ láng mịn tạo cảm giác chạm êm dịu mỗi khi với tay đặt đèn ngủ hay cuốn sách đọc dở trước giờ ngủ. Ngăn kéo trượt trơn tru kín đáo giúp cất giữ vật dụng cá nhân gọn gàng. Chiếc tủ rất ăn nhập không gian phòng ngủ phong cách Wabi-Sabi hoặc Bắc Âu. Bảo quản dễ dàng bằng việc hạn chế tiếp xúc nước đọng lâu.', 1, 3, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên nguyên khối hoàn thiện sáp mờ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "42 x 42 x 50 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Gỗ sồi tự nhiên", "Gỗ sồi lau dầu nâu"]}], "totalElements": 1}', 8500, 2),
(1056, NOW(), NOW(), null, null, 'Tủ giày cánh lam gỗ cao su xuất khẩu thông thoáng Nhà Xinh', 'NEST-TK-1056', 'tu-giay-canh-lam-go-cao-su-xuat-khau-thong-thoang-nha-xinh', 'Tủ để giày dép cánh nan thoáng khí giữ cho tiền sảnh luôn thơm tho và ngăn nắp tinh tế.', 'Tủ giày chế tác từ gỗ cao su tự nhiên tuyển chọn, nổi bật với hệ lam gỗ song song giúp lưu thông không khí hiệu quả, loại bỏ mùi ẩm mốc khó chịu. Kiểu dáng thanh lịch mang lại cảm giác chỉn chu, tươi sáng ngay từ tiền sảnh khi vừa bước chân về nhà. Kệ phân tầng chịu lực tốt, chứa được nhiều đôi giày dép và hộp phụ kiện gọn gàng. Phù hợp cho hành lang, lối vào căn hộ chung cư. Bạn nên vệ sinh lòng tủ hàng tháng và giữ lối vào luôn thông thoáng.', 1, 3, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ cao su tự nhiên đã qua xử lý sấy khô phủ PU"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "100 x 35 x 100 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["2 cánh rộng 80 cm", "3 cánh rộng 110 cm"]}], "totalElements": 1}', 28000, 2),
(1057, NOW(), NOW(), null, null, 'Tủ trưng bày gỗ dẻ gai cánh kính vòm đậm chất wabi sabi', 'NEST-TK-1057', 'tu-trung-bay-go-de-gai-canh-kinh-vom-dam-chat-wabi-sabi', 'Tủ trưng bày vòm cong duyên dáng kết hợp kính trong suốt lưu giữ trọn vẹn nét đẹp kỷ vật.', 'Được chế tác từ gỗ dẻ gai cao cấp cùng cánh kính uốn vòm duyên dáng, chiếc tủ toát lên vẻ đẹp thanh lịch vượt thời gian. Bề mặt mộc mạc đem lại cảm giác bình yên, tôn vinh những món đồ gốm sứ, ly tách hay kỷ vật sưu tầm bên trong. Tủ chia khoang rộng rãi phù hợp đặt tại phòng khách sang trọng hoặc khu vực bàn ăn gia đình. Để giữ vẻ đẹp trong suốt và sáng bóng, bạn nên vệ sinh mặt kính bằng nước lau chuyên dụng cùng khăn sợi mềm.', 1, 3, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ dẻ gai tự nhiên kết hợp kính cường lực trong suốt"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "90 x 40 x 180 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu be mộc", "Màu nâu trầm"]}], "totalElements": 1}', 45000, 2),
(1058, NOW(), NOW(), null, null, 'Kệ treo tường đa năng khung thép sơn tĩnh điện đợt gỗ sồi', 'NEST-TK-1058', 'ke-treo-tuong-da-nang-khung-thep-son-tinh-dien-dot-go-soi', 'Kệ thanh treo tường phối khung kim loại thanh mảnh giúp biến mảng tường trống thành góc thơ mộng.', 'Hệ kệ treo tường là sự kết hợp ăn ý giữa khung thép sơn tĩnh điện đen mờ và các đợt ngang bằng gỗ sồi tự nhiên chắc chắn. Kết cấu hình học tối giản mang lại cảm giác hiện đại, phóng khoáng, giúp tận dụng tối đa khoảng trống trên mảng tường đơn điệu. Kệ thích hợp trang trí tranh ảnh, tinh dầu thơm hoặc sách nhỏ ở phòng làm việc, phòng ngủ và góc thư giãn. Khi lắp đặt cần bắn vít chắc chắn vào tường bê tông và lau bụi bằng chổi lông mềm định kỳ.', 1, 3, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Khung thép sơn tĩnh điện và đợt gỗ sồi tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "80 x 20 x 70 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Khung đen đợt gỗ sáng", "Khung trắng đợt gỗ sáng"]}], "totalElements": 1}', 5500, 2),
(1059, NOW(), NOW(), null, null, 'Tủ ngăn kéo gỗ tần bì 6 hộc chân thon phong cách Bắc Âu', 'NEST-TK-1059', 'tu-ngan-keo-go-tan-bi-6-hoc-chan-thon-phong-cach-bac-au', 'Tủ hộc kéo sáu ngăn phân chia đồ dùng khoa học, chân cao tạo cảm giác nhẹ nhàng cho phòng ngủ.', 'Tủ ngăn kéo gồm sáu hộc chứa tiện nghi chế tác từ gỗ tần bì sáng màu, trang bị hệ ray trượt giảm chấn đóng mở êm ái không gây ồn. Thiết kế chân thon vát tạo độ cao thoáng gầm, đem lại cảm giác thanh thoát và dễ dàng vệ sinh sàn nhà. Chiếc tủ giải quyết hoàn hảo nhu cầu sắp xếp quần áo, chăn ga cho phòng ngủ hoặc phòng thay đồ gia đình. Để duy trì tuổi thọ gỗ, hãy hạn chế đặt đồ nóng trực tiếp lên mặt tủ và giữ phòng có độ ẩm vừa phải.', 1, 3, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tần bì tự nhiên kết hợp ray trượt kim loại giảm chấn"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "120 x 45 x 85 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu gỗ tự nhiên", "Màu trắng kem viền gỗ"]}], "totalElements": 1}', 38000, 2),
(1060, NOW(), NOW(), null, null, 'Tủ sideboard gỗ sồi cánh lùa mây đan thủ công Japandi mộc', 'NEST-TK-1060', 'tu-sideboard-go-soi-canh-lua-may-dan-thu-cong-japandi-moc', 'Tủ búp phê cánh lùa mây đan tự nhiên đa năng cho phòng ăn và phòng khách ấm cúng mộc mạc.', 'Tủ sideboard làm từ gỗ sồi tự nhiên kết hợp cánh lùa bằng mây đan thủ công tỉ mỉ, mang hơi thở thiên nhiên mộc mạc vào không gian sống. Cảm giác trượt mở êm nhẹ cùng mùi hương gỗ dịu nhẹ tạo sự thư thái tuyệt vời khi sử dụng mỗi ngày. Sản phẩm đa năng vừa làm tủ bát đĩa phòng ăn, vừa làm tủ trang trí lối vào căn hộ phong cách Japandi. Vệ sinh nan mây bằng máy hút bụi mini đầu cọ mềm và dùng khăn sạch lau mặt gỗ.', 1, 3, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên kết hợp mây mắt cáo đan thủ công"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "140 x 40 x 80 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dài 140 cm", "Dài 160 cm"]}], "totalElements": 1}', 35000, 2),
(1061, NOW(), NOW(), null, null, 'Kệ sách gỗ dẻ gai chia ô bất đối xứng Bắc Âu Necom', 'NEST-TK-1061', 'ke-sach-go-de-gai-chia-o-bat-doi-xung-bac-au-necom', 'Kệ sách gỗ dẻ gai với kết cấu chia ô so le tinh tế mang lại điểm nhấn thanh lịch cho góc đọc sách.', 'Kệ sách được chế tác từ gỗ dẻ gai tự nhiên nhập khẩu, bề mặt xử lý dầu lau thực vật an toàn giúp giữ nguyên vân gỗ mịn màng ấm áp. Thiết kế các khoang chứa so le bất đối xứng tạo cảm giác thanh thoát, dễ dàng bài trí sách vở hay các vật phẩm decor yêu thích. Sản phẩm rất phù hợp cho phòng khách gia đình, phòng làm việc hoặc góc thư giãn phong cách Bắc Âu. Để giữ sản phẩm luôn sáng đẹp, bạn nên dùng khăn microfiber khô lau sạch bụi định kỳ và tránh đặt kệ nơi ẩm thấp.', 1, 3, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ dẻ gai tự nhiên (Beech wood)"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "80 x 30 x 165 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Gỗ tự nhiên", "Sơn trắng phối gỗ"]}], "totalElements": 1}', 22000, 2),
(1062, NOW(), NOW(), null, null, 'Kệ tivi gỗ sồi cửa lùa lam dọc chân kim loại Japandi', 'NEST-TK-1062', 'ke-tivi-go-soi-cua-lua-lam-doc-chan-kim-loai-japandi', 'Kệ tivi gỗ sồi tự nhiên với hệ cánh lùa nan dọc tinh xảo tạo cảm giác gọn gàng và thoáng đãng.', 'Chiếc kệ tivi kết hợp hài hòa giữa chất liệu gỗ sồi tự nhiên cứng cáp và phần chân kim loại sơn tĩnh điện thanh mảnh. Mặt cánh lùa dạng thanh lam dọc vừa tạo hiệu ứng thị giác đậm chất thiền Japandi vừa hỗ trợ thoát nhiệt hiệu quả cho các thiết bị điện tử bên trong. Món đồ nội thất này là điểm nhấn hoàn hảo cho không gian phòng khách hiện đại hoặc căn hộ chung cư. Khi sử dụng, hãy lau bụi thường xuyên bằng khăn mềm và tránh kéo lê các vật sắc nhọn trên mặt gỗ.', 1, 3, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi trắng tự nhiên, chân thép sơn tĩnh điện"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 40 x 50 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dài 160 cm", "Dài 180 cm"]}], "totalElements": 1}', 28000, 2),
(1063, NOW(), NOW(), null, null, 'Tủ đầu giường hai hộc kéo gỗ sồi chân vát kiểu Bắc Âu', 'NEST-TK-1063', 'tu-dau-giuong-hai-hoc-keo-go-soi-chan-vat-kieu-bac-au', 'Tủ đầu giường gỗ sồi hai hộc kéo tiện lợi, thiết kế chân vát thanh thoát cho phòng ngủ ấm cúng.', 'Tủ đầu giường sở hữu đường nét tối giản với hai ngăn kéo chứa đồ rộng rãi, ray trượt giảm chấn êm ái không gây tiếng ồn trong đêm tĩnh mịch. Chất liệu gỗ sồi tự nhiên mang đến sắc thái mộc mạc, đường vân uốn lượn nhẹ nhàng tạo cảm giác thư thái và an yên cho giấc ngủ. Món đồ rất thích hợp đặt cạnh giường ngủ phong cách Scandinavian hoặc căn hộ tối giản. Bạn chỉ cần lau bề mặt bằng khăn ẩm vắt ráo và hạn chế để cốc nước đọng trực tiếp lên mặt tủ.', 1, 3, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên (White Oak)"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "45 x 40 x 52 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu sồi tự nhiên", "Màu nâu walnut"]}], "totalElements": 1}', 9500, 2),
(1064, NOW(), NOW(), null, null, 'Tủ giày đa năng 3 cánh gỗ sồi kết hợp đệm ngồi thay giày', 'NEST-TK-1064', 'tu-giay-da-nang-3-canh-go-soi-ket-hop-dem-ngoi-thay-giay', 'Tủ để giày dép tích hợp đệm nỉ êm ái giúp việc thay giày mỗi ngày trở nên tiện nghi và thư thái.', 'Sản phẩm là sự kết hợp khéo léo giữa hệ tủ giày ba cánh chứa đồ tiện lợi và ghế ngồi bọc đệm êm ái ở tiền sảnh. Khung tủ gia công từ gỗ sồi tự nhiên phủ sơn PU mờ kháng ẩm, các đợt chia ngăn có thể điều chỉnh độ cao linh hoạt cho nhiều loại giày dép. Thiết kế tối ưu hóa diện tích lối ra vào cho nhà phố hoặc chung cư Japandi. Để bảo quản bền lâu, nên tháo vỏ đệm giặt định kỳ và lau chùi các ngăn đựng bằng khăn khô ráo.', 1, 3, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên, nệm bọc vải bố"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "110 x 35 x 70 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dài 100 cm", "Dài 120 cm"]}], "totalElements": 1}', 26000, 2),
(1065, NOW(), NOW(), null, null, 'Tủ trưng bày đứng gỗ tần bì kính trong suốt tối giản', 'NEST-TK-1065', 'tu-trung-bay-dung-go-tan-bi-kinh-trong-suot-toi-gian', 'Tủ trưng bày kính trong suốt viền gỗ tần bì thanh lịch giúp tôn vinh vẻ đẹp bộ sưu tập quý giá.', 'Tủ trưng bày đứng được chế tác từ khung gỗ tần bì chọn lọc kết hợp cùng hệ kính cường lực trong suốt bốn bề, tối ưu ánh sáng tự nhiên cho từng món đồ lưu niệm. Các mối nối mộng truyền thống đảm bảo độ chịu lực vững chãi và thẩm mỹ mộc mạc tinh tế. Đây là lựa chọn lý tưởng cho phòng khách gia đình, phòng làm việc hoặc studio phong cách Wabi-Sabi. Bạn nên dùng nước lau kính chuyên dụng cho phần kính và dùng sáp ong dưỡng bề mặt gỗ nửa năm một lần.', 1, 3, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tần bì tự nhiên, kính cường lực"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "75 x 40 x 170 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Gỗ sồi sáng", "Gỗ óc chó sẫm"]}], "totalElements": 1}', 34000, 2),
(1066, NOW(), NOW(), null, null, 'Kệ treo tường dây treo da thật mặt gỗ tần bì Bắc Âu', 'NEST-TK-1066', 'ke-treo-tuong-day-treo-da-that-mat-go-tan-bi-bac-au', 'Kệ treo tường đợt gỗ tần bì kết hợp quai da thật mang hơi thở Scandinavia tinh tế và hiện đại.', 'Chiếc kệ tạo ấn tượng độc đáo nhờ sự kết hợp giữa đợt gỗ tần bì nguyên khối và cặp dây treo bằng da bò thuộc tự nhiên cao cấp. Thiết kế thanh thoát giúp tận dụng tối đa khoảng trống trên mảng tường đơn điệu để trưng bày chậu cây nhỏ, nến thơm hay tranh ảnh kỷ niệm. Kệ hòa hợp tuyệt vời trong phòng ngủ, góc học tập hoặc quán cà phê nhỏ. Khi sử dụng, hãy lưu ý bắt vít tắc kê chắc chắn vào tường gạch và dùng khăn mềm khô để vệ sinh nhẹ nhàng.', 1, 3, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tần bì nguyên khối, dây da bò tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "60 x 20 x 2.5 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dài 60 cm", "Dài 80 cm"]}], "totalElements": 1}', 2100, 2),
(1067, NOW(), NOW(), null, null, 'Tủ ngăn kéo gỗ cao su 5 tầng tay nắm tròn mộc mạc', 'NEST-TK-1067', 'tu-ngan-keo-go-cao-su-5-tang-tay-nam-tron-moc-mac', 'Tủ ngăn kéo 5 tầng bằng gỗ cao su gọn gàng, giải pháp lưu trữ đồ đạc tiện dụng cho không gian nhỏ.', 'Mẫu tủ ngăn kéo đứng gồm năm tầng hộc rộng rãi, tay nắm tiện tròn thân thiện giúp việc sắp xếp quần áo hay phụ kiện trở nên ngăn nắp hơn bao giờ hết. Chất liệu gỗ cao su tự nhiên qua xử lý tẩm sấy kỹ lưỡng, chống cong vênh và kháng mối mọt rất tốt trong điều kiện khí hậu nhiệt đới. Tủ cực kỳ thích hợp cho phòng ngủ trẻ em, phòng thay đồ hoặc phòng ngủ chung cư hiện đại. Bạn chỉ cần lau dọn bụi bẩn hàng tuần và tránh đặt tủ sát vách tường ẩm ướt.', 1, 3, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ cao su tự nhiên ghép thanh phủ veneer"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "60 x 42 x 105 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Mộc mạc"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu gỗ mộc", "Màu trắng ấm"]}], "totalElements": 1}', 27000, 2),
(1068, NOW(), NOW(), null, null, 'Tủ búp phê phòng ăn gỗ sồi cánh kính mờ phong cách mộc', 'NEST-TK-1068', 'tu-bup-phe-phong-an-go-soi-canh-kinh-mo-phong-cach-moc', 'Tủ búp phê gỗ sồi cánh kính mờ trang nhã, nơi lưu trữ chén đĩa và đồ gia dụng phòng ăn gọn gàng.', 'Tủ búp phê sở hữu khoang chứa rộng lớn với cánh cửa kính mờ gân sóng mờ ảo, vừa che khéo đồ đạc bên trong vừa tạo nét cổ điển trang nhã. Khung thân tủ làm từ gỗ sồi tự nhiên màu sáng với các góc cạnh vát nhẹ tinh tế, an toàn khi sử dụng hàng ngày. Sản phẩm đặc biệt thích hợp cho phòng ăn ấm cúng hoặc không gian mở liên thông phòng khách phong cách Japandi. Để bảo dưỡng tốt nhất, hãy vệ sinh định kỳ bằng khăn ấm mềm và tránh để dầu mỡ bám dính lâu ngày.', 1, 3, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên, kính gân mờ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "120 x 42 x 82 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dài 120 cm", "Dài 150 cm"]}], "totalElements": 1}', 39000, 2),
(1069, NOW(), NOW(), null, null, 'Đèn thả trần chao giấy wabi sabi Necom khung kim loại', 'NEST-DE-1069', 'den-tha-tran-chao-giay-wabi-sabi-necom-khung-kim-loai', 'Đèn thả trần chất liệu giấy thủ công mang ánh sáng ấm áp dịu nhẹ cho gian phòng ấm cúng.', 'Đèn thả trần được tạo tác từ khung kim loại bọc giấy thủ công cao cấp, mang lại hiệu ứng ánh sáng khuếch tán dịu mắt và ấm cúng. Thiết kế phom dáng hữu cơ bất đối xứng đậm chất Wabi Sabi, gợi vẻ đẹp tĩnh tại và an yên cho tổ ấm. Sản phẩm cực kỳ phù hợp treo bàn ăn, phòng khách hoặc góc thiền thư giãn. Bảo quản dễ dàng bằng cách dùng chổi lông mềm quét bụi định kỳ và tránh treo nơi ẩm ướt để giữ độ bền lâu dài.', 1, 4, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Khung thép tĩnh điện, giấy thủ công chống cháy mờ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "50 x 50 x 35 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Đường kính 40cm", "Đường kính 50cm", "Đường kính 60cm"]}], "totalElements": 1}', 1200, 1),
(1070, NOW(), NOW(), null, null, 'Đèn cây đứng phòng khách thân gỗ chao vải xếp ly Necom', 'NEST-DE-1070', 'den-cay-dung-phong-khach-than-go-chao-vai-xep-ly-necom', 'Đèn cây đứng thân gỗ chao xếp ly cổ điển mang ánh sáng ấm áp dịu mắt cho góc đọc sách.', 'Chiếc đèn sàn thanh lịch kết hợp thân gỗ tự nhiên tiện tròn tinh tế cùng chao vải xếp ly trang nhã. Ánh sáng vàng dịu xuyên qua lớp vải tạo cảm giác thư thái, xóa tan căng thẳng sau ngày dài làm việc. Sản phẩm là điểm nhấn lý tưởng bên cạnh sofa phòng khách, góc đọc sách phòng ngủ hay sảnh chờ studio. Để bảo quản đèn bền đẹp, hãy lau nhẹ thân gỗ bằng khăn cotton khô mềm và dùng cây lăn bụi vệ sinh chao vải định kỳ.', 1, 4, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ cao su tự nhiên, chao vải polyester dập ly"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "35 x 35 x 150 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Gỗ sồi tự nhiên chao kem", "Gỗ óc chó trầm chao be"]}], "totalElements": 1}', 3800, 1),
(1071, NOW(), NOW(), null, null, 'Đèn ngủ để bàn thân gốm mộc chao vải Linen tối giản', 'NEST-DE-1071', 'den-ngu-de-ban-than-gom-moc-chao-vai-linen-toi-gian', 'Đèn ngủ thân gốm mộc chao vải linen tỏa ánh sáng vàng dịu nâng niu giấc ngủ an lành.', 'Sản phẩm sở hữu đế gốm thô vuốt tay phủ men mờ nhám, phối ăn ý cùng chao đèn bọc vải linen tự nhiên. Ánh sáng dịu mắt chan hòa khắp không gian, đem lại cảm giác bình yên tuyệt đối trước khi chìm vào giấc ngủ. Đèn thích hợp đặt trên tủ đầu giường phòng ngủ, kệ console lối vào hoặc góc trang trí kệ sách. Bạn chỉ cần lau bề mặt gốm bằng khăn ẩm vắt khô và phủi bụi nhẹ nhàng phần chao vải để đèn luôn tinh tươm.', 1, 4, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gốm nung men mờ, chao bọc vải linen, đui đèn đồng"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "22 x 22 x 36 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu trắng kem", "Màu xám tro mộc"]}], "totalElements": 1}', 1800, 1),
(1072, NOW(), NOW(), null, null, 'Đèn bàn làm việc khớp gập kim loại tối giản Bắc Âu', 'NEST-DE-1072', 'den-ban-lam-viec-khop-gap-kim-loai-toi-gian-bac-au', 'Đèn bàn kim loại khớp xoay linh hoạt cho ánh sáng tập trung hỗ trợ bảo vệ thị lực tối ưu.', 'Đèn bàn học và làm việc được gia công từ thép sơn tĩnh điện chống trầy, thiết kế các khớp xoay đa hướng linh hoạt giúp tùy chỉnh góc rọi dễ dàng. Chao đèn sâu cho luồng sáng định hướng rõ nét, không gây chói lóa hay nhức mỏi mắt khi làm việc lâu. Mẫu đèn là trợ thủ đắc lực trên bàn làm việc tại gia, bàn học sinh viên hoặc xưởng sáng tạo cá nhân. Vệ sinh bằng khăn mềm khô ráo, tránh dùng chất tẩy rửa mạnh làm ảnh hưởng lớp sơn mờ.', 1, 4, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Thép cán nguội sơn tĩnh điện mịn, khớp nối kim loại"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "18 x 28 x 55 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng nhám", "Đen mờ", "Xanh rêu nhạt"]}], "totalElements": 1}', 2100, 1),
(1073, NOW(), NOW(), null, null, 'Đèn tường gỗ sồi chao thủy tinh khói bo tròn tinh tế', 'NEST-DE-1073', 'den-tuong-go-soi-chao-thuy-tinh-khoi-bo-tron-tinh-te', 'Đèn tường đế gỗ sồi tự nhiên cùng chao thủy tinh tròn tạo điểm nhấn sang trọng ấm cúng.', 'Thiết kế đèn gắn tường tối giản với phần đế bằng gỗ sồi nguyên khối kết hợp chao cầu thủy tinh thủ công tinh xảo. Bóng thủy tinh cho độ tán sắc ấm áp, tạo nên vệt sáng dịu nhẹ đầy nghệ thuật trên mảng tường trống trải. Đèn đặc biệt phù hợp gắn hai bên đầu giường, hành lang, cầu thang hoặc chiếu sáng gương phòng tắm khô. Lưu ý ngắt nguồn điện trước khi lau chùi, vệ sinh chao bóng bằng khăn ẩm lau kính và giữ đế gỗ luôn khô ráo.', 1, 4, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên, chao thủy tinh thổi màu khói"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "15 x 20 x 25 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Thủy tinh trắng mờ", "Thủy tinh màu hổ phách"]}], "totalElements": 1}', 950, 1),
(1074, NOW(), NOW(), null, null, 'Dây đèn LED silicon hắt sáng tủ kệ uốn cong linh hoạt', 'NEST-DE-1074', 'day-den-led-silicon-hat-sang-tu-ke-uon-cong-linh-hoat', 'Dây LED silicon hắt sáng dẻo dai tạo viền sáng nghệ thuật cho tủ kệ và khe trần thạch cao.', 'Dây đèn LED bọc silicon chống chói cung cấp dải sáng liền mạch mịn màng, không lộ mắt led thô kệch. Chất liệu dẻo dai cho phép dễ dàng uốn lượn theo mọi góc cạnh kiến trúc hoặc dán âm tủ kệ sách, khe hắt trần và gầm giường. Sản phẩm mang tới luồng sáng viền hiện đại, ấm cúng và đầy chiều sâu cho phòng khách lẫn phòng ngủ hiện đại. Khi vệ sinh chỉ cần ngắt điện rồi lau nhẹ bề mặt dây bằng khăn khô mềm, tránh kéo căng quá mức mối nối.', 1, 4, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Dải LED COB mật độ cao bọc silicon dẻo tán quang"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "500 x 1.2 x 0.6 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Hiện đại"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dài 3m vàng nắng 3000K", "Dài 5m vàng nắng 3000K", "Dài 5m trung tính 4000K"]}], "totalElements": 1}', 450, 1),
(1075, NOW(), NOW(), null, null, 'Đèn thả bàn ăn chao nhôm sơn mờ phối gỗ sồi hiện đại', 'NEST-DE-1075', 'den-tha-ban-an-chao-nhom-son-mo-phoi-go-soi-hien-dai', 'Đèn thả bàn ăn chao nhôm sơn tĩnh điện phối chuôi gỗ sồi thanh thoát phong cách Bắc Âu.', 'Mẫu đèn thả mang dáng dấp Scandinavian đặc trưng với chao nhôm dập vuốt mượt mà điểm xuyết nút gỗ sồi tiện mộc mạc phía trên. Ánh sáng vàng chiếu tập trung xuống bề mặt mâm cơm, tôn lên màu sắc món ăn và kết nối không khí đầm ấm gia đình. Thiết kế hoàn hảo cho cụm đèn thả quầy đảo bếp, bàn ăn dài hoặc bàn quầy bar nhỏ. Bảo dưỡng đơn giản bằng cách lau chùi chao kim loại bằng khăn mềm định kỳ và lau khô ngay nếu bám dầu mỡ nhà bếp.', 1, 4, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Chao nhôm dập sơn tĩnh điện sần, chuôi gỗ sồi tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "30 x 30 x 22 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng tuyết phối gỗ", "Xám tro phối gỗ", "Xanh olive phối gỗ"]}], "totalElements": 1}', 1400, 1),
(1076, NOW(), NOW(), null, null, 'Đèn để bàn nấm cảm ứng chân kim loại sơn mờ tối giản', 'NEST-DE-1076', 'den-de-ban-nam-cam-ung-chan-kim-loai-son-mo-toi-gian', 'Đèn bàn hình cây nấm tích hợp pin sạc tiện lợi chạm cảm ứng đổi ba chế độ sáng êm ái.', 'Chiếc đèn bàn dáng nấm tròn ngộ nghĩnh mang phong cách hiện đại với vỏ sắt phủ sơn tĩnh điện mịn màng. Đèn trang bị pin sạc không dây cùng nút chạm cảm ứng nhạy bén, cho phép tùy chỉnh ba mức độ sáng từ dịu nhẹ đến rõ nét. Thiết kế gọn nhẹ dễ dàng mang theo sử dụng ở bàn trà ngoài ban công, kệ đầu giường hoặc bàn làm việc. Bảo quản thiết bị bằng cách sạc pin định kỳ mỗi tháng một lần khi không dùng lâu và tránh để nước ngấm vào cổng sạc.', 1, 4, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Hợp kim sắt sơn tĩnh điện mờ, linh kiện led tích hợp pin sạc"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "16 x 16 x 28 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu be ấm", "Màu đen mờ", "Màu vàng mù tạt"]}], "totalElements": 1}', 850, 1),
(1077, NOW(), NOW(), null, null, 'Đèn thả trần chao gốm trắng xếp ly tối giản Bắc Âu', 'NEST-DE-1077', 'den-tha-tran-chao-gom-trang-xep-ly-toi-gian-bac-au', 'Đèn thả trần chao gốm xếp ly tinh tế, lan tỏa ánh sáng vàng ấm cúng cho bàn ăn.', 'Đèn thả trần được tạo hình tinh xảo từ chất liệu gốm sứ nung cao cấp với bề mặt men mờ xếp ly duyên dáng, kết hợp đui đèn bằng kim loại ánh vàng sang trọng. Chao đèn phản xạ ánh sáng vàng ấm nhẹ nhàng, không gây chói mắt và tạo cảm giác quây quần, ấm cúng. Thiết kế tối giản mang hơi thở Bắc Âu, lý tưởng để bố trí phía trên bàn ăn gỗ mộc, quầy đảo bếp hay góc bàn trà phòng khách. Khi vệ sinh, bạn chỉ cần dùng khăn mềm khô hoặc chổi lông mềm lau nhẹ bề mặt, tránh dùng chất tẩy rửa mạnh làm ảnh hưởng nước men.', 1, 4, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gốm sứ tráng men mờ, đui đồng, dây bọc vải dệt"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "26 x 26 x 18 cm, dây dài 120 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Đường kính 22 cm", "Đường kính 26 cm"]}], "totalElements": 1}', 1400, 1),
(1078, NOW(), NOW(), null, null, 'Đèn cây đứng thân gỗ sồi chao vải đay phong cách Japandi', 'NEST-DE-1078', 'den-cay-dung-than-go-soi-chao-vai-day-phong-cach-japandi', 'Đèn sàn ba chân gỗ sồi mộc mạc, tạo điểm nhấn ấm áp và thư thái cho góc phòng khách.', 'Sản phẩm sở hữu khung ba chân chắc chắn bằng gỗ sồi tự nhiên đã xử lý chống cong vênh, kết hợp cùng chao đèn bọc vải đay mộc mạc cho ánh sáng dịu mắt. Đèn mang lại cảm giác thư thái, tĩnh tại và ấm áp cho không gian đọc sách hay góc thư giãn mỗi tối. Mẫu đèn cây đứng này đặc biệt phù hợp đặt cạnh ghế sofa phòng khách, góc phòng ngủ hoặc sảnh nghỉ mang phong cách Japandi và Bắc Âu. Bạn nên lau chùi định kỳ bằng khăn vải vi sợi khô ráo, tránh đặt đèn ở những nơi ẩm ướt hoặc tiếp xúc trực tiếp với nước mưa.', 1, 4, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên, vải đay thô dệt, khung kim loại"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "45 x 45 x 150 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Gỗ sồi tự nhiên", "Gỗ sồi nâu óc chó"]}], "totalElements": 1}', 3200, 1),
(1079, NOW(), NOW(), null, null, 'Đèn ngủ để bàn thân gốm thô men mờ chân mộc chuẩn wabi sabi', 'NEST-DE-1079', 'den-ngu-de-ban-than-gom-tho-men-mo-chan-moc-chuan-wabi-sabi', 'Đèn ngủ gốm mộc với chao vải linen beige dịu nhẹ, kiến tạo không gian nghỉ ngơi thư thái.', 'Chiếc đèn ngủ để bàn kết hợp hài hòa giữa phần thân gốm nung men tro sần tự nhiên và chao đèn vải linen thô mộc nhuộm màu be thanh nhã. Ánh sáng vàng dịu xuyên qua lớp vải khuếch tán đều, xoa dịu đôi mắt và tạo bầu không khí thư thái, đưa bạn vào giấc ngủ ngon sau ngày dài mệt mỏi. Đèn hoàn hảo để đặt trên táp đầu giường, kệ sách trang trí hoặc bàn làm việc phong cách Wabi-Sabi và Japandi. Để giữ chao đèn luôn sạch đẹp, bạn nên dùng con lăn bụi hoặc khăn khô mềm để vệ sinh định kỳ, tránh xịt nước trực tiếp lên thân gốm.', 1, 4, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gốm đất sét mộc, chao vải linen dệt thô"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "22 x 22 x 35 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Men kem chấm cát", "Men nâu tro xám"]}], "totalElements": 1}', 1850, 1),
(1080, NOW(), NOW(), null, null, 'Đèn tường gắn gỗ tần bì chao thủy tinh khói hiện đại', 'NEST-DE-1080', 'den-tuong-gan-go-tan-bi-chao-thuy-tinh-khoi-hien-dai', 'Đèn gắn tường đế gỗ tần bì với chao cầu thủy tinh, tạo điểm nhấn ánh sáng mềm mại.', 'Mẫu đèn gắn tường kết hợp tinh tế giữa đế ốp bằng gỗ tần bì tiện mịn màng và chao cầu thủy tinh khói trong suốt cao cấp. Đèn mang đến luồng ánh sáng hắt tường lãng mạn, tôn vinh các đường nét kiến trúc và tạo chiều sâu ấn tượng cho căn phòng. Thiết kế nhỏ gọn này cực kỳ thích hợp lắp đặt ở hai bên gương bàn trang điểm, dọc hành lang lối đi, đầu giường ngủ hoặc vách trang trí phòng khách. Việc bảo quản rất dễ dàng, chỉ cần ngắt nguồn điện và dùng khăn cotton mềm ẩm vắt ráo nước lau sạch bụi bám trên bề mặt bóng thủy tinh.', 1, 4, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tần bì tự nhiên, chao thủy tinh thổi thủ công, đui nhôm"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "15 x 20 x 25 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Hiện đại"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Thủy tinh khói", "Thủy tinh trắng mờ"]}], "totalElements": 1}', 950, 1),
(1081, NOW(), NOW(), null, null, 'Dây đèn LED trang trí bóng tròn bọc sợi bông tự nhiên', 'NEST-DE-1081', 'day-den-led-trang-tri-bong-tron-boc-soi-bong-tu-nhien', 'Dây đèn LED quả cầu sợi cotton đan thủ công, thắp sáng không gian sống thêm thơ mộng.', 'Bộ đèn LED dây trang trí gồm chuỗi các quả cầu được bọc sợi cotton thiên nhiên dệt đan tỉ mỉ, tích hợp bóng LED tiết kiệm điện năng phát nhiệt cực thấp. Ánh sáng vàng nhẹ len lỏi qua từng kẽ sợi bông, tạo nên hiệu ứng thị giác lung linh, ấm áp và vô cùng thơ mộng. Sản phẩm thích hợp quấn trang trí quanh khung gương, đầu giường ngủ, góc lều đọc sách của bé hoặc lan can ban công trong các buổi tiệc nhỏ. Lưu ý bảo quản dây đèn nơi khô ráo, tránh ngâm nước trực tiếp và dùng chổi quét bụi nhỏ để làm sạch bề mặt các quả bóng.', 1, 4, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Sợi cotton tự nhiên dệt tay, bóng LED, dây nhựa PVC"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "Dài 300 cm, đường kính bóng 6 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dây 20 bóng dài 3 mét", "Dây 35 bóng dài 5 mét"]}], "totalElements": 1}', 380, 1),
(1082, NOW(), NOW(), null, null, 'Đèn bàn làm việc kim loại sơn tĩnh điện khớp gỗ tự nhiên', 'NEST-DE-1082', 'den-ban-lam-viec-kim-loai-son-tinh-dien-khop-go-tu-nhien', 'Đèn bàn học điều chỉnh góc chiếu linh hoạt, chống mỏi mắt với thiết kế Bắc Âu tối giản.', 'Đèn bàn làm việc được chế tác từ kim loại dập định hình phủ sơn tĩnh điện chống xước, phối hợp linh hoạt cùng các khớp nối bằng gỗ dẻ gai mộc mạc. Chao đèn gom sáng chuẩn xác, không nhấp nháy, hỗ trợ chống mỏi mắt tối đa khi học tập và làm việc trong thời gian dài. Kiểu dáng thanh lịch mang đậm tinh thần Scandinavian, dễ dàng phối hợp trên bàn làm việc tại nhà, bàn học hay góc đọc sách cá nhân. Khi sử dụng lâu ngày, bạn hãy lau sạch các khớp chuyển động và thân đèn bằng khăn bông mềm khô ráo, tránh để nước đọng ở các điểm nối dây.', 1, 4, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Thép sơn tĩnh điện, gỗ dẻ gai tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "18 x 28 x 46 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng mờ phối gỗ", "Xám khói phối gỗ", "Đen nhám phối gỗ"]}], "totalElements": 1}', 1600, 1),
(1083, NOW(), NOW(), null, null, 'Đèn thả trần mây tre đan thủ công hình nón mộc mạc', 'NEST-DE-1083', 'den-tha-tran-may-tre-dan-thu-cong-hinh-non-moc-mac', 'Đèn thả nón đan mây tre truyền thống, tạo hiệu ứng vệt sáng nan tre huyền ảo cho phòng ăn.', 'Sản phẩm đèn thả trần được đan thủ công tỉ mỉ từ các sợi mây tre tự nhiên đã qua chọn lọc và xử lý sấy khô chống mối mọt kỹ lưỡng. Chao đèn hình nón tạo ra hiệu ứng đổ bóng nan tre lạ mắt trên vách tường, mang lại xúc cảm mộc mạc, gần gũi thiên nhiên cho căn nhà. Mẫu đèn này rất thích hợp treo thả phía trên bàn ăn gia đình, bàn trà ban công hay không gian quán cà phê phong cách mộc. Bạn chỉ cần dùng máy hút bụi cầm tay đầu chổi mềm hoặc chổi lông quét sạch bụi bẩn bám trên kẽ nan tre, giữ đèn ở nơi thông thoáng.', 1, 4, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Mây tre đan tự nhiên, khung sắt định hình, dây thả chịu lực"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "40 x 40 x 25 cm, dây dài 100 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Mộc mạc"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Đường kính 35 cm", "Đường kính 45 cm"]}], "totalElements": 1}', 850, 1),
(1084, NOW(), NOW(), null, null, 'Đèn để bàn nấm gỗ tự nhiên tích điện cảm ứng chạm 3 chế độ', 'NEST-DE-1084', 'den-de-ban-nam-go-tu-nhien-tich-dien-cam-ung-cham-3-che-do', 'Đèn nấm tích điện cảm ứng chạm không dây, thiết kế gỗ sồi nhỏ gọn đa năng cho mọi phòng.', 'Mẫu đèn bàn hình cây nấm độc đáo với chao tiện từ gỗ sồi tự nhiên kết hợp thân kim loại chắc chắn, tích hợp pin sạc tiện lợi cùng cảm ứng chạm chuyển 3 sắc độ sáng. Nguồn sáng LED dịu êm không tỏa nhiệt mang lại cảm giác ấm cúng, thư thả và có thể dễ dàng xách chuyển khắp mọi góc trong nhà. Thiết kế nhỏ nhắn chuẩn Japandi rất vừa vặn đặt trên bàn trà phòng khách, bàn đầu giường hay góc bàn làm việc tối giản. Để pin luôn bền bỉ, bạn nên sạc định kỳ khi pin yếu và dùng khăn vi sợi khô lau nhẹ thân gỗ, tránh hóa chất ăn mòn.', 1, 4, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi nguyên khối, hợp kim nhôm xước mờ, chíp LED"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "16 x 16 x 22 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Gỗ sồi vàng tự nhiên", "Gỗ sồi nâu óc chó"]}], "totalElements": 1}', 750, 1),
(1085, NOW(), NOW(), null, null, 'Đèn thả trần chao nhôm sơn nhám đỉnh gỗ tần bì Bắc Âu', 'NEST-DE-1085', 'den-tha-tran-chao-nhom-son-nham-dinh-go-tan-bi-bac-au', 'Thiết kế chao vòm hiện đại kết hợp gỗ tần bì mộc mạc, tạo điểm nhấn ấm áp cho bàn ăn.', 'Sản phẩm được gia công từ hợp kim nhôm cao cấp sơn tĩnh điện nhám mịn, kết hợp điểm nhấn đỉnh gỗ tần bì tiện tròn tự nhiên tạo vẻ đẹp trang nhã. Ánh sáng chiếu tập trung xuống mặt bàn tạo cảm giác ấm cúng, gần gũi trong mỗi bữa cơm sum vầy. Mẫu đèn thả này là lựa chọn lý tưởng cho bàn ăn căn hộ, quầy bar bếp hoặc bàn trà phòng khách phong cách Japandi và Scandinavian. Bạn chỉ cần lau chùi bụi bẩn bề mặt chao đèn định kỳ bằng khăn sợi mềm khô ráo, tránh dùng chất tẩy ăn mòn.', 1, 4, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Hợp kim nhôm sơn tĩnh điện, gỗ tần bì tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "35 x 35 x 28 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Đường kính 30cm", "Đường kính 40cm"]}], "totalElements": 1}', 1400, 1),
(1086, NOW(), NOW(), null, null, 'Đèn cây đứng 3 chân gỗ sồi chao vải Linen tối giản', 'NEST-DE-1086', 'den-cay-dung-3-chan-go-soi-chao-vai-linen-toi-gian', 'Chân đỡ ba chạc gỗ sồi vững chãi phối chao vải linen khuếch tán ánh sáng êm dịu góc phòng khách.', 'Mẫu đèn cây sở hữu khung ba chân chế tác từ gỗ sồi tự nhiên chắc chắn kết hợp chao đèn tròn bằng vải linen dệt thô cao cấp. Chao vải mộc giúp khuếch tán ánh sáng vàng dịu nhẹ, tạo bầu không khí thư thái, ấm áp và chống chói mắt hiệu quả khi đọc sách hay trò chuyện. Sản phẩm thích hợp đặt tại góc sofa phòng khách, góc thư giãn phòng đọc hoặc cạnh giường ngủ phong cách Bắc Âu. Vệ sinh đơn giản bằng chổi lông mềm hoặc máy hút bụi cầm tay cho phần chao vải và lau nhẹ thân gỗ bằng khăn ẩm.', 1, 4, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên, chao vải linen dệt thô"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "45 x 45 x 150 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Chao Vải Trắng Be", "Chao Vải Nâu Đất"]}], "totalElements": 1}', 3200, 1),
(1087, NOW(), NOW(), null, null, 'Đèn ngủ để bàn chao xếp ly đế gỗ tự nhiên phong cách Muji', 'NEST-DE-1087', 'den-ngu-de-ban-chao-xep-ly-de-go-tu-nhien-phong-cach-muji', 'Kiểu dáng cổ điển với chao xếp ly tinh tế cùng đế gỗ đặc, mang lại ánh sáng êm dịu cho giấc ngủ.', 'Chiếc đèn để bàn kết hợp hài hòa giữa đế gỗ tự nhiên nguyên khối tiện tròn và chao vải xếp ly tỉ mỉ theo tinh thần tối giản Nhật Bản. Ánh sáng vàng dịu xuyên qua từng nếp gấp vải tạo hiệu ứng chuyển sắc mềm mại, giúp xua tan căng thẳng và đưa bạn vào giấc ngủ ngon sau ngày dài mệt mỏi. Đèn phù hợp đặt trên tab đầu giường ngủ, kệ tủ trang trí hoặc bàn trà góc phòng khách. Để giữ đèn luôn tinh tươm, hãy dùng chổi quét bụi nhỏ làm sạch các nếp gấp chao đèn và bảo quản nơi khô ráo, thoáng mát.', 1, 4, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ cao su tự nhiên, chao vải dệt xếp ly"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "24 x 24 x 32 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Đế Gỗ Sáng Chao Be", "Đế Gỗ Óc Chó Chao Kem"]}], "totalElements": 1}', 850, 1),
(1088, NOW(), NOW(), null, null, 'Đèn tường gắn gỗ sồi chao kim loại xoay góc 180 độ', 'NEST-DE-1088', 'den-tuong-gan-go-soi-chao-kim-loai-xoay-goc-180-do', 'Khớp xoay linh hoạt hỗ trợ điều chỉnh hướng chiếu sáng, đế gỗ sồi ấm áp tô điểm mảng tường trống.', 'Đèn gắn tường nổi bật với phần đế ốp bằng gỗ sồi tự nhiên vân sáng kết hợp chao kim loại phủ sơn tĩnh điện chống gỉ sét bền bỉ. Khớp nối cơ học linh hoạt cho phép xoay chao đèn 180 độ dễ dàng điều hướng luồng sáng theo nhu cầu đọc sách hay chiếu tranh. Thiết kế nhỏ gọn này cực kỳ phù hợp gắn đầu giường ngủ thay cho đèn bàn, hành lang lối đi hoặc khu vực góc làm việc nhỏ hẹp. Bạn nên ngắt nguồn điện trước khi dùng khăn khô mềm lau sạch bề mặt kim loại và gỗ định kỳ.', 1, 4, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên, kim loại sơn tĩnh điện"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "22 x 15 x 18 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng Sữa", "Đen Nhám"]}], "totalElements": 1}', 750, 1),
(1089, NOW(), NOW(), null, null, 'Dây đèn LED trang trí bóng mây tre đan ánh sáng vàng ấm', 'NEST-DE-1089', 'day-den-led-trang-tri-bong-may-tre-dan-anh-sang-vang-am', 'Những quả cầu mây đan thủ công ấm áp mang lại vẻ đẹp mộc mạc, lung linh cho không gian sống.', 'Dây đèn trang trí gồm chuỗi bóng tròn được bọc tỉ mỉ bằng sợi mây tre đan thủ công tự nhiên, kết nối cùng dải LED phát nhiệt thấp an toàn. Ánh sáng vàng ấm len qua từng kẽ đan mây tạo hiệu ứng hoa văn lung linh, biến căn phòng trở nên thơ mộng, gần gũi với thiên nhiên. Sản phẩm thích hợp quấn quanh khung giường ngủ, treo thả ban công, trang trí kệ sách hay góc lều thư giãn phong cách Wabi-Sabi mộc mạc. Nên sử dụng ở không gian trong nhà khô ráo và nhẹ nhàng phủi bụi bằng chổi mềm khi vệ sinh.', 1, 4, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Mây tre đan tự nhiên, bóng LED, dây dẫn bọc nhựa trong"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "300 x 5 x 5 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dài 3 Mét (20 Bóng)", "Dài 6 Mét (40 Bóng)"]}], "totalElements": 1}', 320, 1),
(1090, NOW(), NOW(), null, null, 'Đèn bàn làm việc cần gập kim loại chao vòm tối giản', 'NEST-DE-1090', 'den-ban-lam-viec-can-gap-kim-loai-chao-vom-toi-gian', 'Thiết kế khớp gập cơ học linh động cùng chao vòm tập trung ánh sáng, bảo vệ thị lực tối ưu khi làm việc.', 'Được chế tác hoàn toàn từ thép cán nguội phủ sơn tĩnh điện mờ mịn màng, chiếc đèn bàn mang phong cách Scandinavian sắc sảo và hiện đại. Khớp gập thân đèn vững chãi cho phép người dùng tùy ý nâng hạ độ cao và góc chiếu, cung cấp luồng sáng rõ nét, chống mỏi mắt suốt thời gian học tập hay làm việc. Mẫu đèn bàn này đặc biệt ăn khớp với bàn làm việc văn phòng tại gia, bàn học hoặc góc xưởng sáng tạo thủ công. Bảo quản dễ dàng bằng cách lau sạch bề mặt với khăn vi sợi ẩm nhẹ sau khi ngắt nguồn.', 1, 4, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Thép cán nguội sơn tĩnh điện"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "18 x 18 x 55 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng Mờ", "Xanh Rêu Nhạt", "Xám Tro"]}], "totalElements": 1}', 1850, 1),
(1091, NOW(), NOW(), null, null, 'Bình gốm thô mộc dáng tròn cổ hẹp men cát tối giản', 'NEST-DC-1091', 'binh-gom-tho-moc-dang-tron-co-hep-men-cat-toi-gian', 'Bình gốm thủ công men cát nhám mờ với đường cong mộc mạc mang đậm dấu ấn Wabi-Sabi tĩnh lặng.', 'Sản phẩm chế tác từ chất liệu gốm sành nung ở nhiệt độ cao, bề mặt phủ lớp men cát nhám mờ mang đậm tinh thần Wabi-Sabi nguyên bản. Cảm giác cầm nắm đầm tay, chắc chắn với những hạt vân li ti tự nhiên giúp tạo chiều sâu thị giác ấn tượng. Bình rất phù hợp để cắm hoa khô như lau, tuyết mai hoặc trưng bày độc bản trên bàn trà, kệ sách và bậu cửa sổ phòng khách. Để giữ bình luôn bền đẹp, bạn chỉ cần lau nhẹ bằng khăn mềm ẩm và tránh va chạm mạnh với các vật kim loại sắc nhọn.', 1, 5, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gốm sành men thô ráp"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "18 x 18 x 22 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng cát mờ", "Nâu đất mộc"]}], "totalElements": 1}', 1400, 1),
(1092, NOW(), NOW(), null, null, 'Tranh canvas trừu tượng khung gỗ tần bì phong cách mộc', 'NEST-DC-1092', 'tranh-canvas-truu-tuong-khung-go-tan-bi-phong-cach-moc', 'Tranh canvas gam màu be ấm áp kết hợp khung gỗ tần bì tự nhiên làm sáng bừng mảng tường trống.', 'Bức tranh canvas sử dụng công nghệ in phun kỹ thuật số cao cấp trên nền vải cotton dày dặn, kết hợp khung viền gỗ tần bì tự nhiên sáng màu tinh tế. Họa tiết hình khối trừu tượng với gam màu trung tính mang lại cảm giác bình yên, thư thái và mở rộng không gian thị giác. Tranh là điểm nhấn hoàn hảo cho mảng tường trống phía sau sofa, hành lang hay phòng làm việc tối giản. Khi sử dụng, nên treo tranh ở nơi khô ráo, tránh ánh nắng trực tiếp chiếu gắt và dùng chổi lông gà vệ sinh bụi định kỳ.', 1, 5, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải canvas cotton, khung gỗ tần bì"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "50 x 70 x 3 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Kích thước 50 x 70 cm", "Kích thước 60 x 80 cm"]}], "totalElements": 1}', 1600, 1),
(1093, NOW(), NOW(), null, null, 'Đồng hồ treo tường gỗ sồi kim trôi tĩnh âm chuẩn Japandi', 'NEST-DC-1093', 'dong-ho-treo-tuong-go-soi-kim-troi-tinh-am-chuan-japandi', 'Đồng hồ treo tường gỗ sồi tự nhiên máy kim trôi êm ái giữ trọn sự tĩnh lặng cho không gian sống.', 'Đồng hồ được tiện gọt tỉ mỉ từ gỗ sồi tự nhiên nguyên khối, phô diễn đường vân gỗ uốn lượn mộc mạc và chân thực. Bộ máy Silent Quartz kim trôi êm ái, hoàn toàn không phát ra tiếng tích tắc, mang lại không gian tĩnh lặng tuyệt đối cho việc nghỉ ngơi và tập trung. Thiết kế mặt số tối giản thích hợp để treo tại phòng ngủ, phòng khách hay góc làm việc mang phong cách Japandi ấm cúng. Tránh treo đồng hồ ở nơi có độ ẩm cao hoặc nguồn nhiệt lớn, thay pin định kỳ sáu tháng một lần để máy chạy bền bỉ.', 1, 5, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên, máy kim trôi Silent Quartz"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "30 x 30 x 4 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Gỗ sồi mộc tự nhiên", "Gỗ sồi sơn đen mờ"]}], "totalElements": 1}', 950, 1),
(1094, NOW(), NOW(), null, null, 'Gương treo tường khung gỗ bo tròn bất đối xứng tinh tế', 'NEST-DC-1094', 'guong-treo-tuong-khung-go-bo-tron-bat-doi-xung-tinh-te', 'Gương nghệ thuật dáng vòm bất đối xứng viền gỗ tần bì giúp mở rộng chiều sâu không gian sống.', 'Gương sở hữu kiểu dáng bất đối xứng độc đáo với khung gỗ tần bì uốn cong khéo léo, mang nét đẹp tự do và thanh thoát chuẩn phong cách Bắc Âu. Phôi gương Bỉ cao cấp phủ bạc nhiều lớp mang lại hình ảnh phản chiếu chân thực, sắc nét và khả năng chống ố mốc vượt trội. Món đồ này lý tưởng để treo tại khu vực tiền sảnh, bàn trang điểm hoặc tạo điểm nhấn nghệ thuật trên tường phòng khách. Bạn nên dùng nước xịt kính chuyên dụng cùng khăn sợi microfiber mềm để làm sạch bề mặt gương, tránh xịt nước trực tiếp lên khung gỗ.', 1, 5, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Phôi gương Bỉ tráng bạc 5mm, khung gỗ tần bì"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "55 x 75 x 3 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Gỗ tần bì tự nhiên", "Gỗ óc chó trầm ấm"]}], "totalElements": 1}', 3800, 1),
(1095, NOW(), NOW(), null, null, 'Nến thơm hũ gốm thủ công hương gỗ tuyết tùng thư giãn', 'NEST-DC-1095', 'nen-thom-hu-gom-thu-cong-huong-go-tuyet-tung-thu-gian', 'Nến thơm sáp đậu nành hũ gốm mộc với hương tuyết tùng trầm ấm giúp thư giãn tâm trí nhẹ nhàng.', 'Nến thơm được đổ tay thủ công từ sáp đậu nành thiên nhiên lành tính, hòa quyện cùng tinh dầu cao cấp và bấc gỗ phát ra tiếng lách tách vui tai khi cháy. Chiếc hũ gốm thô mộc xộc xạo vân tay có thể tái sử dụng làm chậu cây nhỏ xinh sau khi nến đã cháy hết. Mùi hương gỗ tuyết tùng ấm áp giúp xua tan căng thẳng, phù hợp thắp trong phòng ngủ, phòng tắm hoặc phòng thiền thư giãn. Bảo quản nến ở nơi râm mát, cắt ngắn bấc gỗ còn khoảng năm milimét trước mỗi lần thắp để ngọn lửa cháy đều và sạch khói.', 1, 5, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Sáp đậu nành, bấc gỗ, hũ gốm nung Bát Tràng"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "9 x 9 x 10 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Hương Tuyết Tùng & Rêu", "Hương Cam Bergamot & Trà"]}], "totalElements": 1}', 650, 1),
(1096, NOW(), NOW(), null, null, 'Tượng điêu khắc nghệ thuật đường nét uốn lượn tối giản', 'NEST-DC-1096', 'tuong-dieu-khac-nghe-thuat-duong-net-uon-luon-toi-gian', 'Tượng trang trí trừu tượng dạng sóng mềm mại tôn vinh vẻ đẹp tĩnh tại và sang trọng cho kệ tủ.', 'Bức tượng nghệ thuật được tạo hình bằng chất liệu composite cao cấp gia cường sợi thủy tinh, bề mặt xử lý sơn mờ mịn màng như đá tự nhiên. Các đường nét uốn lượn trừu tượng tượng trưng cho dòng chảy tĩnh lặng của tâm hồn, khơi gợi cảm hứng sáng tạo và sự thư thái. Tượng rất thích hợp để đặt trang trí trên kệ tivi, bàn làm việc, tủ console hay giá sách phòng khách hiện đại. Trong quá trình sử dụng, bạn chỉ cần dùng cọ mềm hoặc khăn khô lau nhẹ bụi bẩn, tránh để vật sắc nhọn gây trầy xước lớp sơn bên ngoài.', 1, 5, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Composite đúc sợi thủy tinh phủ sơn mờ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "16 x 12 x 28 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Hiện đại"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng thạch cao", "Đen nhám mờ"]}], "totalElements": 1}', 1200, 1),
(1097, NOW(), NOW(), null, null, 'Khay gỗ tròn bê đồ đa năng tay cầm khoét âm mộc mạc', 'NEST-DC-1097', 'khay-go-tron-be-do-da-nang-tay-cam-khoet-am-moc-mac', 'Khay tròn gỗ dẻ gai nguyên khối tiện dụng cho bàn trà, lưu trữ nến thơm và phụ kiện tinh gọn.', 'Chiếc khay được tiện từ gỗ dẻ gai tuyển chọn với các thớ gỗ mịn màng, bề mặt quét lớp dầu lau thực vật an toàn cho sức khỏe và chống ẩm mốc hiệu quả. Phần viền bo tròn mềm mại kết hợp tay cầm khoét âm tinh tế, tạo cảm giác cầm nắm chắc chắn và tiện lợi khi bưng bê. Khay thích hợp dùng để đựng ấm trà, bày biện nến thơm, nước hoa trên bàn console hoặc phục vụ bữa sáng nhẹ nhàng tại giường ngủ. Sau khi sử dụng, hãy lau khô khay bằng khăn sạch và tránh ngâm lâu trong nước hay phơi dưới nắng gắt.', 1, 5, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ dẻ gai sấy tiêu chuẩn phủ dầu lau"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "32 x 32 x 4 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Mộc mạc"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Đường kính 30 cm", "Đường kính 36 cm"]}], "totalElements": 1}', 850, 1),
(1098, NOW(), NOW(), null, null, 'Bình hoa gốm miệng rộng dáng bầu men rạn phong cách Muji', 'NEST-DC-1098', 'binh-hoa-gom-mieng-rong-dang-bau-men-ran-phong-cach-muji', 'Bình gốm men rạn tự nhiên cổ điển tôn nét đẹp thanh thoát cho từng nhành hoa cắm thả tự nhiên.', 'Sản phẩm được nung ở nhiệt độ cao với lớp men rạn cổ điển độc đáo, tạo nên những đường nứt tự nhiên mang đậm hơi thở thời gian và thẩm mỹ Muji. Dáng bình phình tròn ở thân và thuôn dần về miệng, mang lại cảm giác cân bằng, vững chãi khi cắm các cành hoa thân mềm hoặc cành lá xanh mướt. Bình hoa là điểm nhấn duyên dáng cho bàn ăn gia đình, bàn làm việc hay góc kệ trang trí phòng khách. Bạn nên rửa bình bằng nước ấm cùng bọt biển mềm, lau khô nhẹ nhàng trước khi cất giữ ở nơi thông thoáng.', 1, 5, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gốm nung nhiệt độ cao men rạn tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "15 x 15 x 25 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Kem sữa men rạn", "Xám tro men rạn"]}], "totalElements": 1}', 1100, 1),
(1099, NOW(), NOW(), null, null, 'Gương treo tường toàn thân dáng vòm bo viền kim loại', 'NEST-DC-1099', 'guong-treo-tuong-toan-than-dang-vom-bo-vien-kim-loai', 'Gương soi dáng vòm viền kim loại cao cấp mang lại chiều sâu và nét thanh lịch cho không gian sống.', 'Sản phẩm được chế tác từ phôi gương bạc cao cấp cho hình ảnh chân thực, sáng rõ và không bị méo mó. Viền kim loại sơn tĩnh điện chống gỉ sét bền bỉ, đường uốn vòm mềm mại giúp tạo cảm giác trần nhà cao thoáng hơn. Gương phù hợp bài trí tại lối vào sảnh, phòng ngủ hoặc góc thử đồ phong cách hiện đại. Bạn chỉ cần lau bề mặt kính định kỳ bằng khăn sợi mềm thấm nước lau kính để duy trì độ trong suốt.', 1, 5, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Phôi gương bạc, viền kim loại sơn tĩnh điện"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "50 x 3 x 150 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Hiện đại"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Đen mờ", "Vàng đồng"]}], "totalElements": 1}', 8500, 1),
(1100, NOW(), NOW(), null, null, 'Tranh treo tường nghệ thuật trừu tượng tông be tối giản', 'NEST-DC-1100', 'tranh-treo-tuong-nghe-thuat-truu-tuong-tong-be-toi-gian', 'Tranh canvas trừu tượng với các mảng màu trung tính dịu mắt kiến tạo điểm nhấn trang nhã cho bức tường.', 'Bức tranh in trên nền vải canvas chuyên dụng chống thấm ẩm, kết hợp công nghệ in phun mực sắc nét bền màu theo thời gian. Khung ngoài làm từ nhựa composite nhẹ bền giả gỗ tự nhiên, đem lại nét mộc mạc và thanh lịch chuẩn phong cách Bắc Âu. Tranh rất thích hợp treo sau sofa phòng khách, hành lang hoặc đầu giường phòng ngủ. Khi vệ sinh, bạn chỉ cần dùng chổi lông gà hoặc khăn khô mềm quét nhẹ qua bề mặt.', 1, 5, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải canvas, khung composite vân gỗ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "50 x 70 x 3 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Kích thước 40 x 60 cm", "Kích thước 50 x 70 cm"]}], "totalElements": 1}', 1200, 1),
(1101, NOW(), NOW(), null, null, 'Bình hoa gốm trắng men mờ dáng trụ sọc nhuyễn Bắc Âu', 'NEST-DC-1101', 'binh-hoa-gom-trang-men-mo-dang-tru-soc-nhuyen-bac-au', 'Bình hoa gốm sứ trắng men mờ với họa tiết sọc nhuyễn tinh tế tôn vinh vẻ đẹp của mọi cành hoa.', 'Chế tác từ chất liệu đất sét trắng nung nhiệt độ cao, chiếc bình sở hữu kết cấu đanh chắc và khả năng chống rạn nứt tuyệt đối. Bề mặt phủ lớp men mờ mịn màng phối cùng các đường gân nổi dọc thân bình tạo cảm giác cầm nắm chắc tay và giàu tính nghệ thuật. Chiếc bình phù hợp cắm hoa tươi, hoa khô trang trí bàn ăn hoặc kệ sách. Vệ sinh bình dễ dàng bằng cách rửa nhẹ dưới vòi nước và lau khô bằng khăn mềm.', 1, 5, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gốm sứ men mờ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "12 x 12 x 24 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Cỡ vừa cao 18cm", "Cỡ lớn cao 24cm"]}], "totalElements": 1}', 950, 1),
(1102, NOW(), NOW(), null, null, 'Đồng hồ treo tường vành nhôm tối giản mặt số chìm Muji', 'NEST-DC-1102', 'dong-ho-treo-tuong-vanh-nhom-toi-gian-mat-so-chim-muji', 'Đồng hồ treo tường kim trôi êm ái mang thiết kế mặt số chìm tinh giản đậm chất lối sống Muji.', 'Vỏ đồng hồ làm bằng hợp kim nhôm phay xước nhẹ, kết hợp mặt kính khoáng chống trầy trong suốt giúp hiển thị rõ ràng từng chi tiết. Bộ máy kim trôi siêu tĩnh âm vận hành êm ái, hoàn toàn không phát ra tiếng tích tắc gây ảnh hưởng đến giấc ngủ hay sự tập trung. Thiết kế tối giản này lý tưởng cho góc làm việc, phòng ngủ và không gian sinh hoạt chung. Bạn nên thay pin kiềm định kỳ mỗi sáu tháng để đảm bảo đồng hồ chạy ổn định.', 1, 5, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Hợp kim nhôm, mặt kính khoáng"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "30 x 30 x 4 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng tuyết", "Xám khói"]}], "totalElements": 1}', 800, 1),
(1103, NOW(), NOW(), null, null, 'Nến thơm sáp đậu nành tinh dầu cam ngọt gỗ thông ấm cúng', 'NEST-DC-1103', 'nen-thom-sap-dau-nanh-tinh-dau-cam-ngot-go-thong-am-cung', 'Nến thơm hũ gốm từ sáp đậu nành thiên nhiên tỏa hương cam ngọt và gỗ thông dịu nhẹ thư thái tâm hồn.', 'Hũ nến kết hợp hoàn hảo giữa sáp đậu nành thiên nhiên, sáp ong và tinh dầu thực vật nguyên chất, an toàn tuyệt đối cho đường hô hấp. Bấc nến từ sợi cotton không chì giúp ngọn lửa cháy đều, không khói đen, tỏa ngát hương thơm ấm áp xua tan căng thẳng. Sản phẩm rất phù hợp đặt ở bàn trang điểm, phòng tắm hoặc kệ đầu giường. Sau mỗi lần thắp, bạn nên cắt ngắn bấc nến khoảng nửa centimet và đậy nắp kín để lưu giữ trọn vẹn hương thơm.', 1, 5, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Sáp đậu nành tự nhiên, hũ gốm tráng men"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "8 x 8 x 9 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Hũ 150g", "Hũ 250g"]}], "totalElements": 1}', 450, 1),
(1104, NOW(), NOW(), null, null, 'Tượng trang trí gốm sứ vòng tròn đôi phong cách tối giản', 'NEST-DC-1104', 'tuong-trang-tri-gom-su-vong-tron-doi-phong-cach-toi-gian', 'Tượng gốm hình học uốn lượn trừu tượng mang tinh thần nghệ thuật tối giản cho kệ tủ hiện đại.', 'Bức tượng điêu khắc từ gốm nung phủ men cát hạt mịn, tạo hiệu ứng thị giác thô mộc đặc trưng của phong cách Wabi-Sabi đương đại. Thiết kế hai vòng tròn lồng ghép mềm mại biểu trưng cho sự gắn kết và cân bằng, trở thành điểm nhấn tinh tế cho kệ tivi, bàn làm việc hoặc hộc tủ trang trí. Để sản phẩm luôn giữ vẻ đẹp mộc mạc nguyên bản, bạn chỉ cần dùng cọ mềm quét bụi định kỳ và tránh đặt tại mép bàn nơi dễ va quẹt.', 1, 5, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gốm nung men cát"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "18 x 7 x 22 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu be cát", "Màu đen nhám"]}], "totalElements": 1}', 1100, 1),
(1105, NOW(), NOW(), null, null, 'Khay gỗ tần bì hình chữ nhật lượn sóng đựng mỹ phẩm', 'NEST-DC-1105', 'khay-go-tan-bi-hinh-chu-nhat-luon-song-dung-my-pham', 'Khay gỗ tần bì với đường viền lượn sóng điệu đà giúp sắp xếp mỹ phẩm và trang sức gọn gàng đẹp mắt.', 'Sản phẩm được gia công tỉ mỉ từ gỗ tần bì tự nhiên, bề mặt được xử lý mài nhẵn mịn và phủ sáp ong kháng ẩm an toàn. Đường viền uốn lượn sóng tạo nét phá cách mềm mại, giúp tôn lên vẻ sang trọng của những chai nước hoa, đồ trang sức hay chìa khóa hàng ngày. Khay thích hợp để trên bàn phấn, đảo bếp hoặc bàn trà phòng khách. Tránh ngâm khay trong nước lâu, hãy lau khô ngay sau khi vệ sinh bằng khăn ẩm.', 1, 5, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tần bì tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "32 x 20 x 2 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Mộc mạc"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Kích thước 25 x 15 cm", "Kích thước 32 x 20 cm"]}], "totalElements": 1}', 600, 1),
(1106, NOW(), NOW(), null, null, 'Khay tròn bê tông mài đựng nến thơm trang trí bàn trà', 'NEST-DC-1106', 'khay-tron-be-tong-mai-dung-nen-thom-trang-tri-ban-tra', 'Khay tròn bê tông mài thô mộc dùng lót nến thơm và phụ kiện trang trí chuẩn phong cách công nghiệp nhẹ.', 'Chế tác từ chất liệu bê tông sợi thủy tinh cường độ cao, chiếc khay sở hữu độ cứng cáp vượt trội cùng các bọt khí tự nhiên đầy cá tính. Đáy khay được dán miếng đệm silicon giúp chống trầy xước bề mặt bàn và chống trơn trượt hiệu quả. Đây là phụ kiện lý tưởng để sắp xếp nến thơm, bình hoa nhỏ hay đồng hồ trên bàn trà, bàn làm việc. Bạn nên lau sạch vết bẩn bằng khăn ẩm nhẹ nhàng và tránh dùng hóa chất tẩy rửa mạnh.', 1, 5, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Bê tông mài mịn"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "25 x 25 x 2.5 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Đường kính 20 cm", "Đường kính 28 cm"]}], "totalElements": 1}', 1300, 1),
(1107, NOW(), NOW(), null, null, 'Bình hoa gốm đất nung dáng quả lê men tro tự nhiên', 'NEST-DC-1107', 'binh-hoa-gom-dat-nung-dang-qua-le-men-tro-tu-nhien', 'Bình hoa dáng quả lê mộc mạc với lớp men tro độc bản mang hơi thở Wabi Sabi.', 'Bình hoa gốm đất nung được vuốt tay thủ công từ làng nghề truyền thống, hoàn thiện bằng lớp men tro tự nhiên tạo bề mặt nhám sần độc đáo. Sản phẩm mang lại cảm giác an yên, trầm tĩnh, cực kỳ phù hợp khi cắm cành khô trên bàn trà phòng khách hay góc kệ sách Japandi. Để bảo quản, bạn nên lau chùi nhẹ nhàng bằng khăn mềm và tránh va đập mạnh làm mẻ miệng bình.', 1, 5, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gốm đất nung men tro"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "16 x 16 x 24 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Men tro xám nhạt", "Men tro nâu đất"]}], "totalElements": 1}', 1200, 1),
(1108, NOW(), NOW(), null, null, 'Tranh đắp nổi thạch cao khung gỗ tự nhiên tối giản', 'NEST-DC-1108', 'tranh-dap-noi-thach-cao-khung-go-tu-nhien-toi-gian', 'Tranh nghệ thuật đắp nổi thạch cao tạo hiệu ứng đổ bóng 3D thanh lịch cho bức tường.', 'Bức tranh sử dụng chất liệu vữa thạch cao hữu cơ đắp nổi thủ công trên nền toan, kết hợp khung viền gỗ sồi tự nhiên sang trọng. Hiệu ứng thị giác đổ bóng theo góc sáng mang đến chiều sâu nghệ thuật mà không phô trương, hoàn hảo treo tại mảng tường sau sofa hoặc sảnh đón nhà phố. Tránh treo tranh tại nơi ẩm thấp hoặc hứng nắng trực tiếp, chỉ cần phủi bụi định kỳ bằng chổi lông gà.', 1, 5, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Thạch cao và gỗ sồi"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "50 x 70 x 4 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Cỡ vừa 50x70 cm", "Cỡ lớn 60x80 cm"]}], "totalElements": 1}', 2800, 1),
(1109, NOW(), NOW(), null, null, 'Đồng hồ treo tường mặt đá bê tông kim trôi tĩnh lặng', 'NEST-DC-1109', 'dong-ho-treo-tuong-mat-da-be-tong-kim-troi-tinh-lang', 'Mặt đồng hồ bê tông đúc nguyên khối kết hợp kim trôi êm ái tuyệt đối khi hoạt động.', 'Sản phẩm được chế tác từ bê tông sợi khoáng đúc nguyên tấm với bề mặt phẳng mịn lì tự nhiên, điểm xuyết kim gỗ óc chó thanh mảnh. Bộ máy kim trôi siêu êm giúp không gian sống luôn giữ được sự tĩnh lặng tối đa, rất thích hợp treo phòng ngủ, góc làm việc hoặc thư viện gia đình. Bạn chỉ cần thay pin định kỳ mỗi năm một lần và vệ sinh bề mặt bằng khăn khô.', 1, 5, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Bê tông khoáng và gỗ óc chó"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "30 x 30 x 3 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Bê tông xám sáng", "Bê tông xám đậm"]}], "totalElements": 1}', 1600, 1),
(1110, NOW(), NOW(), null, null, 'Gương bàn trang điểm để bàn chân gỗ sồi hình hạt đậu', 'NEST-DC-1110', 'guong-ban-trang-diem-de-ban-chan-go-soi-hinh-hat-dau', 'Gương decor dáng hạt đậu viền mài mịn đặt trên đế gỗ sồi tự nhiên duyên dáng.', 'Gương trang trí để bàn nổi bật với phôi gương tráng bạc sắc nét, viền gương cắt lượn sóng mềm mại gắn vào đế gỗ sồi vững chãi. Thiết kế tạo điểm nhấn đầy cuốn hút cho bàn trang điểm phòng ngủ, kệ console lối vào hoặc bàn làm việc nhỏ xinh. Khi sử dụng, gương phản chiếu ánh sáng tự nhiên giúp căn phòng thêm thoáng đãng. Vệ sinh kính bằng dung dịch lau gương chuyên dụng và khăn cotton.', 1, 5, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Kính tráng bạc và gỗ sồi"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "28 x 12 x 35 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Hiện đại"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Gỗ sồi tự nhiên sáng", "Gỗ sồi sơn nâu hạt dẻ"]}], "totalElements": 1}', 950, 1),
(1111, NOW(), NOW(), null, null, 'Nến thơm hũ xi măng bấc gỗ mùi trà trắng và xạ hương', 'NEST-DC-1111', 'nen-thom-hu-xi-mang-bac-go-mui-tra-trang-va-xa-huong', 'Nến thơm tinh dầu thực vật trong hũ xi măng đúc, tiếng bấc gỗ nổ lách tách ấm áp.', 'Hũ nến làm từ xi măng mài mịn chứa đựng sáp cọ tự nhiên hòa trộn cùng tinh dầu trà trắng, xạ hương và cỏ vetiver thơm mát. Bấc gỗ khi cháy phát ra tiếng tí tách êm dịu, giúp xua tan căng thẳng sau ngày làm việc dài, rất thích hợp thắp trong phòng tắm thư giãn hoặc góc bàn đọc sách. Hãy cắt ngắn bấc còn khoảng 5mm trước mỗi lần thắp và đậy nắp chống bụi sau khi nguội.', 1, 5, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Sáp cọ và hũ xi măng mài"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "9 x 9 x 10 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng tắm"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Cỡ nhỏ 200g", "Cỡ lớn 350g"]}], "totalElements": 1}', 600, 1),
(1112, NOW(), NOW(), null, null, 'Tượng gốm trừu tượng khối rỗng nghệ thuật Bắc Âu', 'NEST-DC-1112', 'tuong-gom-truu-tuong-khoi-rong-nghe-thuat-bac-au', 'Tác phẩm tượng gốm mờ tạo hình khối rỗng mềm mại tôn vinh vẻ đẹp tối giản.', 'Được đúc từ chất liệu gốm sứ cao cấp tráng men mờ cát mịn, bức tượng mang đường nét uốn lượn liên hoàn rỗng ruột đậm chất nghệ thuật đương đại. Vật phẩm đem lại nét tao nhã, cân bằng cho các không gian kiến trúc nội thất mở như kệ tivi, vách ngăn phòng hoặc bàn trà trung tâm. Bạn nên đặt tượng ở bề mặt phẳng an toàn và lau nhẹ bằng khăn mềm ẩm khi bám bụi bẩn.', 1, 5, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gốm sứ tráng men mờ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "18 x 10 x 26 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng kem cát", "Đen mờ than chì"]}], "totalElements": 1}', 850, 1),
(1113, NOW(), NOW(), null, null, 'Khay mây đan họa tiết xương cá viền gỗ mộc mạc', 'NEST-DC-1113', 'khay-may-dan-hoa-tiet-xuong-ca-vien-go-moc-mac', 'Khay đựng đồ đan từ mây tre tự nhiên bền chắc viền gỗ tiện dụng cho bàn trà.', 'Sự kết hợp ăn ý giữa khung gỗ tần bì chắc khỏe và mặt đan mây tự nhiên theo họa tiết xương cá tinh xảo tạo nên nét mộc mạc đậm chất Á Đông. Khay rất tiện lợi để xếp ấm chén trà, ly nước phòng khách hoặc gom gọn nước hoa, phụ kiện trên bàn trang điểm. Tránh ngâm khay trong nước lâu ngày; nếu dính bẩn chỉ cần dùng chổi mềm phủi sạch và phơi ở nơi thoáng mát râm đãng.', 1, 5, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Mây tre đan và gỗ tần bì"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "35 x 25 x 4 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Mộc mạc"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Size M 35x25 cm", "Size L 42x30 cm"]}], "totalElements": 1}', 500, 1),
(1114, NOW(), NOW(), null, null, 'Khay nhôm đúc mạ đồng phay xước phong cách tối giản', 'NEST-DC-1114', 'khay-nhom-duc-ma-dong-phay-xuoc-phong-cach-toi-gian', 'Khay kim loại dập nổi phay xước màu đồng cổ điển sang trọng cho bàn tiếp khách.', 'Khay được đúc từ hợp kim nhôm siêu nhẹ mạ lớp đồng cổ với bề mặt phay xước mờ sang trọng, lòng khay uốn cong nhẹ nhàng tinh tế. Chiếc khay này đóng vai trò điểm nhấn tuyệt hảo để đặt cụm nến thơm, trang sức, chìa khóa ngay tủ giày tiền sảnh hoặc bàn ăn gia đình. Bạn chỉ cần lau khay bằng khăn khô mềm, tránh cọ rửa bằng búi kim loại để giữ bề mặt phay xước luôn mới.', 1, 5, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Hợp kim nhôm mạ đồng"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "26 x 18 x 2 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Hiện đại"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu đồng ánh kim", "Màu đen khói xước"]}], "totalElements": 1}', 450, 1),
(1115, NOW(), NOW(), null, null, 'Gương treo tường tròn viền gỗ sồi tự nhiên tối giản', 'NEST-DC-1115', 'guong-treo-tuong-tron-vien-go-soi-tu-nhien-toi-gian', 'Gương tròn viền gỗ sồi dày dặn mang đến nét mộc mạc và mở rộng thị giác không gian.', 'Gương treo tường tròn viền gỗ sồi tự nhiên được chế tác tỉ mỉ với phần khung gỗ uốn cong mượt mà, giữ trọn vẹn vân gỗ sáng ấm áp chuẩn phong cách Japandi. Phôi gương Bỉ cao cấp tráng bạc dày dặn cho hình ảnh phản chiếu chân thực, sắc nét và chống ố mốc vượt trội theo thời gian. Món đồ decor này lý tưởng để treo tại sảnh đón, bàn phấn phòng ngủ hoặc trên bồn rửa mặt phòng tắm. Bạn chỉ cần lau mặt kính bằng khăn mềm cùng nước lau kính chuyên dụng và tránh xịt hóa chất trực tiếp lên mép gỗ.', 1, 5, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên, phôi gương Bỉ tráng bạc 8 lớp"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "60 x 60 x 3.5 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách, phòng ngủ, phòng tắm"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Đường kính 50 cm", "Đường kính 60 cm", "Đường kính 70 cm"]}], "totalElements": 1}', 3800, 1),
(1116, NOW(), NOW(), null, null, 'Tranh vải Linen họa tiết trừu tượng khung gỗ tần bì mộc', 'NEST-DC-1116', 'tranh-vai-linen-hoa-tiet-truu-tuong-khung-go-tan-bi-moc', 'Bức tranh tối giản trên nền vải linen mộc mạc điểm xuyết nét vẽ trừu tượng giàu chất thiền.', 'Tranh vải linen họa tiết trừu tượng mang đậm tinh thần Wabi-Sabi với bề mặt sợi vải mộc mạc, kết hợp hài hòa cùng các mảng màu khoáng chất trung tính nhẹ nhàng. Phần khung viền làm từ gỗ tần bì tự nhiên giữ nguyên thớ vân sáng, tạo cảm giác thanh lịch và thư thái cho bức tường đơn điệu. Tác phẩm phù hợp treo phía trên sofa phòng khách, đầu giường ngủ hoặc góc tĩnh tâm tại bàn làm việc. Bạn nên treo tranh ở nơi khô ráo, tránh ánh nắng gắt chiếu trực tiếp và định kỳ quét bụi bằng chổi lông gà hoặc khăn khô mềm.', 1, 5, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải linen dệt thô, màu vẽ acrylic khoáng chất, khung gỗ tần bì tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "50 x 70 x 3 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách, phòng ngủ, phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Khổ 40x60 cm", "Khổ 50x70 cm", "Khổ 60x80 cm"]}], "totalElements": 1}', 1800, 1),
(1117, NOW(), NOW(), null, null, 'Bộ bát đĩa gốm sứ men mờ viền nâu phong cách mộc', 'NEST-DB-1117', 'bo-bat-dia-gom-su-men-mo-vien-nau-phong-cach-moc', 'Bộ bát đĩa gốm thủ công men mờ tông màu kem ấm cúng cho bữa cơm gia đình tròn vị.', 'Bộ bát đĩa chế tác từ đất sét nung nhiệt độ cao phủ men mờ mịn màng, mép viền vuốt nâu thủ công tinh tế. Cầm trên tay đầm chắc, giữ nhiệt món ăn tốt và mang lại nét mộc mạc thư thái cho bàn ăn phong cách Japandi. Sản phẩm an toàn trong lò vi sóng và máy rửa bát, hạn chế va đập mạnh và không dùng búi sắt chà xát bề mặt men.', 1, 6, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gốm sứ cao cấp men mờ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "26 x 26 x 15 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Set 8 món cho 2 người", "Set 16 món cho 4 người"]}], "totalElements": 1}', 3200, 1),
(1118, NOW(), NOW(), null, null, 'Chảo gang đúc tay cầm gỗ sồi chống dính tự nhiên', 'NEST-DB-1118', 'chao-gang-duc-tay-cam-go-soi-chong-dinh-tu-nhien', 'Chảo gang nguyên khối cán gỗ sồi cách nhiệt, tỏa nhiệt đều cho món áp chảo hoàn hảo.', 'Chảo gang đúc nguyên khối bền bỉ kết hợp cán gỗ sồi tự nhiên cầm êm ái, chống nóng hiệu quả khi nấu nướng. Khả năng tích nhiệt cao giúp bít tết xém cạnh vàng ươm, giữ trọn vị ngọt mọng nước cho căn bếp hiện đại. Dùng được trên mọi loại bếp kể cả bếp từ, cần tôi dầu định kỳ và lau khô ráo sau khi rửa để bảo vệ lớp chống dính tự nhiên.', 1, 6, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gang đúc nguyên khối, gỗ sồi"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "44 x 26 x 5 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "bếp"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Đường kính 24cm", "Đường kính 28cm"]}], "totalElements": 1}', 2100, 1),
(1119, NOW(), NOW(), null, null, 'Thớt gỗ Teak ghép đầu cây dày dặn bo cạnh tinh tế', 'NEST-DB-1119', 'thot-go-teak-ghep-dau-cay-day-dan-bo-canh-tinh-te', 'Thớt gỗ Teak tự nhiên vân gỗ ấm áp, hạn chế mùn dăm và bảo vệ lưỡi dao vượt trội.', 'Thớt được gia công từ gỗ Teak ghép thớ đầu cây chịu lực tốt, chứa lượng dầu tự nhiên giúp kháng ẩm mốc và không làm cùn lưỡi dao. Thiết kế bo tròn cạnh mềm mại tạo điểm nhấn trang nhã vừa để thái gọt vừa làm khay trình bày phô mai bánh mì. Sau khi dùng nên rửa sạch bằng nước ấm, lau khô ngay và thoa sáp ong định kỳ để vân gỗ luôn sáng bóng.', 1, 6, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ Teak tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "38 x 28 x 3 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Mộc mạc"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "bếp"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Size Vừa 35x25cm", "Size Lớn 40x30cm"]}], "totalElements": 1}', 1800, 1),
(1120, NOW(), NOW(), null, null, 'Bộ 4 ly thủy tinh khía gân sọc chịu nhiệt tối giản', 'NEST-DB-1120', 'bo-4-ly-thuy-tinh-khia-gan-soc-chiu-nhiet-toi-gian', 'Ly thủy tinh borosilicate vân sọc dọc tinh xảo, chịu sốc nhiệt tốt cho đồ uống lạnh ấm.', 'Sản phẩm làm từ thủy tinh borosilicate cao cấp trong suốt, họa tiết sọc dọc tạo hiệu ứng khúc xạ ánh sáng lấp lánh khi đựng cà phê hay nước ép. Cảm giác cầm nhẹ tay nhưng chắc chắn, phù hợp trên bàn làm việc lẫn bàn trà phòng khách tối giản. Ly chịu nhiệt từ âm 20 đến 150 độ C, dùng an toàn với máy rửa bát, tránh va chạm mạnh giữa các mép ly.', 1, 6, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Thủy tinh Borosilicate"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "8 x 8 x 12 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dáng thấp 280ml", "Dáng cao 380ml"]}], "totalElements": 1}', 680, 1),
(1121, NOW(), NOW(), null, null, 'Bộ dao bếp thép không gỉ cán gỗ tần bì cao cấp', 'NEST-DB-1121', 'bo-dao-bep-thep-khong-gi-can-go-tan-bi-cao-cap', 'Bộ dao sắc bén đa năng cán gỗ tần bì thanh lịch, trợ thủ đắc lực cho người yêu nấu nướng.', 'Lưỡi dao rèn từ thép không gỉ nguyên khối sắc bén, giữ độ sắc lâu và chống ăn mòn tối ưu trong môi trường ẩm. Cán gỗ tần bì vát cạnh công thái học mang lại cảm giác cầm đầm tay, thao tác cắt thái nhẹ nhàng chuẩn xác trong gian bếp Japandi. Nên rửa dao bằng tay với xà phòng dịu nhẹ, lau khô ngay lập tức và cất vào khay cắm chuyên dụng để giữ gìn lưỡi thép bén ngọt.', 1, 6, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Thép không gỉ 5Cr15Mov, gỗ tần bì"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "33 x 18 x 7 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "bếp"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Bộ 3 món cơ bản", "Bộ 5 món kèm kéo"]}], "totalElements": 1}', 1150, 1),
(1122, NOW(), NOW(), null, null, 'Hộp đựng thực phẩm thủy tinh nắp gỗ tre gioăng kín', 'NEST-DB-1122', 'hop-dung-thuc-pham-thuy-tinh-nap-go-tre-gioang-kin', 'Hộp thủy tinh đựng đồ khô nắp gỗ tre kín khí, giữ trọn hương vị và làm gọn gian bếp.', 'Thân hộp thủy tinh dày dặn không bám mùi, kết hợp nắp gỗ tre tự nhiên gắn vòng đệm silicone chống ẩm mốc và côn trùng tuyệt đối. Vẻ ngoài thanh thoát giúp góc kệ bếp hay bàn ăn trở nên ngăn nắp, dễ dàng quan sát hạt cà phê, trà hay ngũ cốc bên trong. Phần thân thủy tinh có thể rửa máy, nắp tre chỉ cần lau sạch bằng khăn ẩm và để nơi khô thoáng râm mát.', 1, 6, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Thủy tinh không chì, gỗ tre tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "10 x 10 x 18 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "bếp"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dung tích 750ml", "Dung tích 1100ml", "Dung tích 1600ml"]}], "totalElements": 1}', 900, 1),
(1123, NOW(), NOW(), null, null, 'Ấm trà gốm thô quai gỗ uốn men mờ chuẩn wabi sabi', 'NEST-DB-1123', 'am-tra-gom-tho-quai-go-uon-men-mo-chuan-wabi-sabi', 'Ấm trà gốm mộc quai gỗ uốn cong nhã nhặn, khơi gợi khoảnh khắc thưởng trà tĩnh lặng.', 'Ấm trà nung củi tạo bề mặt men mờ hạt cát độc bản, kết hợp quai xách gỗ uốn cong thủ công tạo nên vẻ đẹp thuần khiết đậm chất Wabi Sabi. Vòi rót ngắt nước dứt khoát, đi kèm lưới lọc gốm mịn giúp giữ trọn hương thơm thanh tao của lá trà trong không gian thiền định hay phòng khách mộc mạc. Vệ sinh bằng nước ấm sạch không dùng xà phòng tẩy mạnh để giữ lớp tráng men tự nhiên.', 1, 6, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gốm nung thô mộc, gỗ tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "16 x 14 x 13 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu Kem Tro", "Màu Nâu Đất"]}], "totalElements": 1}', 750, 1),
(1124, NOW(), NOW(), null, null, 'Khăn trải bàn vải Linen dệt thô tự nhiên tua rua', 'NEST-DB-1124', 'khan-trai-ban-vai-linen-det-tho-tu-nhien-tua-rua', 'Khăn trải bàn sợi lanh thô mộc điểm xuyết tua rua, mang lại vẻ lãng mạn Bắc Âu ấm cúng.', 'Được dệt từ sợi linen tự nhiên thoáng khí, khăn trải bàn có độ rủ mềm mại cùng nếp nhăn tự nhiên đặc trưng tôn lên nét đẹp phong trần kiểu Bắc Âu. Đường viền tua rua thắt tay tỉ mỉ tạo điểm nhấn ấm cúng cho bữa tối sum vầy hay các buổi tiệc trà cuối tuần. Nên giặt tay hoặc giặt máy chế độ nhẹ với túi giặt, phơi nơi râm mát và ủi khi vải còn ẩm nhẹ.', 1, 6, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "100% sợi Linen tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "140 x 180 x 0.2 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Màu Be Cát - 140x180cm", "Màu Be Cát - 140x220cm", "Màu Xám Tro - 140x180cm"]}], "totalElements": 1}', 520, 1),
(1125, NOW(), NOW(), null, null, 'Bộ bát đĩa gốm men tro hỏa biến thủ công Japandi', 'NEST-DB-1125', 'bo-bat-dia-gom-men-tro-hoa-bien-thu-cong-japandi', 'Bộ đồ ăn gốm mộc tráng men tro tự nhiên mang hơi thở tĩnh tại của nghệ thuật gốm thủ công Nhật Bản.', 'Sản phẩm được chế tác thủ công từ đất sét cao cấp nung ở nhiệt độ 1280 độ C, mang lại cốt gốm đanh chắc và bền bỉ. Lớp men tro hỏa biến tạo ra những vệt chuyển màu ngẫu hứng mộc mạc, đem đến cảm giác cầm nắm đầm tay và ấm cúng trên bàn ăn gia đình. Thiết kế tối giản này rất phù hợp với phòng ăn mang phong cách Japandi hoặc Wabi-Sabi tinh tế. Để giữ độ bóng đẹp lâu dài, bạn nên rửa bằng miếng bọt biển mềm và lau khô trước khi cất tủ.', 1, 6, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gốm nung nhiệt độ cao men tro tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "26 x 26 x 15 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Bộ 6 món", "Bộ 12 món"]}], "totalElements": 1}', 2800, 1),
(1126, NOW(), NOW(), null, null, 'Nồi sứ tráng men nắp gỗ chịu nhiệt kiểu Bắc Âu', 'NEST-DB-1126', 'noi-su-trang-men-nap-go-chiu-nhiet-kieu-bac-au', 'Nồi nấu tráng men gốm trắng tinh tế với núm nắp gỗ cách nhiệt, nấu nướng và bày trực tiếp tiện lợi.', 'Nồi được chế tạo từ nhôm đúc nguyên khối tráng men gốm đa lớp chống dính và kháng khuẩn vượt trội. Tay cầm nguyên khối kết hợp nắp kính phẳng viền silicon và núm gỗ dẻ gai cách nhiệt an toàn, mang lại trải nghiệm nấu nướng êm dịu, nhẹ nhàng. Sản phẩm thích hợp cho căn bếp mở hiện đại phong cách Bắc Âu hoặc Tối giản. Sau khi sử dụng, bạn nên để nồi nguội hẳn rồi vệ sinh bằng vải mềm với chất tẩy rửa dịu nhẹ.', 1, 6, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Hợp kim nhôm đúc phủ men gốm chống dính, núm gỗ dẻ gai"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "24 x 24 x 14 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "bếp"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Đường kính 20cm", "Đường kính 24cm"]}], "totalElements": 1}', 1650, 1),
(1127, NOW(), NOW(), null, null, 'Thớt gỗ xà cừ nguyên khối bo tròn kèm dây da treo', 'NEST-DB-1127', 'thot-go-xa-cu-nguyen-khoi-bo-tron-kem-day-da-treo', 'Thớt gỗ tự nhiên dày dặn vừa dùng cắt thái thực phẩm vừa làm khay phục vụ món ăn sang trọng.', 'Chiếc thớt được tiện gọt từ gỗ xà cừ tự nhiên tuyển chọn, bề mặt xử lý bóng mịn bằng dầu khoáng thực vật an toàn cho sức khỏe. Khi thái cắt thực phẩm, thớt cho cảm giác đầm chắc, bám mặt bàn và hạn chế làm cùn lưỡi dao. Thiết kế dáng oval bo tròn thanh thoát cùng dây da bò tự nhiên biến chiếc thớt thành khay decor hoàn hảo cho gian bếp mộc mạc. Bảo quản bằng cách rửa sạch dưới vòi nước, lau khô và định kỳ thoa sáp ong.', 1, 6, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ xà cừ tự nhiên nguyên khối phủ sáp ong, dây da bò"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "36 x 24 x 2.5 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Mộc mạc"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "bếp"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Cỡ vừa 20x30cm", "Cỡ lớn 24x36cm"]}], "totalElements": 1}', 1200, 1),
(1128, NOW(), NOW(), null, null, 'Bộ 2 cốc thủy tinh hai lớp cách nhiệt dáng tròn Muji', 'NEST-DB-1128', 'bo-2-coc-thuy-tinh-hai-lop-cach-nhiet-dang-tron-muji', 'Ly thủy tinh hai lớp thổi thủ công giúp giữ trọn nhiệt độ đồ uống mà không đọng sương trên thành ly.', 'Cốc thủy tinh hai lớp borosilicate cao cấp mang lại khả năng chịu sốc nhiệt vượt trội từ nóng sang lạnh mà không lo nứt vỡ. Cấu trúc chân không giúp giữ nhiệt đồ uống lâu hơn, cầm tay không bị bỏng nóng hay tê lạnh, tạo cảm giác lơ lửng thị giác đẹp mắt. Sản phẩm làm bừng sáng góc thưởng trà phòng khách hay bàn ăn tối giản. Hãy vệ sinh cốc nhẹ nhàng bằng tay và tránh va chạm mạnh ở đáy cốc nơi có nút thoát khí hàn kín.', 1, 6, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Thủy tinh borosilicate chịu nhiệt hai lớp thổi thủ công"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "9 x 9 x 11 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dung tích 250ml", "Dung tích 350ml"]}], "totalElements": 1}', 380, 1),
(1129, NOW(), NOW(), null, null, 'Bộ dao bếp gọt thái 3 món lưỡi thép cán gỗ dẻ gai', 'NEST-DB-1129', 'bo-dao-bep-got-thai-3-mon-luoi-thep-can-go-de-gai', 'Bộ ba dao làm bếp đa năng sắc bén với chuôi gỗ tự nhiên vừa vặn, tối ưu cho thao tác cắt gọt hàng ngày.', 'Bộ ba dao bếp chuyên dụng đáp ứng trọn vẹn nhu cầu sơ chế từ gọt củ quả, phi lê cá thịt đến băm thái thực phẩm gọn gàng. Lưỡi dao rèn từ thép không gỉ giữ cạnh sắc dài lâu, kết hợp cán gỗ dẻ gai gia công nhẵn mịn cho cảm giác cầm nắm chắc chắn, không trơn trượt. Thiết kế mang đường nét Bắc Âu thanh mảnh, tôn lên vẻ trang nhã cho khu vực nấu nướng. Để giữ dao luôn sáng bóng, nên rửa sạch bằng tay và lau khô ngay lập tức.', 1, 6, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Thép không gỉ mác cao, cán gỗ dẻ gai tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "32 x 5 x 2 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "bếp"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu gỗ sáng", "Màu gỗ óc chó"]}], "totalElements": 1}', 620, 1),
(1130, NOW(), NOW(), null, null, 'Bộ 3 hộp thủy tinh tròn nắp gỗ sồi gioăng silicon kín khí', 'NEST-DB-1130', 'bo-3-hop-thuy-tinh-tron-nap-go-soi-gioang-silicon-kin-khi', 'Hũ thủy tinh trong suốt nắp gỗ sồi kín hơi giúp bảo quản gia vị, hạt khô và trà luôn thơm mới.', 'Bộ ba hũ đựng thực phẩm thủy tinh cao cấp kết hợp nắp gỗ sồi tạo điểm nhấn ngăn nắp và ấm cúng cho kệ bếp. Chất liệu thủy tinh trong vắt giúp quan sát nguyên liệu bên trong dễ dàng, gioăng cao su silicon kín khít ngăn ngừa độ ẩm và côn trùng xâm nhập. Thiết kế xếp chồng tiện lợi, tối ưu hóa diện tích cho các căn hộ chung cư phong cách Japandi. Nắp gỗ chỉ cần lau qua khăn ẩm, còn thân hũ an toàn khi dùng trong máy rửa bát.', 1, 6, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Thủy tinh chịu nhiệt borosilicate trong suốt, nắp gỗ sồi tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "11 x 11 x 18 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "bếp"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Bộ 3 hộp vừa 600ml", "Bộ 3 hộp lớn 1000ml"]}], "totalElements": 1}', 950, 1),
(1131, NOW(), NOW(), null, null, 'Ấm trà thủy tinh lõi lọc gốm kèm quai xách gỗ uốn', 'NEST-DB-1131', 'am-tra-thuy-tinh-loi-loc-gom-kem-quai-xach-go-uon', 'Ấm pha trà thanh nhã với lõi lọc gốm mịn và quai xách gỗ cong, mang lại phút giây thưởng trà an yên.', 'Ấm trà là sự hòa quyện nhẹ nhàng giữa thân thủy tinh trong suốt và bộ lọc bên trong bằng gốm thô men mờ tự nhiên. Quai xách bằng gỗ uốn cong tạo cảm giác cầm rót êm ái, cách nhiệt hoàn hảo, cho phép bạn chiêm ngưỡng trọn vẹn sắc nước trà sóng sánh. Chiếc ấm rất thích hợp cho bàn trà phòng khách hay góc thư giãn đọc sách hơi hướng Wabi-Sabi. Nên tháo quai gỗ khi vệ sinh thân ấm và tránh sử dụng vật ráp chà xát bề mặt thủy tinh.', 1, 6, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Thủy tinh chịu nhiệt, lõi lọc gốm thô men mờ, quai gỗ uốn nhiệt"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "15 x 14 x 18 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dung tích 600ml", "Dung tích 800ml"]}], "totalElements": 1}', 540, 1),
(1132, NOW(), NOW(), null, null, 'Khăn trải bàn vải bố Cotton pha kẻ sọc tối giản Bắc Âu', 'NEST-DB-1132', 'khan-trai-ban-vai-bo-cotton-pha-ke-soc-toi-gian-bac-au', 'Khăn trải bàn sợi dệt tự nhiên dày dặn, họa tiết sọc nhã nhặn giúp không gian ăn uống thêm ấm cúng.', 'Khăn trải bàn dệt từ sợi bông tự nhiên pha lanh tạo độ rủ mềm mại cùng khả năng thấm hút mồ hôi và nước cực tốt. Bề mặt vải có gân dệt thô mộc, phối họa tiết sọc kẻ tinh giản mang lại cảm giác thân thiện, nhẹ nhõm cho mỗi bữa cơm quây quần. Phụ kiện này là lựa chọn lý tưởng để làm mới bàn ăn gỗ trong không gian Scandinavia hiện đại. Khuyến khích giặt tay hoặc giặt máy chế độ nhẹ, ủi ở nhiệt độ trung bình khi vải còn ẩm.', 1, 6, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải bố canvas dệt từ sợi cotton và lanh tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "220 x 140 x 0.2 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Size 140x180cm", "Size 140x220cm"]}], "totalElements": 1}', 460, 1),
(1133, NOW(), NOW(), null, null, 'Bộ bát đĩa gốm sứ bát tràng men kem chấm mè tối giản', 'NEST-DB-1133', 'bo-bat-dia-gom-su-bat-trang-men-kem-cham-me-toi-gian', 'Bộ bát đĩa gốm nung nhiệt độ cao phủ men kem chấm mè ấm cúng, thiết kế viền lượn nhẹ nhàng cho mâm cơm gia đình chuẩn vị Japandi.', 'Sản phẩm được chế tác từ đất sét tinh luyện nung ở nhiệt độ 1280 độ C, loại bỏ hoàn toàn chì và tạp chất độc hại. Lớp men kem bóng nhẹ điểm xuyết các hạt chấm mè tự nhiên tạo cảm giác mộc mạc mà sang trọng khi bày biện món ăn. Bề mặt nhẵn mịn dễ dàng vệ sinh, hạn chế trầy xước và bám màu dầu mỡ. Bộ sản phẩm rất phù hợp cho căn bếp gia đình theo đuổi lối sống tối giản hoặc các bữa tiệc ấm cúng kiểu Nhật. Lưu ý an toàn khi sử dụng trong lò vi sóng và máy rửa bát, tránh va đập mạnh mép bát đĩa.', 1, 6, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gốm sứ tráng men cao cấp"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "26 x 26 x 15 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Set 6 món cơ bản", "Set 10 món gia đình"]}], "totalElements": 1}', 3200, 1),
(1134, NOW(), NOW(), null, null, 'Chảo nhôm đúc chống dính vân đá đáy từ cán gỗ mộc', 'NEST-DB-1134', 'chao-nhom-duc-chong-dinh-van-da-day-tu-can-go-moc', 'Chảo chống dính nhôm đúc phủ lớp vân đá khoáng tự nhiên, kết hợp tay cầm gỗ cách nhiệt êm ái cho trải nghiệm nấu nướng nhẹ nhàng.', 'Chảo được đúc từ hợp kim nhôm nguyên khối truyền nhiệt nhanh và đều khắp đáy chảo, giúp tiết kiệm đáng kể năng lượng nấu nướng. Lòng chảo phủ lớp chống dính vân đá tự nhiên không chứa chất độc hại PFOA, đem lại cảm giác chiên rán lướt nhẹ mà không cần dùng nhiều dầu ăn. Tay cầm bằng gỗ sồi tiện tròn ôm tay, cách nhiệt hoàn hảo và tăng nét đẹp mộc mạc cho góc bếp. Sản phẩm bắt từ nhạy bén, thích hợp với mọi loại bếp từ hiện đại. Khuyến khích vệ sinh bằng giẻ mềm và tránh xả nước lạnh khi lòng chảo còn đang nóng.', 1, 6, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Hợp kim nhôm đúc, lớp chống dính vân đá, tay cầm gỗ sồi"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "46 x 24 x 6 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "bếp"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Đường kính 20 cm", "Đường kính 24 cm", "Đường kính 28 cm"]}], "totalElements": 1}', 1150, 1),
(1135, NOW(), NOW(), null, null, 'Thớt gỗ óc chó chữ nhật cắt rãnh hứng nước cao cấp', 'NEST-DB-1135', 'thot-go-oc-cho-chu-nhat-cat-ranh-hung-nuoc-cao-cap', 'Thớt gỗ óc chó tự nhiên sở hữu vân gỗ trầm ấm, thiết kế rãnh âm chống tràn thông minh mang đến nét thanh lịch cho không gian bếp.', 'Thớt được gia công từ khối gỗ óc chó tự nhiên có khả năng đàn hồi tốt, giúp bảo vệ độ bén sắc của lưỡi dao khi chặt thái thực phẩm. Bề mặt gỗ sẫm màu với các đường vân uyển chuyển, mang lại xúc cảm đầm tay và giá trị thẩm mỹ vượt trội khi dùng làm đĩa trình bày đồ nguội trên bàn tiệc. Rãnh khoét âm dọc theo bốn cạnh giúp giữ lại nước cốt thịt quả, giữ mặt bàn luôn sạch sẽ khô ráo. Sau khi vệ sinh bằng nước ấm, lau khô thớt và định kỳ thoa dầu khoáng chuyên dụng để giữ thớ gỗ bền đẹp lâu năm.', 1, 6, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ óc chó tự nhiên xử lý dầu sáp thực vật"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "38 x 26 x 2.5 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "bếp"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Cỡ vừa M (34 x 22 cm)", "Cỡ lớn L (38 x 26 cm)"]}], "totalElements": 1}', 1600, 1),
(1136, NOW(), NOW(), null, null, 'Bộ 6 cốc thủy tinh hổ phách đáy dày uống nước tối giản', 'NEST-DB-1136', 'bo-6-coc-thuy-tinh-ho-phach-day-day-uong-nuoc-toi-gian', 'Bộ cốc thủy tinh nhuộm màu trong trẻo với phần đáy đúc dày dặn, tôn vinh sắc thái các món đồ uống thanh mát mỗi ngày.', 'Bộ sản phẩm làm từ thủy tinh borosilicate cao cấp trong suốt, có độ bền cơ học tốt cùng khả năng chống sốc nhiệt khi thay đổi nhiệt độ đột ngột. Cầm trên tay tạo cảm giác đầm chắc nhờ phần đế dày vững chãi, miệng cốc vát tròn êm dịu khi thưởng thức cà phê, trà đá hay nước trái cây giải nhiệt. Gam màu thanh nhã phản chiếu ánh sáng tự nhiên tuyệt đẹp, mang lại phong thái thư thả chuẩn lối sống Bắc Âu trên bàn ăn. Cốc dùng an toàn trong máy rửa chén gia đình, không rửa chung với các vật sắc nhọn kim loại.', 1, 6, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Thủy tinh màu chịu nhiệt"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "8 x 8 x 10 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu hổ phách", "Màu xám khói"]}], "totalElements": 1}', 1200, 1),
(1137, NOW(), NOW(), null, null, 'Bộ dao làm bếp 4 món thép cacbon cao cán gỗ mun đen', 'NEST-DB-1137', 'bo-dao-lam-bep-4-mon-thep-cacbon-cao-can-go-mun-den', 'Bộ dao nhà bếp bằng thép tôi cứng sắc bén, tay cầm gỗ mun bo tròn cân đối giúp mọi thao tác sơ chế trở nên nhẹ nhàng chuẩn xác.', 'Lưỡi dao được rèn từ phôi thép cacbon chất lượng cao với góc mài tiêu chuẩn 15 độ, đem lại cảm giác cắt thái thực phẩm ngọt lịm mà không tốn nhiều sức bắp tay. Cán dao bằng gỗ mun tự nhiên gia công nhẵn mịn, có độ bám dính tốt kể cả khi bàn tay đang dính ướt. Bộ sản phẩm gồm đủ dao thái, dao gọt hoa quả, dao đa năng và kéo cắt thịt phục vụ linh hoạt cho gian bếp hiện đại. Để duy trì độ bền và vẻ đẹp tinh tế, nên rửa sạch bằng tay và lau khô lưỡi dao ngay sau mỗi lần làm bếp.', 1, 6, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Thép hợp kim hàm lượng cacbon cao, cán gỗ mun"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "33 x 18 x 5 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "bếp"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Bộ 4 món cơ bản", "Bộ 4 món kèm đế cắm gỗ"]}], "totalElements": 1}', 980, 1),
(1138, NOW(), NOW(), null, null, 'Bộ hộp bảo quản thực phẩm men sứ trắng nắp gỗ hút khí', 'NEST-DB-1138', 'bo-hop-bao-quan-thuc-pham-men-su-trang-nap-go-hut-khi', 'Hộp sứ trắng ngà kết hợp nắp gỗ tự nhiên trang bị gioăng hút khí, giúp thực phẩm và gia vị luôn giữ trọn vị tươi mới.', 'Thân hộp được chế tác bằng sứ tráng men trắng sáng mịn màng, hoàn toàn không bám mùi ôi thiu hay nhiễm vi khuẩn như các loại đồ nhựa thông thường. Nắp hộp tiện bằng gỗ tự nhiên có vòng gioăng silicon đàn hồi cao, ấn nhẹ để đẩy không khí thừa ra ngoài, giữ độ giòn thơm cho các loại hạt khô và thảo mộc. Thiết kế xếp chồng tiện lợi tạo nên không gian lưu trữ ngăn nắp, tinh tế cho kệ gia vị và tủ bếp phong cách tối giản. Thân sứ sử dụng thoải mái trong lò vi sóng, nắp gỗ chỉ cần vệ sinh bằng khăn ẩm.', 1, 6, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Sứ phủ men bóng, nắp gỗ cao su, gioăng silicon kín khí"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "12 x 12 x 16 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "bếp"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Set 2 hộp nhỡ 600ml", "Set 3 hộp đa cỡ (400ml, 700ml, 1000ml)"]}], "totalElements": 1}', 1450, 1),
(1139, NOW(), NOW(), null, null, 'Ấm pha trà bằng gang đúc họa tiết đinh tán thủ công', 'NEST-DB-1139', 'am-pha-tra-bang-gang-duc-hoa-tiet-dinh-tan-thu-cong', 'Ấm trà gang đúc truyền thống giữ nhiệt vượt trội, phủ men sứ lòng ấm cùng quai cầm chống bỏng mang đậm nét thiền Wabi-Sabi.', 'Ấm được đúc thủ công từ gang thô nguyên khối có khả năng giữ độ nóng của dòng nước trà kéo dài bền bỉ, giúp giải phóng hoàn hảo tinh dầu từ lá trà khô. Lòng ấm tráng lớp men sứ chịu nhiệt bảo vệ hương vị thuần khiết và ngăn chặn hiện tượng gỉ sét tự nhiên. Thân ngoài phủ lớp oxit đen mờ dập hoa văn đinh tán tạo cảm giác trầm lặng, bình dị khi đặt trên bàn trà góc phòng khách hay hiên nhà ngập nắng. Rửa sạch bằng nước nóng sau khi dùng, mở nắp để ấm khô ráo tự nhiên và tránh dùng miếng rửa kim loại cọ xát.', 1, 6, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gang đúc thủ công, lòng tráng men sứ, lưới lọc thép không gỉ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "18 x 15 x 16 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dung tích 600 ml", "Dung tích 900 ml"]}], "totalElements": 1}', 1350, 1),
(1140, NOW(), NOW(), null, null, 'Khăn trải bàn vải thô chống thấm họa tiết caro Bắc Âu', 'NEST-DB-1140', 'khan-trai-ban-vai-tho-chong-tham-hoa-tiet-caro-bac-au', 'Khăn bàn dệt từ sợi canvas pha bông mềm mại, phủ lớp nano trượt nước hữu hiệu tạo điểm nhấn ấm áp và tươi sáng cho phòng ăn.', 'Sản phẩm dệt từ chất liệu cotton canvas dày dặn nhưng vẫn giữ độ rũ tự nhiên, phủ lớp màng mỏng kháng chất lỏng giúp nước sốt hay cà phê rơi rớt không bị ngấm sâu vào sợi vải. Họa tiết kẻ ô vuông caro thanh lịch mang đến luồng sinh khí nhẹ nhõm, phù hợp cho cả bàn ăn gỗ sồi hàng ngày lẫn không gian tiệc trà ngoài ban công. Viền mép được may giấu chỉ tỉ mỉ, giúp khăn phẳng phiu và không xô lệch khi trải. Khăn giặt sạch nhanh chóng bằng máy ở chế độ giặt nhẹ, ủi phẳng ở nhiệt độ trung bình từ mặt sau.', 1, 6, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải cotton canvas dệt thô phủ nano chống thấm"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "140 x 180 x 0.2 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Kích thước 140 x 140 cm", "Kích thước 140 x 180 cm", "Kích thước 140 x 220 cm"]}], "totalElements": 1}', 560, 1),
(1141, NOW(), NOW(), null, null, 'Nồi gang đúc tráng men nắp nặng giữ nhiệt cao cấp Bắc Âu', 'NEST-DB-1141', 'noi-gang-duc-trang-men-nap-nang-giu-nhiet-cao-cap-bac-au', 'Nồi gang tráng men đối lưu nhiệt hoàn hảo giúp món hầm trọn vị, kiểu dáng tinh tế cho gian bếp ấm cúng.', 'Được chế tác từ gang đúc nguyên khối phủ men gốm láng mịn, chiếc nồi mang lại khả năng phân bổ và giữ nhiệt vượt trội. Nắp đậy thiết kế nặng với điểm ngưng tụ hơi nước giúp giữ trọn vẹn độ ẩm và hương vị tự nhiên của thực phẩm. Sản phẩm phù hợp cho các món kho, ninh nhừ hoặc nướng bánh, tương thích với mọi loại bếp kể cả bếp từ. Vẻ đẹp nhã nhặn biến chiếc nồi thành điểm nhấn tinh tế khi đặt trực tiếp lên bàn ăn Japandi. Vệ sinh bằng bọt biển mềm, tránh sốc nhiệt đột ngột.', 1, 6, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gang đúc nguyên khối phủ men gốm, núm nắp thép không gỉ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "24 x 24 x 16 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "bếp, phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Xanh Mint 20cm", "Trắng Kem 24cm"]}], "totalElements": 1}', 4200, 1),
(1142, NOW(), NOW(), null, null, 'Bộ 4 ly thủy tinh thấp uống rượu vang không chân Bắc Âu', 'NEST-DB-1142', 'bo-4-ly-thuy-tinh-thap-uong-ruou-vang-khong-chan-bac-au', 'Bộ ly thủy tinh pha lê không chân với thiết kế bo tròn thanh thoát, tôn lên sắc thái đồ uống trên bàn tiệc tối giản.', 'Bộ sản phẩm chế tác từ thủy tinh borosilicate cao cấp trong suốt, độ khúc xạ ánh sáng cao và chịu sốc nhiệt ấn tượng. Dáng ly không chân cách tân mang lại cảm giác đầm tay, hạn chế tối đa nguy cơ đổ ngã trong các bữa tiệc thân mật. Thiết kế miệng ly vát tinh tế giúp lưu giữ hương vị rượu vang, nước trái cây hoặc cà phê ủ lạnh. Bộ ly là mảnh ghép hoàn hảo cho không gian bàn ăn phong cách Scandinavian hiện đại. Nên rửa bằng khăn mềm hoặc máy rửa bát ở chế độ nhẹ nhàng.', 1, 6, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Thủy tinh pha lê không chì cao cấp"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "8.5 x 8.5 x 10.5 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn, bếp, phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trong Suốt 380ml", "Khói Mờ 380ml"]}], "totalElements": 1}', 650, 1),
(1143, NOW(), NOW(), null, null, 'Giỏ mây đan tự nhiên có quai cầm đựng quần áo đồ chơi', 'NEST-LT-1143', 'gio-may-dan-tu-nhien-co-quai-cam-dung-quan-ao-do-choi', 'Giỏ mây đan thủ công mộc mạc giúp sắp xếp chăn ga, quần áo hoặc đồ chơi gọn gàng và thẩm mỹ.', 'Sản phẩm được chế tác hoàn toàn từ sợi mây tự nhiên dẻo dai qua đôi bàn tay khéo léo của nghệ nhân Việt. Từng đường đan nong mốt tỉ mỉ tạo kết cấu vững chắc, mang lại hơi thở đồng nội bình yên cho không gian sống hiện đại. Giỏ cực kỳ thích hợp đặt cạnh sofa phòng khách để đựng gối tựa hoặc góc phòng ngủ chứa đồ giặt hàng ngày. Để sản phẩm bền đẹp dài lâu, nên đặt nơi khô ráo thoáng gió, tránh ẩm ướt và lau nhẹ bằng khăn ẩm khi dính bụi bẩn.', 1, 7, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Mây tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "38 x 38 x 42 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Size M", "Size L"]}], "totalElements": 1}', 1200, 1),
(1144, NOW(), NOW(), null, null, 'Hộp vải Linen đựng quần áo gấp gọn có quai da tối giản', 'NEST-LT-1144', 'hop-vai-linen-dung-quan-ao-gap-gon-co-quai-da-toi-gian', 'Hộp vải linen dệt thô thanh lịch giúp phân loại trang phục và tối ưu diện tích tủ quần áo hiệu quả.', 'Hộp được bọc lớp vải linen dệt sợi thô tự nhiên phối cùng khung carton cứng định hình vuông vắn, chống xẹp lún sau thời gian dài sử dụng. Tay cầm bằng da bò sáp vừa tạo điểm nhấn sang trọng vừa giúp bạn kéo hộp ra khỏi kệ tủ dễ dàng. Thiết kế có thể gấp phẳng khi không sử dụng, cực kỳ phù hợp cho tủ quần áo phòng ngủ hoặc kệ sách làm việc theo lối sống tối giản. Bạn nên dùng chổi lông quét nhẹ hoặc máy hút bụi cầm tay để vệ sinh bề mặt định kỳ.', 1, 7, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải linen, bìa cứng, quai da PU"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "40 x 30 x 25 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Beige sáng", "Xám khói"]}], "totalElements": 1}', 650, 1),
(1145, NOW(), NOW(), null, null, 'Kệ gỗ mini để bàn 2 tầng đựng mỹ phẩm sách vở tiện lợi', 'NEST-LT-1145', 'ke-go-mini-de-ban-2-tang-dung-my-pham-sach-vo-tien-loi', 'Kệ gỗ mini hai tầng nhỏ gọn tạo góc học tập và làm việc ngăn nắp, thoáng đãng chuẩn phong cách Muji.', 'Chiếc kệ được gia công từ chất liệu gỗ cao su tự nhiên đã qua xử lý sấy kỹ lưỡng, phủ sơn lót mờ chống mối mọt và hạn chế cong vênh. Cấu trúc hai tầng thông minh chia ngăn hợp lý, tạo cảm giác thư thái khi bày biện nước hoa, mỹ phẩm hay sổ tay ghi chép thường dùng. Sản phẩm là giải pháp giải phóng không gian lý tưởng cho bàn trang điểm, góc bàn làm việc hoặc bàn cạnh giường ngủ. Vệ sinh đơn giản bằng khăn mềm khô ráo, tránh ngâm nước hoặc phơi nắng gắt.', 1, 7, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ cao su tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "35 x 18 x 28 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Gỗ tự nhiên", "Trắng ấm"]}], "totalElements": 1}', 1800, 1),
(1146, NOW(), NOW(), null, null, 'Móc treo quần áo gắn tường gỗ sồi 5 chấu phong cách Bắc Âu', 'NEST-LT-1146', 'moc-treo-quan-ao-gan-tuong-go-soi-5-chau-phong-cach-bac-au', 'Móc treo tường thanh gỗ sồi nguyên khối bo góc mềm mại, tiện lợi móc áo khoác, mũ nón và túi xách.', 'Thanh treo chế tác từ gỗ sồi tự nhiên chắc chắn với những đường vân elip thanh nhã đặc trưng của vùng ôn đới. Năm chấu treo nghiêng góc 45 độ thông minh giúp giữ áo khoác, nón và túi xách không bị tuột rơi, đồng thời bảo vệ sợi vải khỏi rách xước. Thiết kế thanh thoát tôn lên nét ấm cúng cho huyền quan lối vào nhà, sau cánh cửa phòng ngủ hoặc sảnh chờ phòng khách. Lắp đặt kiên cố với đinh vít âm tường đi kèm và chỉ cần lau bằng khăn ẩm khi dọn dẹp nhà cửa.', 1, 7, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "50 x 6 x 8 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["4 Chấu", "5 Chấu"]}], "totalElements": 1}', 750, 1),
(1147, NOW(), NOW(), null, null, 'Hộp đựng trang sức bằng gỗ nắp kính lót vải nhung mềm', 'NEST-LT-1147', 'hop-dung-trang-suc-bang-go-nap-kinh-lot-vai-nhung-mem', 'Hộp gỗ mặt kính tinh xảo bảo quản nhẫn, dây chuyền và đồng hồ chống trầy xước, bám bụi hàng ngày.', 'Sản phẩm kết hợp hài hòa giữa khung gỗ tần bì nguyên khối ấm áp và mặt kính trong suốt giúp bạn dễ dàng chiêm ngưỡng món phụ kiện yêu thích. Lớp lót nhung màu be êm ái bên trong chia nhiều rãnh gài nhẫn, khay phẳng đựng đồng hồ và ngăn nhỏ cho hoa tai, mang lại trải nghiệm nâng niu từng món kỷ vật quý giá. Hộp đặt vừa vặn trên bàn phấn phòng ngủ, tăng thêm nét thanh lịch cho góc làm đẹp cá nhân. Tránh đặt ở môi trường ẩm ướt để giữ lớp nhung luôn mềm mịn.', 1, 7, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tần bì, kính cường lực, vải nhung"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "26 x 18 x 7 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Gỗ tự nhiên lót be", "Gỗ óc chó lót xám"]}], "totalElements": 1}', 950, 1),
(1148, NOW(), NOW(), null, null, 'Thùng nhựa đựng đồ đa năng nắp gỗ tre bo góc tối giản', 'NEST-LT-1148', 'thung-nhua-dung-do-da-nang-nap-go-tre-bo-goc-toi-gian', 'Thùng lưu trữ nhựa PP mờ nắp tre ép phẳng phiu, dễ dàng xếp chồng tiết kiệm diện tích tối đa.', 'Chiếc thùng làm từ chất liệu nhựa nguyên sinh PP không mùi, thân thiện với sức khỏe kết hợp nắp đậy phẳng làm từ tre ép tự nhiên. Tông màu trắng mờ cùng nắp gỗ mang lại cảm giác chỉn chu, sạch sẽ cho ngôi nhà, đồng thời giúp bạn xếp chồng nhiều tầng lên nhau rất kiên cố. Đây là vật dụng lưu trữ hoàn hảo cho góc bếp chứa đồ khô, phòng kho hay góc giặt là. Bề mặt nhẵn bóng chống bám bẩn hiệu quả, có thể rửa trực tiếp dưới vòi nước và phơi ráo nhanh chóng.', 1, 7, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Nhựa PP nguyên sinh, tre ép"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "36 x 26 x 22 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "bếp"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dung tích 12L", "Dung tích 18L"]}], "totalElements": 1}', 850, 1),
(1149, NOW(), NOW(), null, null, 'Giỏ cói tròn đan xếp tầng đựng đồ giặt quai cầm mộc mạc', 'NEST-LT-1149', 'gio-coi-tron-dan-xep-tang-dung-do-giat-quai-cam-moc-mac', 'Giỏ cói dáng chuông đan tay khéo léo dùng làm sọt quần áo bẩn hoặc chậu cây cảnh phòng khách bắt mắt.', 'Được đan tỉ mỉ từ những dải cói biển phơi khô tự nhiên mang màu sắc đồng quê nguyên bản cùng hương cỏ khô dìu dịu. Giỏ có độ đàn hồi tốt, hai quai xách bện chắc chắn chịu tải trọng lớn, giúp việc vận chuyển đồ đạc từ phòng ngủ sang khu giặt phơi nhẹ nhàng hơn. Chiếc giỏ đa năng này còn được ứng dụng để bọc ngoài chậu cây cảnh tạo điểm nhấn xanh mát mộc mạc cho ban công hay phòng khách. Bảo quản nơi râm mát, nếu bị ẩm cần hong khô trước quạt gió.', 1, 7, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Cói tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "35 x 35 x 40 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Mộc mạc"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng tắm"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Cói mộc tự nhiên", "Phối đáy trắng sơn mờ"]}], "totalElements": 1}', 900, 1),
(1150, NOW(), NOW(), null, null, 'Hộp mây tre đan thủ công có nắp đậy lưu trữ trà bánh', 'NEST-LT-1150', 'hop-may-tre-dan-thu-cong-co-nap-day-luu-tru-tra-banh', 'Hộp mây đan khít có nắp đậy kín đáo bảo quản trà bánh, bánh kẹo và phụ kiện nhỏ trên bàn trà gọn gàng.', 'Chiếc hộp sở hữu phom dáng chữ nhật vuông vắn đan xen giữa sợi tre cật và mây nước dẻo dai, phủ lớp dầu bóng thực vật bảo vệ chống ẩm mốc. Nắp đậy khít khao giúp che chắn bụi bặm tối đa, giữ cho các gói trà, cà phê hay bánh mứt tiếp khách luôn sạch sẽ và tinh tươm. Hộp mang vẻ đẹp mộc mạc đậm chất Wabi-Sabi, là món đồ trang trí đầy tính nghệ thuật trên bàn trà phòng khách hoặc kệ tủ phòng ăn. Lau sạch định kỳ bằng khăn khô mềm để giữ độ sáng bóng tự nhiên.', 1, 7, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Mây và tre tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "28 x 20 x 14 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu mây vàng ấm", "Màu hun khói mộc"]}], "totalElements": 1}', 580, 1),
(1151, NOW(), NOW(), null, null, 'Giỏ đựng đồ lục bình đan tay khung sắt phong cách mộc', 'NEST-LT-1151', 'gio-dung-do-luc-binh-dan-tay-khung-sat-phong-cach-moc', 'Giỏ lục bình tự nhiên đan tay tinh xảo kết hợp khung sắt chịu lực, giúp sắp xếp đồ đạc phòng khách và phòng ngủ luôn ngăn nắp, mộc mạc.', 'Sản phẩm chế tác hoàn toàn thủ công từ sợi lục bình phơi khô tự nhiên, liên kết vững chắc trên khung sắt sơn tĩnh điện định hình. Chiếc giỏ mang sắc nâu vàng ấm áp, tạo cảm giác mộc mạc và gần gũi cho không gian Japandi hoặc Wabi-Sabi. Sản phẩm cực kỳ thích hợp để lưu trữ chăn mỏng, gối tựa, sách báo tại phòng khách hoặc quần áo phòng ngủ. Để bảo quản bền lâu, bạn nên đặt giỏ nơi khô thoáng, tránh ẩm ướt kéo dài và dễ dàng vệ sinh bụi bẩn bằng khăn khô mềm hoặc máy hút bụi mini.', 1, 7, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Sợi lục bình tự nhiên, khung sắt sơn tĩnh điện"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "38 x 28 x 22 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Size Nhỏ (32 x 22 x 18 cm)", "Size Lớn (38 x 28 x 22 cm)"]}], "totalElements": 1}', 1100, 1),
(1152, NOW(), NOW(), null, null, 'Hộp vải canvas đựng đồ đa năng có nắp rời khung cứng cáp', 'NEST-LT-1152', 'hop-vai-canvas-dung-do-da-nang-co-nap-roi-khung-cung-cap', 'Hộp lưu trữ vải canvas cao cấp có nắp đậy kín đáo, thiết kế thanh lịch giúp tối ưu hóa không gian tủ đồ và kệ sách phòng ngủ.', 'Hộp đựng đồ chế tác từ chất liệu vải canvas dệt dày dặn kết hợp khung bìa nén cứng cáp, mang lại vẻ đẹp gọn gàng chuẩn phong cách tối giản Muji. Bề mặt vải mềm mịn, thoáng khí giúp bảo vệ trang phục, phụ kiện hay giấy tờ khỏi bụi bẩn ẩm mốc. Thiết kế nắp đậy rời tiện lợi cùng quai xách may tỉ mỉ hai bên giúp bạn dễ dàng kéo hộp ra khỏi kệ tủ quần áo hay bàn làm việc. Khi vệ sinh, chỉ cần dùng khăn ẩm lau nhẹ bề mặt và phơi gió tự nhiên.', 1, 7, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải canvas cotton, khung bìa nén cao cấp"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "40 x 30 x 25 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu Be Tự Nhiên", "Màu Xám Tro"]}], "totalElements": 1}', 850, 1),
(1153, NOW(), NOW(), null, null, 'Kệ gỗ tần bì mini 2 tầng lắp ráp để bàn làm việc gọn gàng', 'NEST-LT-1153', 'ke-go-tan-bi-mini-2-tang-lap-rap-de-ban-lam-viec-gon-gang', 'Kệ mini 2 tầng từ gỗ tần bì tự nhiên với đường nét vuông vức, tối ưu diện tích lưu trữ sách vở và đồ dùng bàn làm việc.', 'Kệ mini được gia công tỉ mỉ từ gỗ tần bì tự nhiên nguyên khối với vân gỗ sáng màu, bề mặt phủ sáp mờ mịn màng tôn lên vẻ đẹp Scandinavian tinh tế. Thiết kế 2 tầng nhỏ gọn mang lại giải pháp sắp xếp sổ tay, tài liệu, mỹ phẩm hoặc chậu cây nhỏ vô cùng ngăn nắp trên bàn làm việc hay bàn trang điểm. Kết cấu mộng gỗ chuẩn xác giúp tháo lắp dễ dàng và vững chãi. Bạn nên đặt kệ nơi khô ráo, tránh ánh nắng gắt trực tiếp và lau chùi định kỳ bằng khăn vải sợi mềm ẩm nhẹ.', 1, 7, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tần bì tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "35 x 18 x 28 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu Gỗ Mộc Sáng", "Màu Nâu Óc Chó"]}], "totalElements": 1}', 1400, 1),
(1154, NOW(), NOW(), null, null, 'Thanh móc treo quần áo gắn tường gỗ dẻ gai xếp gọn Bắc Âu', 'NEST-LT-1154', 'thanh-moc-treo-quan-ao-gan-tuong-go-de-gai-xep-gon-bac-au', 'Thanh móc treo tường gỗ dẻ gai với các chấu gập mở linh hoạt, giải pháp tiết kiệm không gian thông minh cho lối vào và phòng ngủ.', 'Được chế tác từ gỗ dẻ gai tự nhiên nhập khẩu, thanh móc sở hữu tông màu sáng ấm cùng các chấu treo có thể gập gọn sát bề mặt khi không dùng đến. Thiết kế thông minh chuẩn Bắc Âu này tạo cảm giác phẳng phiu, ngăn nắp tuyệt đối cho tiền sảnh, huyền quan hay phòng ngủ nhỏ. Sản phẩm chịu lực tốt, lý tưởng để treo áo khoác, mũ nón, túi xách hay khăn choàng hàng ngày. Để giữ gỗ luôn bền đẹp, bạn chỉ cần gắn chắc chắn lên tường gạch và lau bụi bằng khăn khô sạch.', 1, 7, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ dẻ gai tự nhiên (Beech wood)"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "50 x 6 x 3 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Bản 4 Chấu Treo", "Bản 6 Chấu Treo"]}], "totalElements": 1}', 650, 1),
(1155, NOW(), NOW(), null, null, 'Hộp đựng trang sức gỗ óc chó nhiều ngăn khóa đồng cổ điển', 'NEST-LT-1155', 'hop-dung-trang-suc-go-oc-cho-nhieu-ngan-khoa-dong-co-dien', 'Hộp đựng trang sức chế tác từ gỗ óc chó thượng hạng lót nhung êm ái, bảo quản nhẫn dây chuyền tinh tế cho bàn trang điểm.', 'Sản phẩm là sự giao thoa hoàn hảo giữa chất liệu gỗ óc chó tự nhiên trầm ấm và lớp lót vải nhung cao cấp chống trầy xước. Từng khay chia ngăn thông minh giúp phân loại nhẫn, vòng tay, hoa tai và đồng hồ một cách khoa học, kết hợp bản lề cùng khóa đồng phay xước cổ điển tạo điểm nhấn sang trọng. Hộp rất thích hợp đặt trên bàn trang điểm hoặc tủ đầu giường phòng ngủ Japandi. Để bảo quản, bạn nên tránh đặt hộp ở nơi ẩm thấp và thỉnh thoảng lau bề mặt gỗ bằng dầu dưỡng chuyên dụng.', 1, 7, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ óc chó Bắc Mỹ, phụ kiện đồng thau, lót nhung"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "26 x 18 x 12 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Thiết Kế 2 Tầng", "Thiết Kế 3 Tầng"]}], "totalElements": 1}', 1350, 1),
(1156, NOW(), NOW(), null, null, 'Thùng đựng đồ có nắp gấp gọn bọc vải dệt xơ đay quai cầm da', 'NEST-LT-1156', 'thung-dung-do-co-nap-gap-gon-boc-vai-det-xo-day-quai-cam-da', 'Thùng lưu trữ bọc vải xơ đay có nắp liền và quai cầm da bò, giữ đồ đạc gọn gàng và tạo điểm nhấn mộc mạc cho phòng khách.', 'Thùng đựng đồ đa năng được hoàn thiện từ sợi đay tự nhiên dệt thô mộc mạc kết hợp lớp lót vải cotton bền chắc, mang đậm tinh thần Wabi-Sabi tự do. Nắp đậy liền dính nhám tiện dụng giúp che giấu đồ chơi trẻ em, phụ kiện, quần áo mùa đông nhanh chóng mà vẫn đảm bảo tính thẩm mỹ cho phòng khách hay góc học tập. Quai xách bằng da thật đính đinh tán chắc chắn, thuận tiện di chuyển. Khi không dùng, thùng có thể gấp phẳng gọn gàng. Vệ sinh đơn giản bằng cách phủi bụi hoặc hút bụi nhẹ.', 1, 7, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải sợi đay tự nhiên, lót cotton, quai da bò"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "45 x 35 x 30 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dung Tích 35 Lít", "Dung Tích 47 Lít"]}], "totalElements": 1}', 1200, 1),
(1157, NOW(), NOW(), null, null, 'Giỏ mây tre đan quả chuông đựng quần áo bẩn thoáng khí', 'NEST-LT-1157', 'gio-may-tre-dan-qua-chuong-dung-quan-ao-ban-thoang-khi', 'Giỏ mây đan dáng quả chuông mộc mạc có nắp đậy, giải pháp đựng đồ giặt thông thoáng và tinh tế cho phòng tắm hay phòng ngủ.', 'Chiếc giỏ được đan tay khéo léo từ mây và tre tự nhiên đã qua xử lý sấy chống mốc kỹ lưỡng, tạo nên phom dáng quả chuông độc đáo đậm chất Á Đông. Mắt đan thưa thoáng khí giúp đồ giặt, khăn tắm không bị bốc mùi ẩm mốc, kết hợp nắp đậy kín đáo giữ cho không gian phòng tắm hay phòng ngủ luôn chỉn chu. Quai cầm hai bên uốn cong mềm mại hỗ trợ bưng bê dễ dàng sang khu vực giặt là. Bạn nên đặt giỏ ở vị trí khô ráo, tránh nước đọng và vệ sinh bằng chổi lông gà.', 1, 7, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Mây tre tự nhiên sấy khô"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "36 x 36 x 48 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng tắm"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Size Tiêu Chuẩn (Cao 48 cm)", "Size Đại (Cao 58 cm)"]}], "totalElements": 1}', 1600, 1),
(1158, NOW(), NOW(), null, null, 'Kệ mini gỗ tre đựng đồ nhà tắm 3 tầng chống ẩm tiện lợi', 'NEST-LT-1158', 'ke-mini-go-tre-dung-do-nha-tam-3-tang-chong-am-tien-loi', 'Kệ mini 3 tầng từ tre tự nhiên sơn phủ chống thấm, tối ưu lưu trữ khăn tắm, mỹ phẩm cho không gian phòng tắm và phòng làm việc.', 'Kệ mini chế tác từ gỗ tre tự nhiên ép khối bền dẻo, được xử lý sơn phủ bóng mờ chống thấm ẩm vượt trội, rất phù hợp với khí hậu nhiệt đới ẩm Việt Nam. Thiết kế 3 tầng thanh mảnh nhưng chắc chắn giúp bạn bài trí sữa tắm, dầu gội, nến thơm hoặc đồ dùng cá nhân gọn gàng trong góc phòng tắm hay cạnh bàn làm việc. Tông màu vàng tre tươi sáng mang đến cảm giác thư thái chuẩn phong cách spa tại gia. Bạn chỉ cần dùng khăn ướt vắt ráo lau chùi bề mặt kệ và giữ khu vực thông thoáng.', 1, 7, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tre ép khối tự nhiên chống ẩm"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "28 x 16 x 50 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Hiện đại"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng tắm"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu Tre Tự Nhiên", "Màu Trắng Kem"]}], "totalElements": 1}', 1750, 1),
(1159, NOW(), NOW(), null, null, 'Cây móc treo quần áo đứng gỗ sồi tự nhiên 8 nhánh Bắc Âu', 'NEST-LT-1159', 'cay-moc-treo-quan-ao-dung-go-soi-tu-nhien-8-nhanh-bac-au', 'Cây móc treo đứng bằng gỗ sồi tự nhiên với 8 chấu treo so le tiện lợi cho lối vào và phòng ngủ.', 'Cây treo quần áo được chế tác hoàn toàn từ gỗ sồi tự nhiên bền bỉ, bề mặt phủ sơn mờ chống ẩm mốc giúp giữ nguyên vân gỗ sáng ấm áp. Thiết kế 8 nhánh treo so le khoa học hỗ trợ treo áo khoác, nón mũ, túi xách gọn gàng mà không chiếm diện tích sàn. Đế tròn dày dặn tạo thế đứng vững chãi, hạn chế rung lắc khi treo đồ nặng. Sản phẩm rất thích hợp bài trí tại tiền sảnh, góc phòng ngủ hoặc phòng thay đồ phong cách Scandinavian. Vệ sinh bằng khăn mềm ẩm, tránh đặt sát nguồn nhiệt cao.', 1, 7, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "40 x 40 x 175 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu Gỗ Tự Nhiên", "Màu Nâu Óc Chó"]}], "totalElements": 1}', 4200, 1),
(1160, NOW(), NOW(), null, null, 'Hộp đựng trang sức nắp gập da PU 2 tầng khóa kim loại tinh tế', 'NEST-LT-1160', 'hop-dung-trang-suc-nap-gap-da-pu-2-tang-khoa-kim-loai-tinh-te', 'Hộp đựng trang sức 2 tầng bọc da PU thanh lịch kèm khóa gập mạ đồng bảo quản phụ kiện gọn gàng.', 'Sản phẩm bọc da PU cao cấp chống thấm nước kết hợp khung gỗ cứng cáp và lớp lót nhung nỉ mềm mịn bên trong, giúp bảo vệ nhẫn, vòng cổ, khuyên tai khỏi trầy xước. Thiết kế 2 tầng thông minh với khay chia ô linh hoạt và gương nhỏ tiện dụng khi phối phụ kiện mỗi ngày. Tông màu nhã nhặn mang hơi thở Japandi tinh tế, vừa tối ưu góc bàn trang điểm vừa làm vật trang trí sang trọng cho phòng ngủ. Khi bám bụi, chỉ cần lau nhẹ bề mặt da bằng khăn ẩm mềm và bảo quản nơi khô thoáng.', 1, 7, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Da PU, khung gỗ MDF, vải nhung"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "23 x 17 x 9 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng Kem", "Xanh Rêu Nhạt"]}], "totalElements": 1}', 850, 1),
(1161, NOW(), NOW(), null, null, 'Chậu cây kim tiền để bàn kèm đĩa lót gốm mộc Japandi', 'NEST-CX-1161', 'chau-cay-kim-tien-de-ban-kem-dia-lot-gom-moc-japandi', 'Cây kim tiền lá xanh bóng mượt trồng trong chậu gốm mộc kèm đĩa lót tinh tế, mang lại năng lượng tích cực cho góc làm việc.', 'Sản phẩm gồm cây kim tiền xanh tốt trồng trong chậu gốm mộc nung thủ công với lớp men mờ nền nã. Dáng cây nhỏ gọn, lá dày mọng nước mang ý nghĩa tài lộc và thanh lọc không khí hiệu quả. Thiết kế đậm chất Japandi tạo cảm giác an yên, gần gũi thiên nhiên, rất thích hợp bày trên bàn làm việc, kệ sách hoặc quầy lễ tân. Bạn chỉ cần tưới nước 1 đến 2 lần mỗi tuần khi đất mặt khô ráo và đặt nơi có ánh sáng tán xạ nhẹ.', 1, 9, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Cây kim tiền tự nhiên, chậu gốm nung men mờ, đĩa lót gốm"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "18 x 18 x 30 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Size Nhỏ Cao 25cm", "Size Vừa Cao 35cm"]}], "totalElements": 1}', 1800, 1),
(1162, NOW(), NOW(), null, null, 'Cây bàng singapore dáng thẳng trồng sẵn chậu xi măng đá mài', 'NEST-CX-1162', 'cay-bang-singapore-dang-thang-trong-san-chau-xi-mang-da-mai', 'Cây bàng Singapore phát triển khỏe mạnh trồng sẵn trong chậu xi măng đá mài bo tròn chuẩn phong cách Bắc Âu hiện đại.', 'Cây bàng Singapore sở hữu phiến lá bản to, xanh đậm bóng bẩy vươn đều quanh thân gỗ vững chãi. Đi kèm chậu xi măng đá mài nguyên khối chống thấm, bề mặt nhẵn mịn toát lên vẻ đẹp thanh lịch của nội thất Bắc Âu. Cây là điểm nhấn xanh lý tưởng cho góc sofa phòng khách, hành lang hay sảnh văn phòng. Để cây luôn tươi tốt, hãy đặt ở vị trí đón ánh nắng gián tiếp dồi dào, tưới đẫm nước khi đất khô khoảng 3cm và lau bụi trên lá định kỳ.', 1, 9, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Cây bàng Singapore sống, chậu xi măng đá mài phủ bóng chống thấm"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "40 x 40 x 130 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Chiều cao 1m1", "Chiều cao 1m4"]}], "totalElements": 1}', 12500, 1),
(1163, NOW(), NOW(), null, null, 'Chậu gốm mộc đáy tròn kèm đôn chân gỗ sồi Bắc Âu tối giản', 'NEST-CX-1163', 'chau-gom-moc-day-tron-kem-don-chan-go-soi-bac-au-toi-gian', 'Chậu gốm tráng men mờ thủ công kết hợp chân đôn gỗ sồi tự nhiên nâng tầm vẻ đẹp cho các dòng cây cảnh trong nhà.', 'Chậu gốm được nung ở nhiệt độ cao với cốt gốm đanh chắc, bề mặt phủ men mờ chống bám bẩn tinh xảo kết hợp cùng chân đôn làm từ gỗ sồi tự nhiên tiện tròn mộc mạc. Sự hòa quyện giữa chất liệu đất nung và gỗ mang đến cảm xúc ấm áp, tĩnh tại chuẩn tinh thần Wabi-Sabi và Bắc Âu. Chậu có lỗ thoát nước kèm nút cao su thông minh, thích hợp cho phòng khách, phòng ngủ hoặc góc đọc sách. Lau chùi chân gỗ bằng khăn mềm khô ráo.', 1, 9, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gốm nung tráng men mờ, chân gỗ sồi tự nhiên phủ sáp dầu"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "22 x 22 x 35 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Men Trắng Ngà", "Men Xám Khói", "Men Nâu Đất Nung"]}], "totalElements": 1}', 2600, 1),
(1164, NOW(), NOW(), null, null, 'Chậu cây trầu bà lỗ dây treo macrame thủ công phong cách mộc', 'NEST-CX-1164', 'chau-cay-trau-ba-lo-day-treo-macrame-thu-cong-phong-cach-moc', 'Cây trầu bà lá rách xum xuê kết hợp giỏ treo thắt dây macrame thủ công tạo mảng xanh rủ tự nhiên cho không gian hẹp.', 'Mẫu cây trầu bà lỗ Monstera Adansonii độc đáo với các đường xẻ tự nhiên trên phiến lá xanh biếc, được ươm dưỡng khỏe mạnh trong chậu đất nung mộc mạc. Giỏ treo bện từ sợi cotton thô theo kỹ thuật macrame tỉ mỉ, mang hơi thở phóng khoáng, mộc mạc cho ban công, khung cửa sổ hay góc thư giãn phòng tắm. Dáng lá rủ uyển chuyển giúp tiết kiệm diện tích sàn tối đa. Bạn chỉ cần phun sương giữ ẩm lá và tưới lượng nước vừa phải khi đất ráo mặt.', 1, 9, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Cây trầu bà lá rách, chậu đất nung, dây dệt cotton tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "20 x 20 x 75 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Mộc mạc"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "ban công"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Dây Treo Cotton Trắng", "Dây Treo Sợi Đay Mộc"]}], "totalElements": 1}', 1200, 1),
(1165, NOW(), NOW(), null, null, 'Bình thủy tinh terrarium rêu mini hệ kín nắp gỗ bần tinh tế', 'NEST-CX-1165', 'binh-thuy-tinh-terrarium-reu-mini-he-kin-nap-go-ban-tinh-te', 'Tiểu cảnh hệ sinh thái rêu tươi khép kín trong bình thủy tinh nắp gỗ bần mang lại cảm giác thư thái yên ả.', 'Bình terrarium là một tác phẩm nghệ thuật thu nhỏ mô phỏng khu rừng nhiệt đới với thảm rêu tươi tự nhiên, đá cuội nham thạch và sỏi trang trí tuyển chọn. Lớp vỏ thủy tinh borosilicate cao cấp trong suốt kết hợp nắp gỗ bần kín khí giúp duy trì độ ẩm hoàn hảo, gần như không cần tốn công chăm sóc. Sản phẩm là điểm nhấn thư giãn tuyệt vời cho bàn làm việc, kệ đầu giường phong cách tối giản. Đặt bình nơi mát mẻ, tránh ánh nắng trực tiếp gay gắt.', 1, 9, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Thủy tinh borosilicate trong suốt, rêu cushion tự nhiên, gỗ bần"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "15 x 15 x 22 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dáng Trụ Thẳng 15cm", "Dáng Cầu Tròn 20cm"]}], "totalElements": 1}', 950, 1),
(1166, NOW(), NOW(), null, null, 'Cây oliu giả cao cấp thân gỗ thật trái đen phong cách Bắc Âu', 'NEST-CX-1166', 'cay-oliu-gia-cao-cap-than-go-that-trai-den-phong-cach-bac-au', 'Cây oliu nhân tạo tỉ mỉ với thân gỗ thật và tán lá bạc đan xen quả chín mọng, đem hơi thở Địa Trung Hải thanh tao.', 'Cây oliu giả được chế tác tinh xảo với thân làm từ cành gỗ tự nhiên qua xử lý chống ẩm mốc, kết hợp cành lá lụa phủ màng PE cao cấp tái hiện chân thực sắc xanh bạc đặc trưng cùng quả đen nhỏ nhắn. Sản phẩm không tốn công tưới nước hay cắt tỉa, luôn giữ trọn vẻ tươi mới quanh năm cho căn hộ phong cách Scandinavian hay Japandi. Phù hợp bày cạnh tủ tivi, góc phòng ăn hay huyền quan. Vệ sinh dễ dàng bằng khăn ẩm hoặc chổi lông mềm.', 1, 9, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Thân gỗ tự nhiên xử lý nhiệt, lá vải lụa phủ PE, chậu đúc sẵn đáy"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "55 x 55 x 150 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Chiều cao 1m2", "Chiều cao 1m6"]}], "totalElements": 1}', 4500, 1),
(1167, NOW(), NOW(), null, null, 'Cây bonsai tùng la hán giả chậu men tro chân mộc chuẩn Japandi', 'NEST-CX-1167', 'cay-bonsai-tung-la-han-gia-chau-men-tro-chan-moc-chuan-japandi', 'Cây bonsai tùng la hán nhân tạo uốn thế nhã nhặn trong chậu gốm men tro, thể hiện trọn vẹn tinh thần thiền định Wabi-Sabi.', 'Tác phẩm tùng la hán để bàn được tạo tác công phu với từng chùm lá kim nhựa dẻo mềm mại, lớp phủ phấn mờ sống động như cây thật. Chậu gốm men tro hỏa biến thô mộc cùng lớp rêu nhân tạo phủ kín gốc tạo nên chiều sâu nghệ thuật thị giác đậm chất Thiền định phương Đông. Sản phẩm hoàn hảo cho góc trà đạo, bàn làm việc gỗ tự nhiên hay kệ trang trí phòng ngủ tĩnh lặng. Bạn hoàn toàn không cần chăm sóc, chỉ cần phủi bụi định kỳ để giữ màu sắc luôn tươi sáng.', 1, 9, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Nhựa mềm silicone đúc khuôn, chậu gốm men tro, rêu bảo tồn"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "28 x 16 x 32 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Dáng Trực Đứng", "Dáng Huyền Nghiêng"]}], "totalElements": 1}', 1600, 1),
(1168, NOW(), NOW(), null, null, 'Cây bạch đàn giả lá bạc chậu gốm sứ tối giản Bắc Âu tươi mới', 'NEST-CX-1168', 'cay-bach-dan-gia-la-bac-chau-gom-su-toi-gian-bac-au-tuoi-moi', 'Cành lá khuynh diệp nhân tạo phủ phấn sương nhẹ nhàng cắm chậu gốm sứ trắng thanh lịch, thắp sáng mọi góc nhỏ tối tăm.', 'Cây bạch đàn lá tròn Eucalyptus nhân tạo với tông màu xanh xám phủ phấn mờ đặc trưng mang đến vẻ đẹp nhẹ nhàng, thư thái chuẩn mực của phong cách nội thất Bắc Âu. Cành cây có lõi thép dẻo bên trong giúp bạn tùy ý uốn nắn tạo dáng xòe rộng tự nhiên theo sở thích cá nhân. Chậu gốm sứ trắng bóng nhẹ đi kèm hoàn thiện diện mạo tinh tế cho bàn trang điểm, kệ lavabo hay hộc tủ đầu giường. Cây bền màu tuyệt đối, dễ làm sạch bằng khăn ẩm.', 1, 9, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Nhựa PE cao cấp phủ phấn mờ, cành lõi thép uốn, chậu gốm sứ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "30 x 30 x 75 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Chiều cao 65cm", "Chiều cao 85cm"]}], "totalElements": 1}', 1400, 1),
(1169, NOW(), NOW(), null, null, 'Chậu cây đa búp đỏ mini để bàn men gốm mờ tối giản', 'NEST-CX-1169', 'chau-cay-da-bup-do-mini-de-ban-men-gom-mo-toi-gian', 'Cây đa búp đỏ khỏe khoắn kết hợp chậu gốm men nhám thanh lịch, thanh lọc không khí và mang sắc xanh tươi mới cho bàn làm việc.', 'Cây đa búp đỏ tươi tốt trồng trong chậu gốm thủ công tráng men mờ tao nhã, mang lại nét chấm phá sinh động chuẩn tinh thần Japandi. Tán lá bóng bẩy dày dặn cùng gam màu đỏ tía sang trọng giúp không gian làm việc thêm phần tĩnh tại và khơi nguồn cảm hứng sáng tạo. Sản phẩm rất thích hợp bài trí trên bàn làm việc, kệ sách hay bậu cửa sổ phòng ngủ. Để cây sinh trưởng bền đẹp, bạn chỉ cần đặt ở nơi có ánh sáng tán xạ nhẹ và tưới nước định kỳ 1 đến 2 lần mỗi tuần khi bề mặt đất khô ráo.', 1, 9, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Cây tự nhiên, chậu gốm nung men mờ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "15 x 15 x 28 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Đường kính chậu 12cm", "Đường kính chậu 15cm"]}], "totalElements": 1}', 1200, 1),
(1170, NOW(), NOW(), null, null, 'Cây trầu bà thanh xuân trồng sẵn chậu gốm khía Bắc Âu', 'NEST-CX-1170', 'cay-trau-ba-thanh-xuan-trong-san-chau-gom-khia-bac-au', 'Dáng cây xòe rộng bề thế với phiến lá xẻ duyên dáng, đi kèm chậu gốm sọc khía trang nhã tô điểm góc phòng khách hiện đại.', 'Cây trầu bà thanh xuân nổi bật với những phiến lá xẻ sâu mềm mại, được ươm trồng kỹ lưỡng trong chậu gốm dập khía thanh lịch phong cách Scandinavian. Tán lá xòe rộng xanh mướt mang đến nguồn năng lượng tràn đầy sức sống và cảm giác bình yên thư thái cho tổ ấm. Cây thích hợp đặt tại góc sofa phòng khách, hành lang hoặc sảnh đón khách rộng rãi. Cây ưa bóng râm bán phần, bạn nên lau bụi trên lá bằng khăn ẩm mềm và tưới ẩm vừa đủ từ 2 đến 3 lần mỗi tuần.', 1, 9, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Cây tự nhiên, chậu gốm sứ cao cấp"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "50 x 50 x 85 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Chiều cao 70cm", "Chiều cao 90cm"]}], "totalElements": 1}', 5500, 1),
(1171, NOW(), NOW(), null, null, 'Chậu trồng cây gốm mộc vuốt tay kèm đĩa lót dáng trụ tròn', 'NEST-CX-1171', 'chau-trong-cay-gom-moc-vuot-tay-kem-dia-lot-dang-tru-tron', 'Chậu gốm dáng trụ tròn mộc mạc với bề mặt men thô tự nhiên, có lỗ thoát nước và đĩa hứng giữ sàn nhà luôn sạch sẽ.', 'Chậu trồng cây được nghệ nhân vuốt tay tỉ mỉ từ đất sét tự nhiên, bề mặt phủ lớp men thô xước nhẹ đậm chất thẩm mỹ Wabi-Sabi mộc mạc. Thiết kế dáng trụ tròn tinh gọn đi kèm đĩa lót đồng bộ giúp ngăn nước tràn làm ố sàn gỗ hay bề mặt bàn trà. Sản phẩm phù hợp để trồng các loại cây cảnh nhỏ, sen đá hoặc thảo mộc trang trí bệ cửa sổ bếp và ban công. Sau thời gian sử dụng, bạn có thể dễ dàng vệ sinh chậu bằng khăn mềm và nước ấm để giữ màu men bền đẹp.', 1, 9, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gốm nung men thô mờ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "18 x 18 x 17 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "ban công"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng Ngà", "Xám Tro", "Đất Mộc"]}], "totalElements": 1}', 1600, 1),
(1172, NOW(), NOW(), null, null, 'Chậu cây thường xuân dây leo thả rủ kèm dây treo da thật', 'NEST-CX-1172', 'chau-cay-thuong-xuan-day-leo-tha-ru-kem-day-treo-da-that', 'Cây thường xuân xanh mướt rủ nhánh mềm mại, kết hợp giỏ treo quai da bò thủ công tối ưu không gian sống chật hẹp.', 'Cây thường xuân dáng thả rủ xanh mát được phối cùng chậu gốm men kem và dây treo da bò thuộc thủ công chắc chắn, mang đậm hơi thở mộc mạc Bắc Âu. Dáng cây uyển chuyển giúp làm mềm các góc cạnh thô cứng trong nhà, mang thiên nhiên dịu êm vào tầm mắt. Sản phẩm lý tưởng để treo trang trí cạnh cửa sổ phòng ngủ, góc thư giãn ban công hoặc mảng tường trống phòng khách. Bạn nên tưới phun sương nhẹ lên thân lá mỗi sáng và tránh treo cây trực tiếp dưới nắng gắt buổi trưa.', 1, 9, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Cây tự nhiên, chậu gốm sứ, dây da bò sáp"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "20 x 20 x 65 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Dây Da Nâu Bò", "Dây Da Đen Mộc"]}], "totalElements": 1}', 1100, 1),
(1173, NOW(), NOW(), null, null, 'Tiểu cảnh terrarium rêu đa giác khung đồng tối giản Bắc Âu', 'NEST-CX-1173', 'tieu-canh-terrarium-reu-da-giac-khung-dong-toi-gian-bac-au', 'Hệ sinh thái rêu sống và đá sỏi tí hon thu nhỏ trong bình kính đa giác viền đồng, mang vẻ đẹp bình yên cho góc bàn.', 'Bình tiểu cảnh terrarium được ghép nối từ những phiến kính trong suốt cùng khung kim loại mạ đồng cổ điển, tạo nên khối đa giác hình học độc đáo. Bên trong là một khu rừng mini tĩnh lặng gồm rêu bảo tồn, đá tự nhiên và sỏi cuội suối xếp lớp công phu. Vật phẩm đem lại cảm giác an yên sâu lắng, xua tan căng thẳng mệt mỏi khi đặt trên bàn đọc sách hay bàn làm việc. Bình giữ ẩm rất tốt, chỉ cần xịt sương nhẹ nhàng mỗi 2 đến 3 tuần một lần và đặt nơi thoáng mát râm mát.', 1, 9, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Kính cường lực mỏng, khung đồng, rêu sống, sỏi đá tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "16 x 16 x 18 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Đường kính 14cm", "Đường kính 18cm"]}], "totalElements": 1}', 1350, 1),
(1174, NOW(), NOW(), null, null, 'Cây monstera giả cao cấp 9 lá dáng tự nhiên kèm giỏ cói', 'NEST-CX-1174', 'cay-monstera-gia-cao-cap-9-la-dang-tu-nhien-kem-gio-coi', 'Cây trầu bà Nam Mỹ giả lá xẻ sống động như thật, đi kèm giỏ cói đan mộc mạc cho góc nhà luôn tươi xanh mà không cần chăm sóc.', 'Cây monstera nhân tạo cao cấp được chế tác tỉ mỉ từ nhựa PE dẻo phủ màng mờ sinh học, tái hiện chân thực từng đường gân lá xẻ và sắc xanh thẫm tự nhiên. Đi kèm cùng giỏ cói đan tay thủ công ấm áp, chậu cây mang hơi thở nhiệt đới đậm chất Japandi hiện đại vào không gian sống. Đây là giải pháp hoàn hảo cho phòng khách thiếu sáng, căn hộ bận rộn hay góc phòng ngủ máy lạnh. Cây luôn giữ được vẻ đẹp tươi mới quanh năm, chỉ cần dùng khăn khô lau nhẹ bụi bám định kỳ.', 1, 9, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Nhựa PE cao cấp, lõi kẽm định hình, giỏ cói tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "45 x 45 x 85 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Chiều cao 75cm", "Chiều cao 95cm"]}], "totalElements": 1}', 2200, 1),
(1175, NOW(), NOW(), null, null, 'Giường ngủ gỗ sồi tự nhiên bo góc tối giản Bắc Âu', 'NEST-PN-1175', 'giuong-ngu-go-soi-tu-nhien-bo-goc-toi-gian-bac-au', 'Giường ngủ gỗ sồi sở hữu đường nét bo cong mộc mạc, tạo cảm giác thư thái và an yên cho giấc ngủ.', 'Khung giường được chế tác hoàn toàn từ gỗ sồi nguyên khối kết hợp dát gỗ thông dẻo dai chịu lực. Kết cấu mộng gỗ truyền thống tăng độ vững chãi, hạn chế tiếng cọt kẹt khi trở mình. Sản phẩm mang vẻ đẹp bình dị, trang nhã, cực kỳ thích hợp cho các căn phòng ngủ Scandinavian hoặc Japandi ưa chuộng ánh sáng tự nhiên. Bạn chỉ cần lau sạch bụi bẩn bằng khăn mềm ẩm định kỳ, tránh đặt giường tại nơi có độ ẩm cao hoặc tiếp xúc trực tiếp ánh nắng gắt để giữ độ bền vân gỗ.', 1, 10, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên, dát giường gỗ thông"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 200 x 85 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["160 x 200 cm", "180 x 200 cm"]}], "totalElements": 1}', 48000, 2),
(1176, NOW(), NOW(), null, null, 'Giường bệt kiểu nhật khung gỗ tần bì phong cách Japandi', 'NEST-PN-1176', 'giuong-bet-kieu-nhat-khung-go-tan-bi-phong-cach-japandi', 'Giường bệt gỗ tần bì dáng thấp kiểu Nhật giúp tối ưu không gian và đem lại giấc ngủ sâu lắng.', 'Sản phẩm được gia công từ gỗ tần bì tự nhiên tuyển chọn, bề mặt chà nhám mịn và phủ sơn mờ an toàn cho sức khỏe. Thiết kế sát sàn vững chãi lấy cảm hứng từ phòng ngủ tatami truyền thống, mang đến cảm giác rộng rãi và tĩnh tại tuyệt đối. Giường rất hợp với các phòng ngủ diện tích vừa và nhỏ theo lối tối giản hay Wabi-Sabi. Trong quá trình sử dụng, nên định kỳ nâng nệm để thông thoáng dát giường và lau bụi bề mặt bằng khăn sợi khô mềm.', 1, 10, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tần bì tự nhiên sơn phủ gốc nước"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "180 x 200 x 25 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["160 x 200 cm", "180 x 200 cm"]}], "totalElements": 1}', 52000, 2),
(1177, NOW(), NOW(), null, null, 'Nệm foam hoạt tính nâng đỡ cột sống thoáng khí tối giản', 'NEST-PN-1177', 'nem-foam-hoat-tinh-nang-do-cot-song-thoang-khi-toi-gian', 'Nệm foam hoạt tính đa tầng hỗ trợ giải tỏa áp lực vùng lưng, mang lại sự êm ái và giấc ngủ tròn vẹn.', 'Lõi nệm kết hợp giữa foam mật độ cao nâng đỡ cơ học và lớp memory foam ôm sát đường cong cơ thể, giúp giải phóng áp lực các điểm tỳ nén hiệu quả. Lớp áo nệm dệt từ sợi tencel thoáng khí, mang lại bề mặt tiếp xúc mát mịn suốt bốn mùa. Sản phẩm là lựa chọn lý tưởng cho phòng ngủ hiện đại cần sự êm ái tối đa. Bạn nên lót tấm bảo vệ nệm phía trên, hút bụi nhẹ nhàng hàng tháng và tránh phơi trực tiếp dưới nắng nóng gắt.', 1, 10, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Memory foam tỷ trọng cao, vỏ bọc vải tencel"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 200 x 20 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["160 x 200 cm", "180 x 200 cm"]}], "totalElements": 1}', 22000, 2),
(1178, NOW(), NOW(), null, null, 'Nệm lò xo túi độc lập giảm rung lắc bọc vải dệt chần bông', 'NEST-PN-1178', 'nem-lo-xo-tui-doc-lap-giam-rung-lac-boc-vai-det-chan-bong', 'Nệm lò xo túi độc lập êm ái, cách ly chuyển động tốt giúp bạn có giấc ngủ sâu suốt đêm dài.', 'Hệ thống lò xo túi độc lập bằng thép tôi nhiệt luyện bền bỉ, giúp nâng đỡ độc lập từng vùng cơ thể và không làm phiền người bên cạnh khi xoay trở mình. Bề mặt chần bông êm ái cùng vải dệt kim co giãn bốn chiều đem lại sự thông thoáng vượt trội. Nệm rất phù hợp cho giường đôi trong các căn phòng ngủ sang trọng phong cách Bắc Âu. Để giữ form dáng ổn định, hãy xoay chiều đầu chân nệm sau mỗi ba tháng và sử dụng ga chống thấm.', 1, 10, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Lò xo thép carbon, đệm mút lót, vải dệt kim"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 200 x 25 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Hiện đại"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["160 x 200 cm", "180 x 200 cm"]}], "totalElements": 1}', 34000, 2),
(1179, NOW(), NOW(), null, null, 'Tủ quần áo gỗ sồi 2 cánh mở tay nắm âm tối giản Bắc Âu', 'NEST-PN-1179', 'tu-quan-ao-go-soi-2-canh-mo-tay-nam-am-toi-gian-bac-au', 'Tủ quần áo gỗ sồi thiết kế cánh mở mộc mạc, tối ưu khả năng lưu trữ đồ dùng ngăn nắp và gọn gàng.', 'Tủ được chế tác từ gỗ sồi tự nhiên đã xử lý tẩm sấy kỹ lưỡng, hạn chế cong vênh mối mọt trong môi trường nhiệt đới. Thiết kế tay nắm âm vát mép tinh tế cùng hệ ngăn treo và gấp khoa học giúp quần áo luôn phẳng phiu, ngăn nắp. Mẫu tủ mang tinh thần Bắc Âu phóng khoáng, rất hợp với phòng ngủ master hoặc phòng ngủ căn hộ chung cư. Bạn nên vệ sinh tủ định kỳ bằng khăn mềm ẩm, đặt gói hút ẩm bên trong vào mùa nồm ẩm.', 1, 10, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên kết hợp ván ép phủ veneer sồi"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "100 x 60 x 200 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Gỗ sồi tự nhiên", "Gỗ óc chó trầm"]}], "totalElements": 1}', 62000, 2),
(1180, NOW(), NOW(), null, null, 'Tủ quần áo cửa lùa mây mắt cáo khung gỗ tự nhiên Japandi', 'NEST-PN-1180', 'tu-quan-ao-cua-lua-may-mat-cao-khung-go-tu-nhien-japandi', 'Tủ áo cửa lùa mây đan tinh xảo giúp tiết kiệm diện tích mở cánh và tạo điểm nhấn thanh thoát, ấm áp.', 'Khung tủ bằng gỗ tần bì cứng cáp kết hợp mặt cánh lồng mây mắt cáo tự nhiên đan thủ công tỉ mỉ, tạo độ thoáng khí tuyệt đối cho quần áo bên trong. Hệ ray trượt cửa lùa vận hành êm ái, tối ưu diện tích cho những gian phòng ngủ khiêm tốn. Sản phẩm là mảnh ghép chuẩn mực cho không gian phòng ngủ Japandi mộc mạc và hoài niệm. Cần dùng chổi lông mềm quét bụi kẽ mây thường xuyên, bảo dưỡng bề mặt gỗ bằng sáp lau chuyên dụng.', 1, 10, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Khung gỗ tần bì tự nhiên, cánh cửa lồng mây đan mắt cáo"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "140 x 60 x 200 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Rộng 140cm", "Rộng 160cm"]}], "totalElements": 1}', 71000, 2),
(1181, NOW(), NOW(), null, null, 'Bàn trang điểm gỗ sồi kèm gương tròn phong cách Bắc Âu', 'NEST-PN-1181', 'ban-trang-diem-go-soi-kem-guong-tron-phong-cach-bac-au', 'Bàn trang điểm gỗ sồi kèm gương tròn nhỏ gọn, điểm xuyết nét đẹp thanh lịch và tiện nghi cho góc làm đẹp.', 'Bàn trang điểm được làm từ gỗ sồi tự nhiên với tông màu vân gỗ ấm cúng, tích hợp ngăn kéo ray trượt trơn tru cùng gương tròn viền gỗ thanh thoát. Kích thước gọn nhẹ giúp bạn dễ dàng bố trí cạnh đầu giường mà không tốn nhiều diện tích. Thiết kế nhẹ nhàng này rất thích hợp cho phòng ngủ phong cách Bắc Âu hoặc Japandi hiện đại. Khi vệ sinh, hãy xịt nước lau kính lên khăn riêng cho mặt gương và lau phần khung gỗ bằng khăn mềm ẩm ráo nước.', 1, 10, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên, mặt gương bạc chống ố"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "80 x 45 x 125 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu gỗ tự nhiên", "Màu nâu hạt dẻ"]}], "totalElements": 1}', 24000, 2),
(1182, NOW(), NOW(), null, null, 'Tấm đệm đầu giường bọc vải Linen đan cúc êm ái tối giản', 'NEST-PN-1182', 'tam-dem-dau-giuong-boc-vai-linen-dan-cuc-em-ai-toi-gian', 'Tấm đệm đầu giường bọc nệm êm ái mang đến điểm tựa lưng thư giãn khi đọc sách hay nghe nhạc trước khi ngủ.', 'Tấm tựa đầu giường sở hữu khung ván gỗ chắc chắn, lớp đệm mút dày bọc vải linen dệt thô mộc mạc, tạo cảm giác êm ái vượt bậc khi tựa lưng thư giãn. Tông màu trang nhã điểm xuyết hàng nút rút chìm tinh xảo biến chiếc giường đơn giản thành góc nghỉ ngơi sang trọng. Sản phẩm lý tưởng cho các phòng ngủ phong cách Japandi hoặc tối giản hiện đại. Bạn có thể tháo vỏ bọc bên ngoài để giặt nhẹ nhàng hoặc dùng máy hút bụi cầm tay vệ sinh định kỳ.', 1, 10, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Khung ván ép chuẩn E0, mút xốp êm, vải linen tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 10 x 70 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["160 x 70 cm", "180 x 70 cm"]}], "totalElements": 1}', 9500, 2),
(1183, NOW(), NOW(), null, null, 'Giường ngủ gỗ tràm chân cao phong cách Bắc Âu mộc mạc', 'NEST-PN-1183', 'giuong-ngu-go-tram-chan-cao-phong-cach-bac-au-moc-mac', 'Giường ngủ gỗ tràm tự nhiên chân cao thanh thoát mang lại cảm giác ấm cúng cho không gian nghỉ ngơi.', 'Sản phẩm được chế tác từ gỗ tràm bông vàng tự nhiên đã qua xử lý sấy kỹ lưỡng, hạn chế cong vênh và mối mọt hiệu quả. Bề mặt gỗ hoàn thiện sơn phủ mờ giữ trọn vân gỗ tự nhiên mộc mạc, kết cấu khung chắc chắn chịu lực tốt không phát ra tiếng cọt kẹt khi trở mình. Gầm giường cao 20 cm tạo độ thông thoáng tuyệt đối, thuận tiện cho robot hút bụi lau dọn hằng ngày. Thiết kế tinh giản hài hòa với phòng ngủ phong cách Bắc Âu hoặc Japandi. Vệ sinh khung giường bằng khăn mềm vắt ráo nước định kỳ.', 1, 10, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tràm tự nhiên, nan giường gỗ thông"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "165 x 205 x 90 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["160 x 200 cm", "180 x 200 cm"]}], "totalElements": 1}', 45000, 2),
(1184, NOW(), NOW(), null, null, 'Nệm cao su thiên nhiên nâng đỡ 7 vùng bọc vải kháng khuẩn', 'NEST-PN-1184', 'nem-cao-su-thien-nhien-nang-do-7-vung-boc-vai-khang-khuan', 'Nệm 100% mủ cao su thiên nhiên nâng đỡ trọn vẹn cột sống, mang lại giấc ngủ sâu êm ái mỗi đêm.', 'Nệm đúc nguyên khối từ 100% mủ cao su tự nhiên với thiết kế phân bổ lực 7 vùng trọng điểm giúp giảm áp lực lên vai, hông và cột sống. Cấu trúc bọt hở hàng triệu lỗ thông hơi hai mặt đem lại khả năng lưu thông khí vượt trội, không gây hầm bí lưng trong thời tiết oi bức. Áo nệm bằng vải dệt sinh học kháng khuẩn mềm mại, có khóa kéo tháo rời giặt giũ dễ dàng. Rất thích hợp cho người hay đau lưng và phòng ngủ thanh lịch. Tránh phơi nệm trực tiếp dưới ánh nắng gay gắt.', 1, 10, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Cao su thiên nhiên 100%, vỏ vải gấm xốp kháng khuẩn"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 200 x 10 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["160 x 200 x 10 cm", "180 x 200 x 10 cm"]}], "totalElements": 1}', 32000, 2),
(1185, NOW(), NOW(), null, null, 'Tủ quần áo gỗ tần bì 3 cánh mở ngăn kéo phẳng tối giản', 'NEST-PN-1185', 'tu-quan-ao-go-tan-bi-3-canh-mo-ngan-keo-phang-toi-gian', 'Tủ quần áo 3 cánh gỗ tần bì mộc mạc với khoang treo rộng rãi và ngăn kéo tiện ích cho phòng ngủ gọn gàng.', 'Tủ chế tác từ gỗ tần bì tự nhiên kết hợp gỗ dán phủ veneer vân tuyển chọn, phủ dầu mờ bảo vệ chống ẩm mốc. Thiết kế 3 cánh mở với bản lề giảm chấn êm ái, bên trong phân chia hợp lý gồm suốt treo áo dài, đợt chia tầng gấp quần áo và hai ngăn kéo tiện lợi chứa đồ lót phụ kiện. Phong cách tối giản không tay nắm lộ giúp mặt tủ liền mạch, tôn vẻ đẹp thanh thoát của gian phòng ngủ. Thường xuyên lau bụi bằng khăn sợi nhỏ khô và đặt túi hút ẩm góc tủ vào mùa nồm.', 1, 10, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tần bì tự nhiên kết hợp veneer tần bì"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "140 x 58 x 200 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu gỗ sồi tự nhiên", "Màu nâu hạt dẻ"]}], "totalElements": 1}', 68000, 2),
(1186, NOW(), NOW(), null, null, 'Bàn trang điểm gương lật đa năng khung gỗ tần bì nhỏ gọn', 'NEST-PN-1186', 'ban-trang-diem-guong-lat-da-nang-khung-go-tan-bi-nho-gon', 'Bàn phấn thông minh tích hợp gương lật và nhiều khay chia mỹ phẩm, tiết kiệm diện tích tối đa.', 'Thiết kế thông minh với cánh gương lật trợ lực êm ái, khi đóng nắp bàn biến thành bàn làm việc hoặc đọc sách gọn gàng. Bên dưới là hệ chia ngăn khoa học giúp phân loại son phấn, kem dưỡng và trang sức ngăn nắp. Khung bàn làm từ gỗ tần bì chắc chắn, xử lý nhẵn mịn từng góc cạnh bo tròn an toàn. Sản phẩm hoàn hảo cho các căn hộ diện tích vừa và nhỏ chuộng sự ngăn nắp phong cách Nhật Bản. Bảo quản mặt bàn bằng cách lau ngay khi dính vết mỹ phẩm dạng lỏng.', 1, 10, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tần bì tự nhiên, gương tráng bạc cao cấp"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "80 x 45 x 75 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu gỗ tự nhiên", "Màu cánh gián nhạt"]}], "totalElements": 1}', 18000, 2),
(1187, NOW(), NOW(), null, null, 'Tấm ốp đầu giường bọc vải boucle lông cừu rời êm ái', 'NEST-PN-1187', 'tam-op-dau-giuong-boc-vai-boucle-long-cuu-roi-em-ai', 'Tấm tựa đầu giường bọc vải lông cừu mềm mại, tạo điểm nhấn ấm áp và thư giãn khi tựa lưng đọc sách.', 'Tấm ốp sở hữu khung gỗ thông chịu lực bọc đệm mút D40 độ đàn hồi cao, phủ bên ngoài lớp vải boucle xù lông cừu ấm cúng và thời thượng. Cảm giác khi tựa lưng vô cùng mềm xốp, giảm mỏi cổ vai gáy sau một ngày làm việc dài. Mặt sau trang bị sẵn đai treo dán tường kiên cố, dễ dàng tự lắp đặt phía trên đầu giường mà không cần khoan đục phức tạp. Phù hợp nâng cấp giường bệt hoặc giường không đầu giường trong phòng ngủ Bắc Âu. Hút bụi nhẹ nhàng và giặt khô định kỳ phần vỏ.', 1, 10, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải boucle lông cừu, nệm mút D40, khung gỗ thông"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "180 x 10 x 70 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Trắng kem 1m6", "Trắng kem 1m8", "Xám be 1m8"]}], "totalElements": 1}', 8500, 2),
(1188, NOW(), NOW(), null, null, 'Giường pallet gỗ thông khò mịn dát cuộn tự nhiên gấp gọn', 'NEST-PN-1188', 'giuong-pallet-go-thong-kho-min-dat-cuon-tu-nhien-gap-gon', 'Dát giường gỗ thông cuộn gọn gàng, nâng đỡ nệm cách đất sạch sẽ chuẩn phong cách sống tối giản.', 'Sản phẩm gồm các thanh gỗ thông Chile tự nhiên được khò mịn, bo vát cạnh an toàn và liên kết bằng dải đai dù chịu lực siêu bền. Dát phản giúp nâng nệm cách mặt sàn 3.5 cm, ngăn ẩm mốc nệm mà vẫn giữ nguyên cảm giác ngủ bệt phóng khoáng đậm chất Wabi-Sabi. Khi không sử dụng chỉ cần cuộn tròn lại cất vào góc tủ hoặc dễ dàng chuyển nhà trọ. Lựa chọn tuyệt vời cho người trẻ sống tối giản và phòng ngủ nhỏ. Giữ sàn nhà khô ráo và lau thanh nan bằng khăn ẩm nhẹ.', 1, 10, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ thông Chile tự nhiên, đai vải dù polyester"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 200 x 3.5 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["140 x 200 cm", "160 x 200 cm", "180 x 200 cm"]}], "totalElements": 1}', 14000, 2),
(1189, NOW(), NOW(), null, null, 'Nệm topper lông vũ nhân tạo chần bông vải Cotton thoáng khí', 'NEST-PN-1189', 'nem-topper-long-vu-nhan-tao-chan-bong-vai-cotton-thoang-khi', 'Tấm làm mềm đệm topper dày 7 cm bọc sợi cotton êm ái như trải nghiệm giường ngủ khách sạn 5 sao.', 'Topper được nhồi sợi lông vũ nhân tạo microgel siêu mịn, tạo độ bồng bềnh êm ái tức thì cho chiếc nệm cũ đang bị cứng. Vỏ ngoài bằng vải cotton 100% dệt mật độ cao chống thoát sợi, thoáng khí mát mẻ và thấm hút mồ hôi tối đa suốt đêm. Bốn góc có đai chun co giãn ôm chặt vào nệm dưới giúp tấm topper cố định không xô lệch khi trở mình. Hoàn hảo để nâng cấp độ êm cho phòng ngủ gia đình. Nên vỗ đều các ô chần định kỳ và phơi nơi thoáng gió râm mát.', 1, 10, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Sợi microgel nhân tạo, vỏ bọc cotton 100%"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 200 x 7 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Hiện đại"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["160 x 200 cm", "180 x 200 cm"]}], "totalElements": 1}', 4200, 2),
(1190, NOW(), NOW(), null, null, 'Tủ quần áo cửa trượt gỗ sồi phối mặt trắng Bắc Âu hiện đại', 'NEST-PN-1190', 'tu-quan-ao-cua-truot-go-soi-phoi-mat-trang-bac-au-hien-dai', 'Tủ quần áo 2 cánh trượt ray nhôm mượt mà, tối ưu không gian cho căn hộ chung cư hiện đại.', 'Mẫu tủ kết hợp tinh tế giữa khung viền gỗ sồi tự nhiên cứng cáp và cánh tủ trượt phủ lớp melamine trắng mờ thanh nhã. Hệ thống ray trượt hợp kim nhôm giảm chấn giúp đóng mở nhẹ nhàng, không gây tiếng ồn và tiết kiệm diện tích mở cửa tối đa cho phòng ngủ hẹp. Bên trong bố trí hai khoang riêng biệt với thanh treo nhôm anodized và nhiều ngăn để đồ gấp rộng rãi. Phù hợp hoàn hảo với không gian nội thất Scandinavian tươi sáng. Lau sạch ray trượt định kỳ để cửa luôn vận hành êm.', 1, 10, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên, MDF chống ẩm phủ Melamine"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 60 x 200 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["160 x 200 cm", "180 x 200 cm"]}], "totalElements": 1}', 78000, 2),
(1191, NOW(), NOW(), null, null, 'Giường ngủ gỗ dẻ gai có ngăn kéo lưu trữ phong cách Bắc Âu', 'NEST-PN-1191', 'giuong-ngu-go-de-gai-co-ngan-keo-luu-tru-phong-cach-bac-au', 'Giường ngủ gỗ dẻ gai nhập khẩu tích hợp ngăn kéo tiện dụng, tối ưu không gian cho phòng ngủ gọn gàng.', 'Giường ngủ được gia công từ gỗ dẻ gai tự nhiên với vân sáng đều đặn, kết cấu mộng ghép chắc chắn chịu lực vượt trội. Hai hộc kéo dưới gầm cung cấp diện tích lưu trữ chăn màn tiện lợi, giảm bớt sự bừa bộn cho gian phòng. Sản phẩm mang lại cảm giác ấm cúng, nâng đỡ giấc ngủ sâu suốt đêm. Thiết kế thanh thoát cực kỳ phù hợp căn hộ chung cư hoặc nhà phố theo tinh thần Scandinavian. Vệ sinh bằng khăn mềm vắt ráo nước, tránh để nước đọng lâu trên bề mặt gỗ.', 1, 10, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ dẻ gai tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "200 x 160 x 85 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["1m6 x 2m", "1m8 x 2m"]}], "totalElements": 1}', 55000, 2),
(1192, NOW(), NOW(), null, null, 'Nệm bông ép kháng khuẩn gấp 3 vải gấm dệt kim Bắc Âu', 'NEST-PN-1192', 'nem-bong-ep-khang-khuan-gap-3-vai-gam-det-kim-bac-au', 'Nệm bông ép vỏ gấm dệt kim cao cấp với thiết kế gấp ba linh hoạt, nâng đỡ cột sống thẳng tự nhiên.', 'Nệm được ép nhiệt từ sợi bông polyester tinh khiết, mang lại độ phẳng vững chắc không lo xẹp lún sau nhiều năm sử dụng. Lớp áo bọc bằng vải gấm dệt kim mềm mịn, thoáng khí, kháng bụi mịn và hạn chế kích ứng da nhạy cảm. Cảm giác nằm vững chãi giúp giảm mỏi lưng hiệu quả, cực kỳ thích hợp cho người thích nệm cứng hoặc gia đình có người lớn tuổi. Thiết kế gấp 3 gọn gàng, phù hợp phòng ngủ nhỏ hoặc homestay. Giữ nệm ở nơi khô ráo, định kỳ hút bụi và xoay đầu nệm để duy trì độ đàn hồi.', 1, 10, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Lõi bông ép sợi polyester, vỏ vải gấm dệt kim"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 200 x 10 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["1m6 x 2m x 10cm", "1m8 x 2m x 10cm"]}], "totalElements": 1}', 16000, 2),
(1193, NOW(), NOW(), null, null, 'Tủ quần áo gỗ thông 2 cánh nan chớp thoáng khí Japandi', 'NEST-PN-1193', 'tu-quan-ao-go-thong-2-canh-nan-chop-thoang-khi-japandi', 'Tủ quần áo gỗ thông tự nhiên cánh chớp giúp lưu thông không khí, ngăn ẩm mốc tối ưu cho trang phục.', 'Tủ quần áo chế tác từ gỗ thông tự nhiên đã qua xử lý sấy kỹ lưỡng, nổi bật với hệ cánh nan chớp thủ công tinh xảo giúp quần áo luôn thoáng mát, không đọng mùi ẩm mốc. Bên trong chia ngăn khoa học gồm khoang treo áo dài và kệ gấp tiện lợi. Tông màu gỗ sáng mộc mạc đem lại cảm giác an yên, phù hợp phòng ngủ Japandi hoặc Wabi-Sabi. Lau chùi bằng khăn khô mềm, có thể đặt túi hút ẩm tự nhiên bên trong tủ để bảo quản trang phục tốt hơn.', 1, 10, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ thông New Zealand tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "90 x 55 x 190 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu gỗ mộc tự nhiên", "Màu nâu hạt dẻ"]}], "totalElements": 1}', 42000, 2),
(1194, NOW(), NOW(), null, null, 'Bàn trang điểm treo tường gỗ sồi kèm gương bầu dục nhỏ', 'NEST-PN-1194', 'ban-trang-diem-treo-tuong-go-soi-kem-guong-bau-duc-nho', 'Bàn trang điểm treo tường gỗ sồi tích hợp ngăn kéo nhỏ gọn và gương bầu dục tinh tế, tiết kiệm sàn phòng.', 'Bàn trang điểm treo tường được làm từ gỗ sồi Mỹ tự nhiên bền bỉ, bề mặt phủ sáp mờ tôn đường vân mềm mại. Thiết kế gắn tường thông minh giúp giải phóng mặt sàn, đi kèm một ngăn kéo chứa mỹ phẩm và gương bầu dục viền gỗ thanh mảnh. Khi ngồi trang điểm, người dùng cảm nhận sự gọn gàng và thư thái tuyệt đối. Món đồ là giải pháp tối ưu cho phòng ngủ khiêm tốn diện tích phong cách Bắc Âu. Lau chùi bề mặt gỗ bằng khăn hơi ẩm và lau gương bằng dung dịch chuyên dụng.', 1, 10, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên, gương tráng bạc"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "70 x 35 x 45 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu gỗ tự nhiên", "Màu nâu óc chó"]}], "totalElements": 1}', 12000, 2),
(1195, NOW(), NOW(), null, null, 'Tấm tựa đầu giường bọc nệm vải nỉ nhung đệm dày tối giản', 'NEST-PN-1195', 'tam-tua-dau-giuong-boc-nem-vai-ni-nhung-dem-day-toi-gian', 'Tấm tựa đầu giường êm ái bọc vải nỉ nhung mềm mại, bảo vệ lưng tựa khi đọc sách thư giãn trước giờ ngủ.', 'Tấm đệm tựa đầu giường sở hữu khung ván gỗ bọc mút D40 êm ái kết hợp lớp vỏ nỉ nhung mịn màng, ấm áp khi chạm vào. Đường chần nổi tinh tế tạo điểm tựa lưng vững chãi, nâng đỡ trọn vẹn cột sống khi đọc sách hoặc xem phim buổi tối. Gam màu trung tính thanh lịch tôn vinh nét hài hòa cho không gian phòng ngủ hiện đại và Japandi. Lắp đặt dễ dàng bằng cách móc treo cố định vào tường. Vệ sinh định kỳ bằng máy hút bụi đệm hoặc khăn ấm lau nhẹ vết bẩn nhỏ.', 1, 10, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Khung gỗ công nghiệp E1, mút D40, vỏ nỉ nhung cao cấp"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 8 x 60 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Rộng 1m6 - Be yến mạch", "Rộng 1m8 - Be yến mạch", "Rộng 1m6 - Xám tro"]}], "totalElements": 1}', 9500, 2),
(1196, NOW(), NOW(), null, null, 'Giường ngủ gỗ tần bì dát phản liền phong cách Japandi', 'NEST-PN-1196', 'giuong-ngu-go-tan-bi-dat-phan-lien-phong-cach-japandi', 'Giường ngủ gỗ tần bì chân thấp dát phản nguyên tấm, thiết kế mộc mạc mang năng lượng an tĩnh cho căn phòng.', 'Giường ngủ được sản xuất từ gỗ tần bì nguyên khối nhập khẩu, xử lý sấy chống cong vênh với vân gỗ dạng elip đặc sắc. Kết cấu chân thấp vững chãi và dát phản phẳng liền mạch giúp tương thích với nhiều dòng nệm khác nhau. Cảm giác nằm gần mặt đất tạo sự thư thái, bình yên đặc trưng của lối sống thiền tịnh Nhật Bản. Sản phẩm là điểm nhấn hoàn hảo cho không gian phòng ngủ Japandi và tối giản. Vệ sinh giường bằng chổi lông gà hoặc khăn mềm khô, hạn chế tiếp xúc ánh nắng gắt.', 1, 10, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tần bì tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "205 x 165 x 40 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["1m6 x 2m", "1m8 x 2m"]}], "totalElements": 1}', 60000, 2),
(1197, NOW(), NOW(), null, null, 'Bộ ga gối Cotton washed dệt mật độ cao tối giản Bắc Âu', 'NEST-CG-1197', 'bo-ga-goi-cotton-washed-det-mat-do-cao-toi-gian-bac-au', 'Bộ ga chun và vỏ gối cotton washed tự nhiên thoáng khí, thấm hút mồ hôi tối ưu mang lại giấc ngủ trọn vẹn.', 'Bộ sản phẩm được xử lý giặt mềm cotton washed giúp mặt vải có độ nhăn tự nhiên mộc mạc và êm dịu ngay từ lần chạm đầu tiên. Khả năng hút ẩm tuyệt vời cùng mật độ dệt dày dặn giữ cho bề mặt giường luôn khô ráo và mát mẻ quanh năm. Thiết kế gam màu đơn sắc nhã nhặn tôn vinh vẻ đẹp tinh giản cho phòng ngủ phong cách Bắc Âu hay Japandi. Sản phẩm giặt máy tiện lợi ở chế độ nhẹ, nên phơi trong bóng râm và hạn chế sấy ở nhiệt độ cao.', 1, 11, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "100% Cotton Washed"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 200 x 25 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["1m6 x 2m x 25cm - Xám khói", "1m8 x 2m x 25cm - Xám khói"]}], "totalElements": 1}', 1400, 1),
(1198, NOW(), NOW(), null, null, 'Gối nằm memory foam công thái học nâng đỡ cổ vai gáy', 'NEST-CG-1198', 'goi-nam-memory-foam-cong-thai-hoc-nang-do-co-vai-gay', 'Gối định hình công thái học ôm sát đường cong đốt sống cổ giúp giải tỏa áp lực và ngủ sâu suốt đêm.', 'Ruột gối đúc từ mút hoạt tính memory foam cao cấp có khả năng đàn hồi chậm và nâng đỡ chính xác đường cong sinh lý vùng cổ vai gáy. Thiết kế hai đầu cao thấp riêng biệt đáp ứng hoàn hảo cho cả thói quen nằm ngửa lẫn nằm nghiêng. Vỏ gối bọc vải dệt kim mềm mại, kháng khuẩn và thoáng khí, dễ dàng tháo rời để vệ sinh định kỳ. Sản phẩm phù hợp cho phòng ngủ gia đình hiện đại, lưu ý chỉ giặt vỏ ngoài và vệ sinh ruột gối bằng cách phơi nơi thoáng gió.', 1, 11, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Ruột Memory Foam, vỏ vải dệt kim tencel"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "50 x 30 x 10 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Hiện đại"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng viền xám", "Trắng viền be"]}], "totalElements": 1}', 950, 1),
(1199, NOW(), NOW(), null, null, 'Chăn dệt sợi bông waffle tổ ong 4 lớp phong cách Japandi', 'NEST-CG-1199', 'chan-det-soi-bong-waffle-to-ong-4-lop-phong-cach-japandi', 'Chăn đắp bốn mùa cấu trúc dệt tổ ong waffle nhẹ nhàng, thoáng khí và mang tính thẩm mỹ mộc mạc.', 'Chiếc chăn được tạo nên từ bốn lớp sợi bông nguyên chất đan cài theo cấu trúc rãnh tổ ong độc đáo giúp lưu thông không khí tuyệt vời. Cảm giác đắp nhẹ tênh, giữ ấm êm dịu khi bật điều hòa mùa hè và làm lớp phủ phụ ấm áp vào mùa đông. Tông màu tự nhiên mộc mạc hòa quyện lý tưởng với không gian phòng ngủ Japandi hay Wabi-Sabi. Bạn có thể giặt máy ở chu kỳ nhẹ nhàng bằng túi giặt và phơi phẳng để chăn giữ nguyên phom dáng mềm mại lâu bền.', 1, 11, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "100% Sợi bông tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "200 x 230 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Vàng be mộc", "Nâu caramel"]}], "totalElements": 1}', 1200, 1),
(1200, NOW(), NOW(), null, null, 'Tấm bảo vệ nệm chống thấm chần gòn kháng khuẩn thoáng khí', 'NEST-CG-1200', 'tam-bao-ve-nem-chong-tham-chan-gon-khang-khuan-thoang-khi', 'Tấm lót bọc nệm chần gòn êm ái kết hợp màng TPU chống thấm bảo vệ nệm tối đa khỏi bụi bẩn và chất lỏng.', 'Sản phẩm sở hữu cấu trúc thông minh với lớp mặt chần gòn êm xốp, bên dưới ép màng TPU chống thấm ngăn chặn hiệu quả nước tiểu trẻ em hoặc đồ uống đổ tràn. Lớp thun bọc quanh viền co giãn ôm chặt lấy thân nệm hạn chế xô lệch khi xoay trở người. Đây là giải pháp giữ gìn vệ sinh hoàn hảo cho mọi chiếc nệm trong phòng ngủ gia đình. Tấm bảo vệ có thể giặt máy cùng nước lạnh, tránh ủi trực tiếp và không dùng chất tẩy mạnh để giữ màng chống thấm bền bỉ.', 1, 11, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải cotton pha chần microfiber, đáy màng TPU"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "180 x 200 x 30 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["1m6 x 2m x 30cm", "1m8 x 2m x 30cm", "2m x 2m2 x 30cm"]}], "totalElements": 1}', 1100, 1),
(1201, NOW(), NOW(), null, null, 'Ga trải giường Linen pháp tự nhiên giặt mềm phong cách mộc', 'NEST-CG-1201', 'ga-trai-giuong-linen-phap-tu-nhien-giat-mem-phong-cach-moc', 'Ga giường vải lanh Pháp thuần khiết càng giặt càng mềm, mang nét đẹp tự nhiên mộc mạc và sang trọng.', 'Được dệt từ sợi lanh nhập khẩu từ Pháp, chiếc ga mang lại trải nghiệm nghỉ ngơi mát mẻ khác biệt nhờ khả năng tản nhiệt tự nhiên nhanh chóng. Bề mặt vải sở hữu những nếp nhăn duyên dáng đặc trưng, tôn lên tinh thần Wabi-Sabi và vẻ đẹp nguyên bản cho chốn nghỉ ngơi. Càng qua nhiều lần giặt, sợi linen càng trở nên mềm mại và êm ái với làn da nhạy cảm. Giặt sản phẩm bằng nước lạnh hoặc nước ấm nhẹ, phơi khô trong gió trời tự nhiên và tránh vắt quá khô.', 1, 11, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "100% Vải lanh tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "180 x 200 x 25 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng ngà", "Xanh olive nhạt", "Nâu đất mộc"]}], "totalElements": 1}', 980, 1),
(1202, NOW(), NOW(), null, null, 'Bộ chăn ga gối tencel Cotton sợi bạch đàn tự nhiên mát lạnh', 'NEST-CG-1202', 'bo-chan-ga-goi-tencel-cotton-soi-bach-dan-tu-nhien-mat-lanh', 'Bộ chăn ga phối sợi tencel từ bột gỗ bạch đàn mềm mượt như lụa, mát lịm tức thì và thân thiện môi trường.', 'Sự kết hợp tinh tế giữa sợi cellulose bạch đàn và cotton tuyển chọn tạo ra chất vải óng ả, mịn màng và mát dịu ngay khi ngả lưng. Khả năng kháng khuẩn tự nhiên cùng tốc độ bay hơi ẩm vượt trội biến bộ sản phẩm thành lựa chọn lý tưởng cho khí hậu nhiệt đới. Thiết kế trang nhã giúp làm bừng sáng gian phòng ngủ phong cách Bắc Âu thanh lịch. Khuyến khích giặt mặt trái của ga gối ở chế độ nhẹ nhàng, phơi nơi râm mát để giữ bề mặt vải luôn bóng mượt.', 1, 11, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "60% Tencel, 40% Cotton tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "200 x 220 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["1m6 x 2m - Xanh sương mù", "1m8 x 2m - Xanh sương mù"]}], "totalElements": 1}', 2200, 1),
(1203, NOW(), NOW(), null, null, 'Ruột gối nằm lông vũ nhân tạo microfiber êm ái kháng khuẩn', 'NEST-CG-1203', 'ruot-goi-nam-long-vu-nhan-tao-microfiber-em-ai-khang-khuan', 'Ruột gối nhồi sợi lông vũ nhân tạo microfiber siêu mịn, bồng bềnh êm ái nâng niu trọn vẹn đầu cổ.', 'Gối được nhồi hàng triệu sợi microfiber siêu nhỏ tái tạo cảm giác êm bồng tương tự lông vũ tự nhiên mà không gây mùi hay kích ứng da. Độ cao vừa phải cùng khả năng phục hồi phom dáng ấn tượng giúp phân bổ đều trọng lượng vùng đầu, mang đến cảm giác thư giãn sâu. Sản phẩm phù hợp cho mọi phong cách phòng ngủ từ mộc mạc đến hiện đại sang trọng. Vỏ ngoài dệt cotton mật độ cao chống trồi sợi bông, ruột gối có thể giặt máy nhẹ nhàng và phơi nắng định kỳ.', 1, 11, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Sợi Microfiber nhân tạo, vỏ bọc Cotton"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "50 x 70 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Tiêu chuẩn 50 x 70 cm", "Lớn 60 x 80 cm"]}], "totalElements": 1}', 1000, 1),
(1204, NOW(), NOW(), null, null, 'Chăn hè thu Cotton dệt xơ đậu nành siêu nhẹ kháng khuẩn Muji', 'NEST-CG-1204', 'chan-he-thu-cotton-det-xo-dau-nanh-sieu-nhe-khang-khuan-muji', 'Chăn mền mỏng nhẹ nhồi sợi xơ đậu nành tự nhiên mềm xốp, ấm áp vừa đủ cho giấc ngủ đêm hè se lạnh.', 'Chiếc chăn hè ứng dụng công nghệ nhồi xơ đậu nành sinh học có độ tơi xốp tự nhiên, tạo cảm giác đắp ôm người mềm mại và nhẹ như mây. Mặt vải ngoài dệt sợi cotton chải kỹ thấm hút mồ hôi tối ưu, đem lại sự thông thoáng tuyệt đối suốt đêm dài. Tông màu nhạt nền nã tô điểm hoàn hảo cho căn phòng mang hơi thở tối giản thanh bình. Bạn có thể giặt chăn trực tiếp trong máy giặt gia đình với nước lạnh, sau đó giũ nhẹ và phơi khô tự nhiên.', 1, 11, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Ruột xơ protein đậu nành, vỏ 100% Cotton"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "200 x 230 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Xanh ngọc pastel", "Trắng kem bơ"]}], "totalElements": 1}', 1350, 1),
(1205, NOW(), NOW(), null, null, 'Bộ drap giường Cotton satin 60s mềm mịn phối viền tối giản', 'NEST-CG-1205', 'bo-drap-giuong-cotton-satin-60s-mem-min-phoi-vien-toi-gian', 'Bộ chăn ga cotton satin 60s mềm mượt, mang lại cảm giác mát mẻ và tôn lên vẻ đẹp thanh lịch cho phòng ngủ.', 'Sản phẩm được dệt từ sợi cotton satin 60s mật độ cao, mang đến bề mặt trơn mịn, óng ả tự nhiên cùng khả năng thấm hút mồ hôi vượt trội suốt đêm dài. Tông màu đơn sắc phối viền chỉ tinh tế tạo điểm nhấn trang nhã, rất phù hợp với phòng ngủ phong cách Bắc Âu hoặc Japandi hiện đại. Bộ sản phẩm gồm một ga bọc nệm và hai vỏ gối nằm đồng bộ. Nên giặt bằng nước lạnh ở chế độ nhẹ, tránh sử dụng chất tẩy mạnh và phơi trong bóng râm thoáng gió để bảo toàn độ bền màu sợi vải.', 1, 11, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải cotton satin 60s dệt mật độ 300 sợi"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 200 x 30 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Bắc Âu"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["160 x 200 cm - Xám Khói", "180 x 200 cm - Xám Khói", "180 x 200 cm - Be Nhạt"]}], "totalElements": 1}', 1800, 1),
(1206, NOW(), NOW(), null, null, 'Ruột gối cao su thiên nhiên lượn sóng thoáng khí chống ngáy', 'NEST-CG-1206', 'ruot-goi-cao-su-thien-nhien-luon-song-thoang-khi-chong-ngay', 'Gối cao su thiên nhiên thiết kế lượn sóng công thái học, giúp nâng đỡ đốt sống cổ và duy trì giấc ngủ sâu.', 'Ruột gối đúc từ 100% cao su thiên nhiên đàn hồi cao với cấu trúc bọt hở giúp không khí lưu thông tối ưu, không gây bí bách khi nằm lâu. Thiết kế vòm sóng uốn lượn nâng đỡ chuẩn xác đường cong cổ gáy, giải tỏa áp lực cơ bắp và hỗ trợ giảm thiểu chứng ngáy ngủ hiệu quả. Gối phù hợp cho người hay đau mỏi cổ vai trong các không gian nghỉ ngơi thư thái phong cách Japandi. Lưu ý tháo rời áo gối để giặt máy định kỳ, ruột gối chỉ cần hong gió nơi thoáng mát, tuyệt đối không phơi trực tiếp dưới ánh nắng mặt trời.', 1, 11, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Cao su thiên nhiên 100%, vỏ cotton dệt kim"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "40 x 60 x 11 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Độ cao 9-11 cm (Tiêu chuẩn)", "Độ cao 11-13 cm (Dày)"]}], "totalElements": 1}', 1300, 1),
(1207, NOW(), NOW(), null, null, 'Chăn dệt sợi acrylic dày dặn họa tiết quả trám tua rua Bắc Âu', 'NEST-CG-1207', 'chan-det-soi-acrylic-day-dan-hoa-tiet-qua-tram-tua-rua-bac-au', 'Chăn dệt acrylic mềm xốp họa tiết quả trám cổ điển, hoàn hảo để đắp nhẹ hoặc phủ trang trí sofa, giường ngủ.', 'Chiếc chăn dệt họa tiết quả trám dập nổi kết hợp tua rua hai đầu mang đậm tinh thần phóng khoáng của nội thất Scandinavian. Chất liệu sợi acrylic tổng hợp cao cấp giữ ấm dịu nhẹ, bề mặt xốp mịn không gây ngứa ngáy hay rụng xơ bông khi sử dụng. Chăn là điểm nhấn decor ấm áp trên giường ngủ hay ghế sofa phòng khách trong những buổi tối thư giãn đọc sách. Nên giặt tay hoặc dùng túi giặt máy ở chu kỳ nhẹ với nước lạnh, giũ phẳng phơi ngang trên giá để giữ phom dáng nguyên vẹn theo thời gian.', 1, 11, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Sợi acrylic dệt xốp cao cấp"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "130 x 170 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Nâu Nâu Kem", "Vàng Mù Tạt", "Xám Ghi Nhạt"]}], "totalElements": 1}', 950, 1),
(1208, NOW(), NOW(), null, null, 'Tấm lót nệm chống trượt chần bông microfiber kháng khuẩn', 'NEST-CG-1208', 'tam-lot-nem-chong-truot-chan-bong-microfiber-khang-khuan', 'Tấm lót bảo vệ nệm chần bông microfiber êm ái, giữ nệm luôn sạch sẽ, chống bám bụi và thoáng khí tối đa.', 'Tấm bảo vệ nệm được cấu tạo từ lớp mặt vải cotton mềm mại cùng lõi bông microfiber chần quả trám đều đặn, mang đến cảm giác êm ái và ngăn ngừa bụi bẩn hiệu quả. Thiết kế bốn góc có đai thun bản lớn co giãn ôm sát nệm, chống xô lệch dù bạn xoay trở nhiều tư thế trong đêm. Sản phẩm thích hợp cho mọi loại nệm trong phòng ngủ gia đình phong cách tối giản. Có thể dễ dàng giặt máy với nước ấm dưới 40 độ C, phơi khô tự nhiên hoặc sấy ở nhiệt độ thấp để bông tơi xốp bền lâu.', 1, 11, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vỏ cotton dệt, ruột bông sợi microfiber 250gsm"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 200 x 3 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["160 x 200 cm", "180 x 200 cm", "200 x 220 cm"]}], "totalElements": 1}', 1500, 1),
(1209, NOW(), NOW(), null, null, 'Drap bọc nệm vải Linen thô mộc tone be phong cách wabi sabi', 'NEST-CG-1209', 'drap-boc-nem-vai-linen-tho-moc-tone-be-phong-cach-wabi-sabi', 'Drap bọc nệm vải linen tự nhiên mộc mạc, tạo cảm giác thoáng mát mùa hè và ấm áp dịu nhẹ vào mùa đông.', 'Sản phẩm được dệt hoàn toàn từ sợi lanh tự nhiên cao cấp đã qua xử lý giặt mềm, đem lại cảm giác mộc mạc, thoáng khí tuyệt đối và thấm hút mồ hôi cực tốt. Tông màu be đất tự nhiên tôn vinh triết lý thẩm mỹ Wabi Sabi mộc mạc, hòa quyện trọn vẹn cùng khung giường gỗ thô. Càng qua nhiều lần giặt, sợi linen càng trở nên mềm mại và dễ chịu hơn với làn da. Khuyên dùng nước giặt dịu nhẹ, không vắt xoắn mạnh, phơi khô trong gió tự nhiên để giữ lại nếp nhăn duyên dáng đặc trưng của chất vải.', 1, 11, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "100% sợi lanh tự nhiên (pure linen)"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 200 x 25 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["160 x 200 cm - Màu Be Đất", "180 x 200 cm - Màu Be Đất", "180 x 200 cm - Trắng Tự Nhiên"]}], "totalElements": 1}', 1200, 1),
(1210, NOW(), NOW(), null, null, 'Ruột gối ôm dài gòn bi nhân tạo nâng đỡ thân người êm ái', 'NEST-CG-1210', 'ruot-goi-om-dai-gon-bi-nhan-tao-nang-do-than-nguoi-em-ai', 'Ruột gối ôm dài nhồi gòn bi nhân tạo êm ái, đàn hồi tốt, mang lại sự dễ chịu trọn vẹn cho tư thế nằm nghiêng.', 'Ruột gối ôm sử dụng hạt gòn bi nhân tạo polyester cao cấp đã qua xử lý kháng khuẩn, chống vón cục và giữ độ bồng bềnh bền bỉ theo thời gian. Vỏ bọc cotton trắng dệt mật độ cao ngăn chặn xơ gòn bay ra ngoài, an toàn cho hệ hô hấp. Kích thước thon dài vừa vặn ôm trọn vòng tay, nâng đỡ hông và cột sống khi nằm nghiêng, tạo không gian ngủ ấm cúng chuẩn Japandi. Bạn nên vỗ nhẹ gối mỗi ngày để gòn tơi đều, thỉnh thoảng phơi ruột gối nơi nắng nhẹ để khử khuẩn và giữ mùi thơm mát.', 1, 11, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gòn bi polyester kháng khuẩn, vỏ cotton trắng"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "35 x 100 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["30 x 100 cm", "35 x 100 cm"]}], "totalElements": 1}', 1400, 1),
(1211, NOW(), NOW(), null, null, 'Bộ ga giường Cotton kẻ sọc nhuyễn vintage phong cách Bắc Âu', 'NEST-CG-1211', 'bo-ga-giuong-cotton-ke-soc-nhuyen-vintage-phong-cach-bac-au', 'Bộ ga giường cotton dệt sọc nhuyễn trang nhã, tạo nét trẻ trung và thoáng mát dễ chịu cho căn phòng ngủ.', 'Được may từ chất liệu cotton dệt từ sợi bông thiên nhiên, sản phẩm mang lại bề mặt mát nhẹ, thấm hút mồ hôi tốt và vô cùng thân thiện với làn da nhạy cảm. Họa tiết kẻ sọc nhuyễn tinh tế mang hơi thở Scandinavian hiện đại, dễ dàng phối hợp cùng nhiều gam màu nội thất gỗ sáng. Bộ gồm một ga chun bo góc và hai vỏ gối nằm tiện lợi. Khi giặt nên lộn trái, chọn chế độ giặt thường với nước mát và phơi nơi bóng mát để sợi vải luôn giữ được độ mềm mại, không bị phai màu.', 1, 11, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "100% cotton tự nhiên dệt sợi chải kỹ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 200 x 25 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["160 x 200 cm - Sọc Xanh Khói", "180 x 200 cm - Sọc Xanh Khói", "180 x 200 cm - Sọc Nâu Be"]}], "totalElements": 1}', 1350, 1),
(1212, NOW(), NOW(), null, null, 'Chăn chần bông hè thu sợi modal gỗ sồi mát mịn bo viền tinh tế', 'NEST-CG-1212', 'chan-chan-bong-he-thu-soi-modal-go-soi-mat-min-bo-vien-tinh-te', 'Chăn hè thu chất liệu modal từ gỗ sồi chần bông mỏng nhẹ, mang lại xúc cảm mát rượi và êm ái khi ngủ phòng điều hòa.', 'Chăn hè chần bông được may từ vải modal chiết xuất từ sợi gỗ sồi thiên nhiên, nổi bật với bề mặt mềm như lụa, mát lạnh tự nhiên và khả năng kiểm soát độ ẩm vượt trội. Lớp ruột chần bông lông vũ nhân tạo siêu mỏng nhẹ vừa đủ giữ ấm trong phòng máy lạnh mà không gây nặng ngực. Thiết kế bo viền tỉ mỉ, tông màu trung tính nhã nhặn tôn lên phong cách phòng ngủ Japandi thanh bình. Có thể giặt máy bằng túi giặt chuyên dụng với chế độ êm dịu, không là ủi ở nhiệt độ cao để bảo vệ sợi modal.', 1, 11, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải modal gỗ sồi cao cấp, ruột bông microfiber mỏng"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "200 x 220 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["200 x 220 cm - Xanh Xám Mờ", "200 x 220 cm - Trắng Sữa"]}], "totalElements": 1}', 1600, 1),
(1213, NOW(), NOW(), null, null, 'Tấm bảo vệ nệm sợi tre chống thấm 4 lớp kháng khuẩn thoáng khí', 'NEST-CG-1213', 'tam-bao-ve-nem-soi-tre-chong-tham-4-lop-khang-khuan-thoang-khi', 'Tấm bảo vệ nệm sợi tre 4 lớp chống thấm nước tuyệt đối, kháng khuẩn vượt trội và êm ái cho giấc ngủ gia đình.', 'Sản phẩm được dệt từ sợi tre bamboo thiên nhiên kết hợp lớp màng TPU chống thấm chuyên dụng, tạo cảm giác thoáng mát và êm dịu vượt trội khi tiếp xúc. Lớp chần bông mỏng tăng độ xốp nhẹ, ngăn ngừa nấm mốc và chất bẩn thấm sâu vào đệm. Thiết kế bo chun ôm sát nệm dày đến 30 cm, giữ bề mặt luôn phẳng phiu, phù hợp phòng ngủ gia đình hoặc khách sạn hiện đại. Dễ dàng tháo rời giặt máy chế độ nhẹ, tránh chất tẩy mạnh và phơi nơi bóng râm thoáng khí.', 1, 11, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải sợi tre bamboo, màng TPU chống thấm, gòn microfiber chần"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 200 x 30 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["1m6 x 2m", "1m8 x 2m", "2m x 2m2"]}], "totalElements": 1}', 1400, 1),
(1214, NOW(), NOW(), null, null, 'Gối ngủ vỏ kiều mạch tự nhiên nâng đỡ cổ vai gáy kiểu nhật', 'NEST-CG-1214', 'goi-ngu-vo-kieu-mach-tu-nhien-nang-do-co-vai-gay-kieu-nhat', 'Gối ngủ ruột vỏ kiều mạch tự nhiên nâng đỡ đốt sống cổ chuẩn xác, thoáng khí và mang lại giấc ngủ sâu kiểu Nhật.', 'Gối ngủ sở hữu phần ruột làm từ 100% vỏ hạt kiều mạch tự nhiên được sấy tiệt trùng, bọc ngoài bằng lớp vải cotton thô mộc thoáng khí. Các hạt kiều mạch tự do dịch chuyển theo từng tư thế nằm, giúp ôm sát đường cong đốt sống cổ và giảm căng thẳng cơ bắp vai gáy hiệu quả. Thiết kế mang đậm tinh thần thiền định Japandi, thích hợp cho phòng ngủ tối giản hoặc không gian nghỉ dưỡng tĩnh tại. Có thể điều chỉnh lượng vỏ bên trong bằng khóa kéo, vỏ gối giặt máy nhẹ nhàng, phơi ruột vỏ hạt dưới nắng nhẹ định kỳ.', 1, 11, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vỏ hạt kiều mạch tự nhiên tiệt trùng, vỏ bọc 100% cotton canvas"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "50 x 30 x 8 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu Be cát", "Màu Xám nhạt", "Màu Xanh chàm"]}], "totalElements": 1}', 1600, 1),
(1215, NOW(), NOW(), null, null, 'Rèm cửa vải Linen thô dệt tự nhiên cản sáng nhẹ', 'NEST-RT-1215', 'rem-cua-vai-linen-tho-det-tu-nhien-can-sang-nhe', 'Rèm cửa vải linen dệt thô mộc mạc, lọc sáng nhẹ nhàng tạo không gian sống thư thái chuẩn phong cách Japandi.', 'Rèm cửa vải linen thô mang đến vẻ đẹp mộc mạc và thanh lịch cho ngôi nhà. Chất liệu sợi lanh pha cotton dệt dày dặn cho độ rủ tự nhiên, giúp lọc bớt ánh nắng gay gắt nhưng vẫn giữ được độ sáng dịu nhẹ cho gian phòng. Sản phẩm rất phù hợp cho không gian phòng khách hoặc phòng ngủ mang âm hưởng Japandi và Scandinavian thư thái. Để giữ rèm bền đẹp và duy trì phom dáng mộc mạc, bạn nên giặt hấp hoặc giặt tay nhẹ nhàng với nước lạnh, phơi bóng râm và ủi ở nhiệt độ trung bình.', 1, 12, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải sợi lanh tự nhiên pha cotton"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "140 x 260 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng kem", "Be mộc", "Xám nhạt"]}], "totalElements": 1}', 1250, 1),
(1216, NOW(), NOW(), null, null, 'Rèm voan trắng xuyên sáng dệt sợi thô phong cách Bắc Âu', 'NEST-RT-1216', 'rem-voan-trang-xuyen-sang-det-soi-tho-phong-cach-bac-au', 'Rèm voan trắng mềm mại dệt sợi thô thoáng khí, đón sáng tự nhiên và giữ nét riêng tư tinh tế cho căn phòng.', 'Rèm voan mỏng tông trắng thanh khiết được dệt từ sợi polyester cao cấp mô phỏng thớ vải lanh nhẹ xốp. Tấm rèm mềm mại đón gió, nhẹ nhàng khuếch tán ánh sáng tự nhiên vào không gian mà vẫn đảm bảo tính riêng tư cho gia chủ. Mẫu rèm là lựa chọn hoàn hảo kết hợp cùng rèm chính tại cửa sổ phòng ngủ, ban công hay phòng khách phong cách Bắc Âu hiện đại. Khuyên dùng giặt máy với túi giặt ở chế độ nhẹ, không vắt xoắn mạnh và treo khô tự nhiên ngay sau khi giặt.', 1, 12, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Sợi polyester dệt hiệu ứng sợi thô"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "150 x 250 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["150 x 250 cm", "200 x 270 cm"]}], "totalElements": 1}', 650, 1),
(1217, NOW(), NOW(), null, null, 'Rèm cuốn cửa sổ cản sáng vải dệt phủ nhựa tối giản', 'NEST-RT-1217', 'rem-cuon-cua-so-can-sang-vai-det-phu-nhua-toi-gian', 'Rèm cuốn cửa sổ thiết kế phẳng gọn gàng, cản sáng cách nhiệt hiệu quả cho không gian làm việc và nghỉ ngơi.', 'Rèm cuốn cửa sổ sở hữu thiết kế phẳng phiu hiện đại với bề mặt dệt polyester phủ lớp cản nhiệt cao cấp. Rèm vận hành trơn tru nhờ trục cuốn trợ lực êm ái, hỗ trợ cản sáng đến 90% và cách nhiệt hiệu quả, giữ cho căn phòng luôn mát mẻ và riêng tư. Thiết kế gọn gàng rất phù hợp cho khung cửa sổ phòng làm việc, phòng ngủ nhỏ hoặc căn hộ chung cư hiện đại. Cách bảo quản vô cùng đơn giản: chỉ cần dùng khăn mềm ẩm hoặc máy hút bụi đầu lông mềm để lau sạch bụi bẩn định kỳ.', 1, 12, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải polyester phủ acrylic chống nắng"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "100 x 160 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["80 x 160 cm", "100 x 160 cm", "120 x 160 cm"]}], "totalElements": 1}', 1400, 1),
(1218, NOW(), NOW(), null, null, 'Thảm trải sàn phòng khách lông ngắn dệt họa tiết Bắc Âu', 'NEST-RT-1218', 'tham-trai-san-phong-khach-long-ngan-det-hoa-tiet-bac-au', 'Thảm phòng khách dệt lông ngắn êm ái, họa tiết hình học tối giản mang lại sự ấm cúng và sang trọng cho sàn nhà.', 'Chiếc thảm phòng khách lông ngắn được dệt từ sợi tổng hợp polypropylene cao cấp với mật độ dệt dày dặn, cho bề mặt êm dịu và không bị xẹp lún sau thời gian dài sử dụng. Họa tiết hình học tối giản tông màu trung tính mang đến hơi thở Bắc Âu ấm cúng, sang trọng cho khu vực sofa hay bàn trà. Thảm có khả năng chống bám bụi và chống tĩnh điện vượt trội. Bạn nên hút bụi 1 đến 2 lần mỗi tuần và xử lý ngay vết bẩn lỏng bằng khăn ẩm sạch kết hợp xà phòng dịu nhẹ.', 1, 12, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Sợi tổng hợp polypropylene, đế đay chống trượt"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 230 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["160 x 230 cm", "200 x 290 cm"]}], "totalElements": 1}', 5800, 1),
(1219, NOW(), NOW(), null, null, 'Thảm trải sàn dệt phẳng vải chenille mềm mại Japandi', 'NEST-RT-1219', 'tham-trai-san-det-phang-vai-chenille-mem-mai-japandi', 'Thảm dệt phẳng sợi chenille mềm mịn, sắc màu be cát mộc mạc tôn lên nét thanh lịch của không gian Japandi.', 'Thảm trải sàn dệt phẳng làm từ sợi chenille dệt đan xen sợi bông mềm mịn, tạo cảm giác bước chân êm ái và mát mẻ quanh năm. Thiết kế bề mặt vân sọc chìm tinh tế hòa quyện nhịp nhàng với nội thất gỗ tự nhiên của phong cách Japandi và Wabi-Sabi. Sản phẩm thích hợp đặt dưới bàn trà phòng khách, chân giường ngủ hoặc góc đọc sách yên tĩnh. Thảm dễ dàng gấp gọn khi cần cất giữ, có thể hút bụi thường xuyên hoặc giặt khô chuyên dụng để giữ màu sắc luôn tươi sáng như mới.', 1, 12, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Sợi chenille kết hợp cotton"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "140 x 200 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Be cát 140 x 200 cm", "Xám ấm 140 x 200 cm", "Be cát 160 x 230 cm"]}], "totalElements": 1}', 3600, 1),
(1220, NOW(), NOW(), null, null, 'Thảm cói tròn dệt thủ công họa tiết xoắn ốc tự nhiên', 'NEST-RT-1220', 'tham-coi-tron-det-thu-cong-hoa-tiet-xoan-oc-tu-nhien', 'Thảm tròn đan cói và xơ đay thủ công mộc mạc, tạo điểm nhấn ấm áp và gần gũi với thiên nhiên cho tổ ấm.', 'Thảm tròn thủ công được bện tỉ mỉ từ sợi cói và xơ đay tự nhiên đã qua xử lý sấy khô chống ẩm mốc. Từng đường đan xoắn ốc tạo nên bề mặt thô mộc đặc trưng, đem lại cảm giác gần gũi với thiên nhiên cho không gian sống phong cách Japandi mộc mạc. Sản phẩm lý tưởng để đặt lót dưới ghế thư giãn, chậu cây lớn hoặc làm điểm nhấn giữa phòng khách. Lưu ý đặt thảm ở nơi khô ráo thoáng khí, vệ sinh bằng chổi mềm hoặc máy hút bụi, tránh ngâm nước trực tiếp.', 1, 12, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Sợi cói tự nhiên và xơ đay thủ công"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "120 x 120 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Mộc mạc"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Đường kính 100 cm", "Đường kính 120 cm", "Đường kính 150 cm"]}], "totalElements": 1}', 2800, 1),
(1221, NOW(), NOW(), null, null, 'Thảm lau chân cửa ra vào Cotton dập nổi chống trượt', 'NEST-RT-1221', 'tham-lau-chan-cua-ra-vao-cotton-dap-noi-chong-truot', 'Thảm chùi chân cotton dập gân dệt dày dặn, thấm hút tốt kèm lớp đế cao su bám sàn an toàn cho mọi không gian.', 'Thảm lau chân cửa ra vào với kết cấu bề mặt dập nổi họa tiết gân sọc từ sợi cotton dệt đặc, giúp thấm hút nước nhanh và giữ lại bụi bẩn hiệu quả dưới đế giày dép. Mặt đáy phủ lớp cao su TPR chống trượt an toàn, bám chặt trên sàn gạch men và sàn gỗ. Thảm mang thiết kế Bắc Âu trang nhã, thích hợp đặt tại tiền sảnh, cửa ban công hoặc lối vào phòng ngủ. Sản phẩm dễ dàng vệ sinh, giặt được bằng máy giặt ở nhiệt độ thường mà không lo phai màu hay bong tróc đế.', 1, 12, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Sợi cotton dệt nổi, mặt đáy cao su TPR"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "45 x 70 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Nâu đất", "Xám tro", "Xanh rêu"]}], "totalElements": 1}', 680, 1),
(1222, NOW(), NOW(), null, null, 'Thảm chùi chân đá diatomite thấm hút nhanh kháng khuẩn', 'NEST-RT-1222', 'tham-chui-chan-da-diatomite-tham-hut-nhanh-khang-khuan', 'Thảm đá diatomite thiên nhiên hút nước siêu tốc và tự khô ráo trong tích tắc, giữ sàn nhà tắm luôn sạch sẽ.', 'Thảm chùi chân làm từ khoáng đá trầm tích diatomite thiên nhiên kết hợp sợi thực vật, nổi bật với tính năng thấm hút nước tức thì chỉ trong vài giây và tự khô ráo nhanh chóng. Bề mặt nhám mịn kháng khuẩn, chống ẩm mốc và ngăn mùi hôi vượt trội, rất an toàn khi đặt trước cửa phòng tắm hoặc bồn rửa mặt phong cách tối giản. Để làm sạch, bạn chỉ cần xả nước rửa nhẹ hoặc dùng giấy nhám mịn đi kèm chà nhẹ bề mặt rồi lau khô, thảm sẽ phục hồi độ thấm hút như ban đầu.', 1, 12, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Khoáng đá tảo cát diatomite và sợi thực vật"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "39 x 60 x 0.9 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng tắm"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng ngà", "Xám xi măng"]}], "totalElements": 1}', 1900, 1),
(1223, NOW(), NOW(), null, null, 'Rèm cửa vải Cotton canvas dệt mộc chống nắng Bắc Âu', 'NEST-RT-1223', 'rem-cua-vai-cotton-canvas-det-moc-chong-nang-bac-au', 'Rèm cửa vải cotton canvas dệt thô mộc, cản sáng dịu nhẹ và tạo nét thanh lịch cho căn phòng.', 'Rèm cửa được gia công từ sợi cotton canvas dày dặn dệt thô mộc mạc, mang đến khả năng lọc bớt 75% ánh nắng chói gắt mà vẫn giữ cho căn phòng sự thông thoáng tự nhiên. Bề mặt vải mềm rủ nhẹ nhàng, thích hợp lắp đặt tại không gian phòng khách, phòng đọc sách hoặc phòng ngủ mang hơi hướng Scandinavian thanh lịch. Sản phẩm dễ kết hợp với thanh treo gỗ hoặc kim loại mờ. Để giữ độ bền của vải, nên giặt tay hoặc giặt máy chế độ nhẹ bằng túi giặt và phơi trong bóng râm râm mát.', 1, 12, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải cotton canvas dệt thô tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "140 x 260 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng khách, phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["140 x 200 cm", "140 x 260 cm"]}], "totalElements": 1}', 1200, 1),
(1224, NOW(), NOW(), null, null, 'Rèm cuốn cầu vồng Hàn Quốc điều chỉnh ánh sáng tối giản', 'NEST-RT-1224', 'rem-cuon-cau-vong-han-quoc-dieu-chinh-anh-sang-toi-gian', 'Rèm cuốn cầu vồng hai lớp linh hoạt, cản nắng hiệu quả và tạo điểm nhấn gọn gàng hiện đại.', 'Rèm cuốn cầu vồng hiện đại kết hợp đan xen giữa dải vải polyester cản sáng và lưới lọc sáng tinh tế, giúp bạn dễ dàng điều chỉnh cường độ ánh sáng tự nhiên theo nhu cầu. Thiết kế tối giản, vận hành êm ái nhờ trục cuốn hợp kim nhôm cao cấp, cực kỳ lý tưởng cho phòng làm việc hoặc cửa sổ phòng ngủ căn hộ chung cư hiện đại. Chất liệu bề mặt kháng bám bụi và chống ẩm mốc tốt. Khi vệ sinh, chỉ cần dùng khăn mềm ẩm hoặc máy hút bụi đầu chổi quét nhẹ.', 1, 12, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải polyester dệt vân xước, phụ kiện hợp kim nhôm sơn tĩnh điện"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "120 x 180 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Hàn Quốc"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Hiện đại"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng làm việc, phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["100 x 160 cm", "120 x 180 cm", "140 x 200 cm"]}], "totalElements": 1}', 2100, 1),
(1225, NOW(), NOW(), null, null, 'Rèm cuốn nan tre tự nhiên dây kéo phong cách Japandi', 'NEST-RT-1225', 'rem-cuon-nan-tre-tu-nhien-day-keo-phong-cach-japandi', 'Rèm cuốn nan tre mộc mạc thanh lịch, điều tiết ánh sáng dịu mát cho không gian tĩnh tại.', 'Rèm cuốn chế tác từ nan tre cật tự nhiên đã qua xử lý sấy nhiệt chống mối mọt cong vênh, giữ trọn vẹn màu sắc mộc mạc và vân tre thanh mảnh. Sản phẩm tạo hiệu ứng ánh sáng đổ bóng nhẹ nhàng kiểu Nhật Bản, mang đến cảm giác an yên cho phòng khách, phòng thiền hay góc ban công thư giãn. Dây kéo cuộn mượt mà giúp điều chỉnh độ cao linh hoạt. Nên vệ sinh định kỳ bằng chổi lông gà hoặc khăn khô mềm để tránh ẩm tích tụ.', 1, 12, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Nan tre cật tự nhiên, dây dù bện chịu lực"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "100 x 160 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng khách, ban công"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["80 x 160 cm", "100 x 160 cm", "120 x 180 cm"]}], "totalElements": 1}', 1800, 1),
(1226, NOW(), NOW(), null, null, 'Thảm trải sàn phòng khách dệt len họa tiết hình học Bắc Âu', 'NEST-RT-1226', 'tham-trai-san-phong-khach-det-len-hoa-tiet-hinh-hoc-bac-au', 'Thảm trải sàn dệt len êm ái họa tiết hình học bất đối xứng tone be trầm ấm cho phòng khách.', 'Thảm trải sàn dệt từ sợi len tổng hợp dệt kim cao cấp với bề mặt êm ái và mật độ sợi dày dặn, giảm tiếng ồn bước chân hiệu quả. Họa tiết hình học bất đối xứng trên nền tone be trung tính mang đậm phong cách Bắc Âu, hoàn hảo để làm điểm nhấn dưới bàn trà phòng khách hoặc chân giường ngủ. Đế thảm dệt đan sợi đay chắc chắn, bám sàn tốt và không lo xô lệch. Định kỳ làm sạch bằng máy hút bụi và giặt khô khi dính vết bẩn sẫm màu.', 1, 12, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Sợi len tổng hợp Polypropylene, đế sợi đay tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 230 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thổ Nhĩ Kỳ"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng khách, phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["140 x 200 cm", "160 x 230 cm"]}], "totalElements": 1}', 4800, 1),
(1227, NOW(), NOW(), null, null, 'Thảm sàn phòng khách sợi boucle lông cừu êm ái wabi sabi', 'NEST-RT-1227', 'tham-san-phong-khach-soi-boucle-long-cuu-em-ai-wabi-sabi', 'Thảm trải sàn sợi boucle xốp mềm mại màu kem ấm cúng, chuẩn phong cách Wabi Sabi mộc mạc.', 'Sở hữu chất liệu vải sợi xoăn boucle dày dặn mô phỏng bề mặt lông cừu mềm xốp, chiếc thảm đem lại cảm giác nâng niu đôi chân và giữ ấm sàn nhà tuyệt vời vào mùa đông. Tông màu đơn sắc nhã nhặn tôn vinh vẻ đẹp tĩnh lặng chuẩn tinh thần Wabi Sabi, thích hợp bố trí tại phòng khách, góc thư giãn hay phòng ngủ Master. Thảm có lớp lót hạt cao su chống trơn trượt an toàn. Khuyên dùng máy hút bụi cầm tay để vệ sinh bụi bẩn thường ngày.', 1, 12, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Sợi xoăn Boucle Polyester, đế cao su chống trượt TPR"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "160 x 200 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng khách, phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng sữa", "Be nhạt"]}], "totalElements": 1}', 4200, 1),
(1228, NOW(), NOW(), null, null, 'Thảm lau chân sợi chenille dày dặn siêu thấm hút nước', 'NEST-RT-1228', 'tham-lau-chan-soi-chenille-day-dan-sieu-tham-hut-nuoc', 'Thảm lau chân sợi chenille mềm mại, thấm hút tức thì và có đế cao su chống trượt tuyệt đối.', 'Thảm lau chân sử dụng sợi chenille siêu mềm mại với cấu trúc vi sợi dày đặc, cho khả năng thấm hút nước tức thì khi vừa bước ra khỏi phòng tắm hay nhà bếp. Cảm giác bước chân lên thảm cực kỳ êm ái, lớp đế phủ cao su nhiệt dẻo TPR giúp chống trơn trượt tối đa ngay cả trên mặt sàn gạch ướt. Sản phẩm có kích thước gọn nhẹ, màu sắc trang nhã dễ phối hợp. Có thể giặt máy thuận tiện ở nhiệt độ nước dưới 30 độ C và phơi mau khô.', 1, 12, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Sợi Microfiber Chenille, đế cao su TPR chống trượt"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "45 x 70 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng tắm, phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Xám nhạt", "Xanh rêu", "Nâu be"]}], "totalElements": 1}', 550, 1),
(1229, NOW(), NOW(), null, null, 'Thảm chùi chân sợi xơ dừa chống trượt cửa ra vào mộc mạc', 'NEST-RT-1229', 'tham-chui-chan-soi-xo-dua-chong-truot-cua-ra-vao-moc-mac', 'Thảm chùi chân xơ dừa tự nhiên dày dặn gạt sạch bụi bẩn đế giày dép trước khi vào nhà.', 'Được dệt từ sợi xơ dừa tự nhiên có tính chất cứng cáp và đàn hồi cao, thảm giúp giữ lại bùn đất, bụi bẩn bám dưới đế giày dép trước khi bước vào nhà một cách triệt để. Mặt dưới ép lớp cao su non bám dính chắc chắn, chống trượt ngã hiệu quả nơi tiền sảnh, cửa ra vào hay thềm hiên nhà. Phong cách thô mộc tự nhiên mang đến nét chào đón thân thiện cho ngôi nhà. Cách làm sạch cực kỳ đơn giản: chỉ cần giũ mạnh hoặc dùng vòi xịt nước rồi dựng đứng phơi khô ráo.', 1, 12, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Sợi xơ dừa tự nhiên, đế cao su non đúc"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "40 x 60 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Ấn Độ"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Mộc mạc"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Ban công, phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Nâu mộc trơn", "Họa tiết kẻ tối giản"]}], "totalElements": 1}', 1400, 1),
(1230, NOW(), NOW(), null, null, 'Thảm sợi đay tự nhiên dệt tay phối viền phong cách Japandi', 'NEST-RT-1230', 'tham-soi-day-tu-nhien-det-tay-phoi-vien-phong-cach-japandi', 'Thảm sợi đay dệt thủ công đanh chắc, mang hương vị đồng quê mộc mạc và tĩnh lặng vào gian phòng.', 'Thảm dệt thủ công từ sợi đay và cói tự nhiên tuyển chọn, bề mặt đan nong mốt đanh chắc tạo nét đẹp mộc mạc và gần gũi với thiên nhiên theo đúng chuẩn Japandi. Sợi cói tỏa hương cỏ khô thanh nhẹ, rất thích hợp lót dưới bộ sofa gỗ, bàn ăn mộc hoặc góc đọc sách yên tĩnh. Thảm cách nhiệt tốt, mát mẻ vào mùa hè và ấm áp vào mùa đông. Hạn chế sử dụng ở nơi ẩm ướt, bảo quản bằng cách hút bụi nhẹ nhàng và phơi nắng sớm định kỳ.', 1, 12, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Sợi đay tự nhiên kết hợp sợi cói tuyển chọn"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "120 x 180 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng khách, phòng ăn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["120 x 180 cm", "150 x 210 cm"]}], "totalElements": 1}', 3600, 1),
(1231, NOW(), NOW(), null, null, 'Rèm xếp lớp roman vải bố cản nắng tối giản Bắc Âu', 'NEST-RT-1231', 'rem-xep-lop-roman-vai-bo-can-nang-toi-gian-bac-au', 'Rèm roman xếp lớp bằng vải bố dệt dày dặn, cản sáng 80% mang lại vẻ gọn gàng, thanh lịch cho khung cửa.', 'Rèm roman được may từ chất liệu vải bố polyester pha cotton cao cấp dệt sợi đan khít, tạo độ rủ phẳng phiu và khả năng cản sáng hiệu quả. Hệ phụ kiện dây kéo trơn tru giúp nâng hạ rèm theo từng nếp gấp ngay ngắn, tối ưu ánh sáng linh hoạt cho căn phòng. Sản phẩm mang gam màu trung tính nhã nhặn, hoàn hảo cho phòng ngủ, phòng làm việc hoặc góc đọc sách phong cách Bắc Âu. Vệ sinh đơn giản bằng máy hút bụi đầu chổi mềm hoặc tháo vải giặt khô định kỳ.', 1, 12, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải bố sợi polyester pha cotton, thanh cuộn hợp kim nhôm"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "120 x 160 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng ngủ"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["100 x 160 cm", "120 x 160 cm", "140 x 180 cm"]}], "totalElements": 1}', 1800, 1),
(1232, NOW(), NOW(), null, null, 'Thảm chiếu cói tatami gấp gọn viền vải mộc phong cách Japandi', 'NEST-RT-1232', 'tham-chieu-coi-tatami-gap-gon-vien-vai-moc-phong-cach-japandi', 'Thảm chiếu cói tự nhiên xử lý sấy khô kỹ lưỡng, viền vải thô mộc mang hương cỏ thoang thoảng chuẩn phong vị Nhật Bản.', 'Chiếu cói tatami sử dụng sợi cói biển tự nhiên tuyển chọn, dệt thủ công với mật độ dày và bề mặt nhẵn mịn, đem lại cảm giác mát mẻ vào mùa hè và ấm áp khi trời se lạnh. Ruột lót đệm xốp êm ái hỗ trợ nâng đỡ nhẹ nhàng, viền bo vải thô mộc chắc chắn cùng thiết kế nếp gấp ba khúc tiện lợi cất gọn. Thảm thích hợp trải phòng trà, góc thiền hoặc sàn phòng khách phong cách Japandi tĩnh tại. Chỉ cần lau bằng khăn ẩm vắt ráo và phơi nơi thoáng gió.', 1, 12, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Sợi cói tự nhiên dệt tay, ruột xốp EPE đàn hồi, viền vải cotton canvas"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "180 x 200 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng khách"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["90 x 200 cm", "180 x 200 cm"]}], "totalElements": 1}', 3600, 1),
(1233, NOW(), NOW(), null, null, 'Khăn tắm Cotton hữu cơ dệt sợi waffle thấm hút nhanh', 'NEST-PT-1233', 'khan-tam-cotton-huu-co-det-soi-waffle-tham-hut-nhanh', 'Khăn tắm cotton dệt tổ ong mềm mại, thấm hút vượt trội và nhanh khô ráo.', 'Sản phẩm được dệt hoàn toàn từ sợi cotton hữu cơ tự nhiên theo cấu trúc tổ ong waffle thoáng khí. Khăn mang lại cảm giác xốp nhẹ, êm ái trên làn da nhạy cảm và có khả năng thấm hút nước tức thì, không gây ẩm mốc sau khi sử dụng. Thiết kế tối giản tinh tế phù hợp cho các không gian phòng tắm phong cách Japandi hoặc hiện đại. Khăn dễ dàng giặt sạch bằng tay hoặc máy ở chế độ nhẹ, nên phơi nơi thoáng gió tránh ánh nắng gắt.', 1, 13, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Cotton hữu cơ 100%"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "70 x 140 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng tắm"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Be nhạt", "Xám tro"]}], "totalElements": 1}', 380, 1),
(1234, NOW(), NOW(), null, null, 'Khăn tắm sợi bông chải kỹ mềm mịn tối giản Bắc Âu', 'NEST-PT-1234', 'khan-tam-soi-bong-chai-ky-mem-min-toi-gian-bac-au', 'Khăn tắm sợi bông chải kỹ dệt mật độ cao dày dặn, siêu mềm mại và bền bỉ.', 'Chiếc khăn tắm cao cấp sử dụng sợi bông chải kỹ dài sợi giúp bề mặt vải mịn màng, hạn chế tối đa tình trạng đổ lông hay xơ cứng sau nhiều lần giặt. Cảm giác bao bọc cơ thể ấm áp, mềm xốp và thấm hút nước cực tốt sau mỗi lần tắm gội thư giãn. Tông màu đơn sắc trang nhã tôn vinh vẻ đẹp tối giản Scandinavian cho phòng tắm gia đình. Bạn nên giặt riêng trong vài lần đầu, không dùng chất tẩy mạnh và sấy ở nhiệt độ thấp để duy trì độ êm ái.', 1, 13, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Cotton chải kỹ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "70 x 140 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng tắm"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng kem", "Xanh rêu nhạt"]}], "totalElements": 1}', 500, 1),
(1235, NOW(), NOW(), null, null, 'Kệ đựng đồ nhà tắm khung thép không gỉ dán tường tiện lợi', 'NEST-PT-1235', 'ke-dung-do-nha-tam-khung-thep-khong-gi-dan-tuong-tien-loi', 'Kệ dán tường không cần khoan đục chịu lực tốt, thoát nước nhanh gọn gàng.', 'Mẫu kệ treo tường tiện lợi được làm từ khung thép không gỉ phủ sơn tĩnh điện nhám cao cấp, chống han gỉ tối ưu trong môi trường ẩm ướt của nhà tắm. Đáy kệ thiết kế khe hở rãnh song song giúp chai lọ dầu gội, sữa tắm luôn ráo nước, hạn chế đọng cặn bẩn. Kiểu dáng hình chữ nhật thanh thoát phù hợp với phòng tắm căn hộ hiện đại hoặc phong cách tối giản. Sản phẩm đi kèm miếng dán keo siêu dính chịu lực lên đến 8 kg, lau chùi dễ dàng bằng khăn ẩm mềm.', 1, 13, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Thép không gỉ sơn tĩnh điện"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "30 x 12 x 8 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Hiện đại"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng tắm"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Đen mờ", "Trắng sữa"]}], "totalElements": 1}', 420, 1),
(1236, NOW(), NOW(), null, null, 'Kệ góc phòng tắm gỗ tràm chịu nước 3 tầng phong cách Japandi', 'NEST-PT-1236', 'ke-goc-phong-tam-go-tram-chiu-nuoc-3-tang-phong-cach-japandi', 'Kệ góc 3 tầng gỗ tràm tự nhiên bo góc ấm cúng, tối ưu không gian nhỏ hẹp.', 'Kệ được chế tác từ gỗ tràm tự nhiên nguyên khối đã qua xử lý sấy kỹ và phủ lớp sơn lau chống nước mờ, hạn chế cong vênh, mốc ố. Thiết kế góc tam giác thông minh giúp tận dụng tối đa góc chết trong phòng tắm để sắp xếp khăn, giỏ đồ hay tinh dầu thơm. Cảm giác mộc mạc và màu gỗ ấm áp mang đậm tinh thần thư thái của phong cách Japandi. Cần giữ kệ ở vị trí khô ráo tương đối, lau chùi định kỳ bằng khăn mềm để giữ vân gỗ bền đẹp theo năm tháng.', 1, 13, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tràm tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "35 x 35 x 85 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng tắm"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu tự nhiên", "Màu nâu óc chó"]}], "totalElements": 1}', 3600, 1),
(1237, NOW(), NOW(), null, null, 'Bộ phụ kiện nhà tắm gốm sứ men mờ phong cách wabi sabi', 'NEST-PT-1237', 'bo-phu-kien-nha-tam-gom-su-men-mo-phong-cach-wabi-sabi', 'Bộ 3 món gốm sứ mộc mạc gồm bình xịt, cốc súc miệng và khay đựng xà bông.', 'Bộ phụ kiện gồm bình chiết xà phòng, cốc súc miệng và khay đựng bánh xà bông được hoàn thiện từ chất liệu gốm nung nhiệt độ cao với lớp men mờ thủ công. Bề mặt nhám nhẹ tạo cảm giác cầm nắm chắc tay, mang nét thô mộc đặc trưng của phong cách Wabi Sabi và Japandi. Sản phẩm giúp mặt bàn lavabo luôn ngăn nắp, đồng điệu và nâng tầm trải nghiệm thư giãn như tại spa. Vệ sinh đơn giản bằng nước ấm và xà phòng loãng, tránh va đập mạnh làm mẻ góc gốm sứ.', 1, 13, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gốm sứ tráng men mờ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "22 x 10 x 18 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng tắm"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu kem cát", "Màu xám đá"]}], "totalElements": 1}', 950, 1),
(1238, NOW(), NOW(), null, null, 'Bộ đựng bàn chải và nước rửa tay bằng nhựa nhám tối giản', 'NEST-PT-1238', 'bo-dung-ban-chai-va-nuoc-rua-tay-bang-nhua-nham-toi-gian', 'Bộ phụ kiện nhựa ABS hoàn thiện mờ chống bám vân tay, thanh lịch tiện dụng.', 'Thiết kế sản phẩm tập trung vào công năng thuần túy với chất liệu nhựa ABS nguyên sinh cao cấp chịu lực, bề mặt nhám mờ chống bám vân tay và dễ lau chùi. Bộ sản phẩm gồm một bình nhấn tạo bọt tiết kiệm xà phòng và một ống cắm bàn chải có vách ngăn thông minh. Tông màu đơn sắc mang phong cách Bắc Âu thanh lịch, hài hòa với mọi kiểu chậu rửa mặt hiện đại. Nên tháo rời các chi tiết để rửa sạch cặn xà phòng định kỳ hàng tuần, giữ phụ kiện luôn sáng đẹp như mới.', 1, 13, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Nhựa ABS cao cấp"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "16 x 8 x 17 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng tắm"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng ngà", "Xám than"]}], "totalElements": 1}', 400, 1),
(1239, NOW(), NOW(), null, null, 'Gương phòng tắm tròn viền hợp kim nhôm kèm kệ đựng nhỏ', 'NEST-PT-1239', 'guong-phong-tam-tron-vien-hop-kim-nhom-kem-ke-dung-nho', 'Gương tròn tráng bạc sắc nét viền kim loại có tích hợp giá để đồ tinh tế.', 'Chiếc gương soi hình tròn sử dụng phôi gương tráng bạc nhiều lớp cho hình ảnh phản chiếu chân thực, sáng rõ và chống ố mốc trong môi trường có độ ẩm cao. Phần viền ngoài làm bằng hợp kim nhôm sơn tĩnh điện chắc chắn, tích hợp thêm một thanh kệ ngang nhỏ gọn phía dưới để đặt chai nước hoa hoặc mỹ phẩm thường dùng. Kiểu dáng tròn trịa mềm mại giúp cân bằng các đường thẳng trong phòng tắm tối giản. Lau mặt kính bằng khăn sợi microfiber ẩm, tránh dung dịch tẩy rửa có tính axit cao.', 1, 13, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Phôi gương tráng bạc, viền hợp kim nhôm"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "50 x 10 x 50 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng tắm"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Đường kính 50 cm Đen", "Đường kính 60 cm Đen"]}], "totalElements": 1}', 3200, 1),
(1240, NOW(), NOW(), null, null, 'Thảm cao su chống trượt nhà tắm thoát nước nhanh kiểu nhật', 'NEST-PT-1240', 'tham-cao-su-chong-truot-nha-tam-thoat-nuoc-nhanh-kieu-nhat', 'Thảm cao su tự nhiên vân nổi êm chân, giác hút bám sàn chống trượt hiệu quả.', 'Tấm thảm lót sàn được sản xuất từ chất liệu cao su nhiệt dẻo thân thiện với môi trường, không phát sinh mùi khó chịu khi tiếp xúc với nước nóng. Bề mặt thảm sở hữu các rãnh sọc thoát nước linh hoạt kết hợp giác hút dày đặc ở mặt dưới, giúp bám chặt vào sàn gạch men ướt, ngăn ngừa trơn trượt tối đa cho trẻ nhỏ và người lớn tuổi. Thiết kế gọn gàng mang cảm hứng tối giản Nhật Bản. Sau khi tắm chỉ cần treo ngược thảm lên tường để ráo khô tự nhiên hoặc xịt rửa sạch bằng vòi sen.', 1, 13, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Cao su nhiệt dẻo TPR"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "70 x 40 x 0.5 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng tắm"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Xám nhạt", "Trắng sữa"]}], "totalElements": 1}', 650, 1),
(1241, NOW(), NOW(), null, null, 'Khăn tắm Cotton ai cập dày dặn dệt gân nổi thấm hút tốt', 'NEST-PT-1241', 'khan-tam-cotton-ai-cap-day-dan-det-gan-noi-tham-hut-tot', 'Khăn tắm cotton Ai Cập sợi dài siêu thấm hút, bề mặt dệt gân gợn sóng êm ái cho làn da nhạy cảm.', 'Sản phẩm được dệt từ 100% sợi bông cotton Ai Cập chải kỹ mật độ cao, mang lại cảm giác bông xốp, thấm hút nước tức thì và nhanh khô. Cấu trúc gân nổi tinh tế tạo độ ma sát nhẹ nhàng, giúp massage da sau mỗi lần tắm. Tông màu nhã nhặn phù hợp cho không gian phòng tắm phong cách Bắc Âu hoặc Japandi. Nên giặt bằng nước lạnh trong lần đầu, tránh sấy nhiệt độ quá cao và hạn chế nước xả vải để duy trì độ thấm hút tự nhiên bền lâu.', 1, 13, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "100% Cotton Ai Cập"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "70 x 140 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng tắm"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng sữa - 70 x 140 cm", "Xám nhạt - 70 x 140 cm", "Xanh sage - 70 x 140 cm"]}], "totalElements": 1}', 550, 1),
(1242, NOW(), NOW(), null, null, 'Kệ treo khăn tắm gỗ Teak tự nhiên chống ẩm mốc Japandi', 'NEST-PT-1242', 'ke-treo-khan-tam-go-teak-tu-nhien-chong-am-moc-japandi', 'Kệ vắt khăn gỗ teak tự nhiên phủ dầu thực vật chịu nước tốt, thiết kế nan ngang gọn gàng cho phòng tắm.', 'Kệ treo khăn tắm được gia công hoàn toàn từ gỗ teak tự nhiên già tuổi, nổi tiếng với khả năng kháng nước và chống mối mọt vượt trội trong môi trường ẩm ướt. Thiết kế nan thoáng khí kết hợp mặt kệ phía trên giúp bạn vừa gấp khăn sạch vừa hong ráo khăn ướt ngăn nắp. Kiểu dáng thanh thoát mang hơi thở Japandi mộc mạc, làm ấm không gian tắm hiện đại. Lau sạch bằng khăn ẩm mềm định kỳ và lau khô bề mặt đọng nước để gỗ luôn bền đẹp.', 1, 13, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ teak tự nhiên lau dầu bảo vệ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "60 x 22 x 18 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Indonesia"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng tắm"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Gỗ tự nhiên - Dài 60 cm", "Gỗ tự nhiên - Dài 80 cm"]}], "totalElements": 1}', 2100, 1),
(1243, NOW(), NOW(), null, null, 'Bộ phụ kiện nhà tắm đá Terrazzo tự nhiên bo viền tối giản', 'NEST-PT-1243', 'bo-phu-kien-nha-tam-da-terrazzo-tu-nhien-bo-vien-toi-gian', 'Bộ phụ kiện 4 món từ đá terrazzo bề mặt mài nhẵn mịn, mang vẻ đẹp hiện đại và sang trọng cho bàn lavabo.', 'Bộ phụ kiện gồm bình chiết xà phòng vòi inox, cốc súc miệng, khay đựng xà bông bánh và ống cắm bàn chải đánh răng. Chất liệu đá mài terrazzo đúc đặc chắc chắn, cầm đầm tay và phủ lớp chống thấm nước giúp hạn chế ố vàng theo thời gian. Sự hòa trộn giữa hạt đá khoáng tự nhiên tạo nên hoa văn ngẫu hứng, tô điểm cho mặt bàn lavabo thêm chỉn chu và phong cách. Dễ dàng vệ sinh bằng nước ấm pha xà phòng loãng, tránh cọ rửa bằng búi kim loại.', 1, 13, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Đá mài terrazzo tự nhiên, vòi nhấn inox 304"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "25 x 12 x 18 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng tắm"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Terrazzo trắng kem", "Terrazzo xám xi măng"]}], "totalElements": 1}', 2800, 1),
(1244, NOW(), NOW(), null, null, 'Gương phòng tắm bầu dục bo góc khung gỗ tần bì chống ẩm', 'NEST-PT-1244', 'guong-phong-tam-bau-duc-bo-goc-khung-go-tan-bi-chong-am', 'Gương soi hình bầu dục khung gỗ tần bì uốn cong tinh xảo, phôi gương tráng bạc sắc nét chống ố mốc.', 'Sản phẩm sở hữu đường cong bầu dục mềm mại với khung gỗ tần bì nguyên khối uốn nhiệt và xử lý sơn lót chống ẩm chuyên dụng cho nhà tắm. Mặt gương phôi Bỉ tráng bạc 8 lớp cho hình ảnh phản chiếu chân thực, sáng rõ và chống ẩm mốc mép viền tối ưu. Thiết kế thanh lịch tạo cảm giác cởi mở, ấm cúng và mở rộng chiều sâu thị giác cho không gian tắm phong cách Bắc Âu. Lau gương định kỳ bằng khăn sợi microfiber mềm cùng nước lau kính chuyên dụng.', 1, 13, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Phôi gương tráng bạc, khung gỗ tần bì tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "50 x 80 x 3.5 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng tắm"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Gỗ tự nhiên - 50 x 80 cm", "Gỗ màu óc chó - 50 x 80 cm"]}], "totalElements": 1}', 4600, 1),
(1245, NOW(), NOW(), null, null, 'Thảm gỗ tràm chống trượt lát sàn phòng tắm thoát nước tốt', 'NEST-PT-1245', 'tham-go-tram-chong-truot-lat-san-phong-tam-thoat-nuoc-tot', 'Thảm lát sàn nhà tắm nan gỗ tràm sấy nhiệt chịu nước, đế cao su chống trượt an toàn tuyệt đối.', 'Thảm sàn được chế tác từ các nan gỗ tràm rừng trồng qua quy trình sấy nhiệt chống cong vênh và kháng ẩm hiệu quả. Khoảng cách giữa các nan gỗ hỗ trợ róc nước nhanh chóng, giữ bề mặt luôn khô ráo và không gây đọng vũng khó chịu. Mặt dưới lót đệm cao su bám sàn cực tốt, chống trơn trượt hiệu quả cho cả người già và trẻ nhỏ. Thích hợp đặt ngay trước bồn tắm đứng hoặc cửa ra vào phòng tắm. Thường xuyên dựng đứng thảm phơi khô nơi thoáng gió để bảo dưỡng.', 1, 13, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tràm sấy nhiệt, đế đệm cao su EPDM"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "60 x 40 x 2.8 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng tắm"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Gỗ tràm vàng nhạt - 60 x 40 cm", "Gỗ tràm nâu mộc - 60 x 40 cm"]}], "totalElements": 1}', 2300, 1),
(1246, NOW(), NOW(), null, null, 'Gương phòng tắm dáng vòm viền kim loại sơn tĩnh điện đen', 'NEST-PT-1246', 'guong-phong-tam-dang-vom-vien-kim-loai-son-tinh-dien-den', 'Gương vòm viền hợp kim thanh mảnh sơn tĩnh điện, tạo điểm nhấn kiến trúc sang trọng cho khu vực lavabo.', 'Gương vòm treo tường mang đường nét kiến trúc tinh giản với phần viền kim loại uốn cong liền mạch, phủ sơn tĩnh điện chống rỉ sét trong môi trường ẩm. Kính gương cao cấp dày dặn cho độ phản chiếu sắc nét, không gợn sóng và được dán lớp màng an toàn chống vỡ vụn phía sau. Thiết kế dáng vòm thanh thoát giúp trần nhà trông cao ráo hơn và nâng tầm thẩm mỹ phòng tắm tối giản. Vệ sinh nhẹ nhàng bằng khăn mềm sạch và nước lau kính, không dùng hóa chất tẩy rửa mạnh.', 1, 13, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Khung hợp kim nhôm sơn tĩnh điện, gương Bỉ tráng bạc"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "50 x 75 x 3 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Hiện đại"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng tắm"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Viền đen mờ - 50 x 75 cm", "Viền vàng đồng nhạt - 50 x 75 cm"]}], "totalElements": 1}', 4200, 1),
(1247, NOW(), NOW(), null, null, 'Ghế xếp gỗ Teak ngoài trời chống nước gấp gọn', 'NEST-NT-1247', 'ghe-xep-go-teak-ngoai-troi-chong-nuoc-gap-gon', 'Ghế xếp ban công gỗ teak tự nhiên chống thấm nước, dễ dàng gấp gọn tiết kiệm không gian.', 'Ghế xếp ban công được gia công hoàn toàn từ gỗ teak tự nhiên già tuổi, nổi tiếng với khả năng chống thấm nước và kháng mối mọt vượt trội. Thiết kế nan gỗ thoáng khí mang lại cảm giác ngồi thư giãn, dễ chịu khi đọc sách hay thưởng trà ngoài trời. Ghế có cơ chế gấp gọn linh hoạt, tối ưu diện tích cho ban công nhỏ, sân thượng hoặc hiên nhà. Để sản phẩm luôn bền đẹp, bạn nên lau sạch bằng khăn ẩm mềm và định kỳ thoa dầu bảo quản gỗ teak mỗi năm một lần, tránh ngâm nước đọng kéo dài.', 1, 14, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ teak tự nhiên, phụ kiện inox 304"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "45 x 52 x 85 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Indonesia"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "ban công"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu gỗ tự nhiên", "Màu nâu hạt dẻ"]}], "totalElements": 1}', 4500, 2),
(1248, NOW(), NOW(), null, null, 'Bộ bàn ghế ban công gấp gọn gỗ tràm chịu nắng mưa', 'NEST-NT-1248', 'bo-ban-ghe-ban-cong-gap-gon-go-tram-chiu-nang-mua', 'Bộ bàn ghế gỗ tràm gấp gọn tinh tế, chống thấm dầu chuyên dụng cho ban công chung cư.', 'Bộ bàn ghế ngoài trời chế tác từ gỗ tràm bông vàng xử lý sấy dầu chuyên dụng, chịu nhiệt và chống cong vênh tốt trước thời tiết nhiệt đới. Mặt bàn và lưng ghế xẻ rãnh nan thoáng gió, tạo tư thế ngồi êm ái, thư thái vào mỗi buổi sớm mai. Thiết kế nhỏ gọn có thể gập phẳng khi không dùng, rất phù hợp cho ban công chung cư, logia hoặc góc sân vườn xinh xắn. Vệ sinh đơn giản với khăn mềm vắt khô nước, đồng thời nên bảo quản dưới mái che hoặc che bạt khi mưa bão kéo dài để giữ màu gỗ lâu phai.', 1, 14, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tràm tự nhiên lau dầu"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "60 x 60 x 74 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "ban công"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Bộ 1 bàn 2 ghế", "Bàn đơn 60x60cm"]}], "totalElements": 1}', 11500, 2),
(1249, NOW(), NOW(), null, null, 'Bàn trà ban công tròn khung sắt sơn tĩnh điện mặt đá', 'NEST-NT-1249', 'ban-tra-ban-cong-tron-khung-sat-son-tinh-dien-mat-da', 'Bàn trà tròn mặt đá nung kết khung sắt sơn tĩnh điện bền bỉ, phong cách Bắc Âu hiện đại.', 'Mẫu bàn trà ngoài trời ghi điểm nhờ khung kim loại phủ sơn tĩnh điện chống rỉ sét kết hợp mặt đá nung kết chịu lực và chống trầy xước. Thiết kế đường cong thanh thoát phong cách Bắc Âu mang đến nét đẹp tinh tế, hiện đại cho góc ban công nhỏ. Bàn có độ đầm chắc chắn, không bị rung lắc khi đặt tách trà hay chậu cây nhỏ. Sản phẩm lý tưởng cho ban công căn hộ, quán cà phê hoặc sân vườn mở. Chỉ cần lau nhẹ bằng khăn ướt sạch sẽ sáng bóng mà không tốn công sức bảo dưỡng định kỳ.', 1, 14, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Khung sắt sơn tĩnh điện, mặt đá nung kết"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "50 x 50 x 55 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Hiện đại"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "ban công"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Mặt đá trắng kem", "Mặt đá xám vân mây"]}], "totalElements": 1}', 6800, 2),
(1250, NOW(), NOW(), null, null, 'Chậu treo ban công gốm đất nung kèm dây dệt macrame', 'NEST-NT-1250', 'chau-treo-ban-cong-gom-dat-nung-kem-day-det-macrame', 'Chậu treo gốm đất nung mộc mạc kèm dây thừng macrame dệt thủ công tạo mảng xanh thư thái.', 'Chậu cây treo kết hợp hoàn hảo giữa gốm đất nung xốp thoáng khí và dây thừng cotton macrame dệt tay tỉ mỉ, mang hơi thở mộc mạc Wabi-Sabi vào ban công. Chất gốm nung tự nhiên hỗ trợ rễ cây trao đổi oxy và thoát nước tối ưu, giúp các loại cây dây leo phát triển xanh tốt. Thiết kế treo lơ lửng giúp tiết kiệm tối đa diện tích sàn cho ban công hẹp hoặc cửa sổ nhiều nắng. Bạn nên lau dây treo bằng khăn ẩm nhẹ nhàng và tránh tưới nước tràn lênh láng để giữ dây macrame luôn sạch đẹp tinh tươm.', 1, 14, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gốm đất nung, dây thừng sợi cotton"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "18 x 18 x 16 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "ban công"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Đường kính 16cm", "Đường kính 20cm"]}], "totalElements": 1}', 1200, 2),
(1251, NOW(), NOW(), null, null, 'Máng chậu treo lan can ban công sắt sơn tĩnh điện', 'NEST-NT-1251', 'mang-chau-treo-lan-can-ban-cong-sat-son-tinh-dien', 'Máng sắt treo lan can ban công chịu tải tốt, phủ sơn tĩnh điện chống rỉ sét ngoài trời.', 'Máng treo lan can sản xuất từ thép cuộn cán nguội phủ sơn tĩnh điện nhám mịn, chống ăn mòn và kháng tia UV hiệu quả khi đặt ngoài trời. Kết cấu móc treo chữ U chắc chắn, dễ dàng gài vào nhiều loại thành lan can ban công mà không cần khoan đục tường. Sản phẩm giúp bạn thỏa sức trồng hoa, thảo mộc hay rau thơm, biến góc ban công nhỏ thành khu vườn xanh ngát. Bạn chỉ cần xịt rửa sạch bụi đất bằng vòi nước và lau khô bằng khăn mềm, định kỳ kiểm tra móc treo để đảm bảo an toàn.', 1, 14, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Thép sơn tĩnh điện chống gỉ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "60 x 20 x 18 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "ban công"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Chiều dài 50cm", "Chiều dài 70cm"]}], "totalElements": 1}', 1900, 2),
(1252, NOW(), NOW(), null, null, 'Đèn năng lượng mặt trời cắm cỏ sân vườn chống nước', 'NEST-NT-1252', 'den-nang-luong-mat-troi-cam-co-san-vuon-chong-nuoc', 'Đèn cắm sân vườn cảm biến ánh sáng tự động, tiêu chuẩn chống nước IP65 phong cách tối giản.', 'Đèn cắm đất ngoài trời sở hữu vỏ nhựa ABS kết hợp chao thủy tinh mờ cao cấp, tích hợp chuẩn kháng nước IP65 bền bỉ qua mọi mùa mưa nắng. Tấm pin quang điện chuyển hóa ánh sáng hiệu suất cao, tự động thắp sáng ánh đèn vàng ấm áp khi hoàng hôn buông xuống, tạo khung cảnh lung linh thư thái. Đèn phù hợp cắm lối đi sân vườn, tiểu cảnh hoặc bồn cây ban công chung cư. Cách bảo quản vô cùng đơn giản, bạn chỉ cần lau sạch mặt pin năng lượng bằng khăn khô định kỳ để duy trì khả năng hấp thụ ánh sáng tốt nhất.', 1, 14, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Nhựa ABS, thủy tinh hữu cơ, pin lithium"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "12 x 12 x 42 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "ban công"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Ánh sáng vàng 3000K", "Ánh sáng trung tính 4000K"]}], "totalElements": 1}', 450, 2),
(1253, NOW(), NOW(), null, null, 'Đèn lồng treo ban công năng lượng mặt trời chống nước', 'NEST-NT-1253', 'den-long-treo-ban-cong-nang-luong-mat-troi-chong-nuoc', 'Đèn lồng treo phong cách Japandi chống thấm nước, sạc năng lượng mặt trời tự động sáng.', 'Đèn lồng treo lấy cảm hứng từ phong cách Japandi tối giản với khung kim loại sơn tĩnh điện và chao đèn vải dù chống thấm nước thời tiết. Nguồn sáng LED vàng ấm áp hoạt động hoàn toàn bằng năng lượng mặt trời, không cần dây điện rườm rà, an toàn tuyệt đối khi lắp đặt ngoài trời. Sản phẩm tạo điểm nhấn lãng mạn cho mái hiên, giàn hoa ban công hoặc khu vực tiệc nướng sân thượng. Bạn nên vệ sinh bề mặt tấm pin năng lượng định kỳ bằng vải mềm và treo ở nơi đón nắng trực tiếp để sạc pin hiệu quả nhất.', 1, 14, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải dù chống nước, khung thép, chip LED"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "25 x 25 x 30 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "ban công"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu trắng kem", "Màu be tự nhiên"]}], "totalElements": 1}', 620, 2),
(1254, NOW(), NOW(), null, null, 'Võng xếp treo ban công vải canvas dệt kèm thanh gỗ', 'NEST-NT-1254', 'vong-xep-treo-ban-cong-vai-canvas-det-kem-thanh-go', 'Võng treo ban công vải canvas dệt dày dặn kèm thanh giằng gỗ sồi êm ái phong cách Bắc Âu.', 'Chiếc võng treo thư giãn làm từ vải bố canvas dệt dày dặn, thấm hút mồ hôi êm ái kết hợp thanh giằng gỗ sồi tự nhiên giữ form võng rộng rãi. Cảm giác nằm đu đưa bồng bềnh giúp xua tan căng thẳng sau ngày dài làm việc, rất thích hợp treo ở ban công rộng, sân thượng hoặc dưới bóng mát sân vườn. Võng có kèm móc treo kim loại chịu lực cao, đảm bảo độ an toàn vượt trội khi sử dụng. Dễ dàng tháo rời phần vải để giặt sạch bằng tay hoặc máy ở chế độ nhẹ, nên cất vào nhà khi trời mưa bão.', 1, 14, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải canvas cotton, thanh gỗ sồi tự nhiên, dây thừng"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "200 x 100 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "ban công"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng ngà viền tua rua", "Ghi xám trơn tối giản"]}], "totalElements": 1}', 2100, 2),
(1255, NOW(), NOW(), null, null, 'Ghế xếp thư giãn gỗ Teak tự nhiên lưng tựa dây dù nan đan', 'NEST-NT-1255', 'ghe-xep-thu-gian-go-teak-tu-nhien-lung-tua-day-du-nan-dan', 'Ghế xếp thư giãn chất liệu gỗ teak tự nhiên đan dây dù êm ái, gấp gọn linh hoạt cho ban công hay sân thượng.', 'Sản phẩm được chế tác từ gỗ teak tự nhiên già tuổi tuyển chọn, kết hợp nan tựa lưng đan dây dù polyeste chịu lực co giãn nhẹ nhàng. Ghế mang lại tư thế ngả lưng thư giãn thoải mái, ôm sát đường cong cơ thể khi đọc sách ngắm cảnh. Thiết kế gấp gọn tiện lợi, đặc biệt thích hợp cho ban công chung cư, sân vườn hoặc hiên nhà phong cách Japandi mộc mạc. Để ghế bền đẹp lâu dài qua nắng mưa, nên lau sạch bụi bẩn bằng khăn ẩm mềm và định kỳ quét dầu dưỡng gỗ chuyên dụng mỗi 6 tháng một lần.', 1, 14, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ teak tự nhiên, dây dù bọc lõi chịu lực"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "65 x 82 x 78 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Indonesia"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "ban công, sân vườn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Dây đen khung gỗ tự nhiên", "Dây be kem khung gỗ tự nhiên"]}], "totalElements": 1}', 7500, 2),
(1256, NOW(), NOW(), null, null, 'Bộ bàn tròn 2 ghế ban công kim loại sơn nhám chống rỉ sét', 'NEST-NT-1256', 'bo-ban-tron-2-ghe-ban-cong-kim-loai-son-nham-chong-ri-set', 'Bộ bàn tròn 2 ghế ban công khung thép sơn nhám tĩnh điện nhỏ gọn, kháng nước vượt trội cho góc thư giãn tối giản.', 'Bộ bàn ghế làm từ thép mạ kẽm phủ lớp sơn tĩnh điện nhám mịn cao cấp, giúp chống gỉ sét và chịu đựng thời tiết khắc nghiệt ngoài trời. Mặt bàn tròn kết hợp hai ghế tựa uốn cong thanh thoát, mang lại cảm giác ngồi chắc chắn và thông thoáng gió. Kích thước gọn gàng lý tưởng cho ban công chung cư diện tích nhỏ, góc sân thượng hoặc sân đón nắng phong cách Scandinavian. Trong quá trình sử dụng, chỉ cần dùng khăn ướt lau sạch vết nước đọng hoặc bụi bẩn ngoài trời nhanh chóng.', 1, 14, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Thép mạ kẽm sơn tĩnh điện nhám"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "Bàn 60 x 60 x 72 cm, Ghế 42 x 45 x 80 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "ban công, sân thượng"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Xám than", "Trắng be", "Xanh ô liu"]}], "totalElements": 1}', 12500, 2),
(1257, NOW(), NOW(), null, null, 'Chậu cây treo ban công nhựa tự dưỡng dây treo thép không gỉ', 'NEST-NT-1257', 'chau-cay-treo-ban-cong-nhua-tu-duong-day-treo-thep-khong-gi', 'Chậu cây treo ban công thông minh tích hợp khoang trữ nước tự dưỡng cùng dây treo thép bọc nhựa an toàn, gọn ghẽ.', 'Chậu cây được đúc từ nhựa PP nguyên sinh dày dặn chống tia UV giòn gãy, kết hợp khay trữ nước ngầm thông minh giúp rễ cây tự hút ẩm mà không lo úng. Dây treo làm bằng cáp thép không gỉ bọc nhựa chắc chắn, dễ dàng điều chỉnh độ cao để đón ánh sáng tự nhiên lý tưởng. Sản phẩm là giải pháp xanh hoàn hảo cho lan can ban công hẹp, hiên nhà hay giàn leo phong cách tối giản. Để giữ chậu luôn sạch đẹp, bạn nên tháo nút xả đáy vệ sinh cặn nước định kỳ hàng tháng và lau bóng bề mặt ngoài.', 1, 14, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Nhựa PP nguyên sinh chống UV, dây cáp thép không gỉ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "Đường kính 25 cm, Cao 16 cm, Dây dài 50 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "ban công, sân vườn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Trắng ngà - Size Nhỏ 20cm", "Trắng ngà - Size Vừa 25cm", "Xám xi măng - Size Vừa 25cm"]}], "totalElements": 1}', 650, 2),
(1258, NOW(), NOW(), null, null, 'Đèn treo tường ban công năng lượng mặt trời cảm biến ánh sáng', 'NEST-NT-1258', 'den-treo-tuong-ban-cong-nang-luong-mat-troi-cam-bien-anh-sang', 'Đèn treo tường ban công năng lượng mặt trời cảm biến tự động, ánh sáng vàng ấm chống nước chuẩn IP65 ngoài trời.', 'Đèn sử dụng tấm pin quang năng đơn tinh thể hấp thụ ánh sáng hiệu quả, tích hợp bóng LED ánh sáng vàng ấm dịu nhẹ với khả năng chống nước IP65 bền bỉ. Cảm biến thông minh tự động bật sáng khi trời tối và tắt sạc pin vào ban ngày, không cần đi dây điện rườm rà. Thiết kế bán nguyệt bo cong mềm mại, tôn thêm vẻ ấm cúng thư thái cho tường ban công, lối đi sân vườn hoặc hàng rào gỗ phong cách Japandi. Định kỳ dùng khăn khô lau sạch mặt kính tấm pin mặt trời để đèn sạc điện tốt nhất.', 1, 14, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Nhựa ABS cao cấp, tấm pin silicon đơn tinh thể"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "12 x 8.5 x 5 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Trung Quốc"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "ban công, sân vườn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Vỏ đen - Ánh sáng vàng", "Vỏ trắng - Ánh sáng vàng"]}], "totalElements": 1}', 280, 2),
(1259, NOW(), NOW(), null, null, 'Võng ghế treo ban công dệt sợi Cotton dày dặn kèm nệm ngồi', 'NEST-NT-1259', 'vong-ghe-treo-ban-cong-det-soi-cotton-day-dan-kem-nem-ngoi', 'Võng ghế treo ban công dệt sợi bông cotton tự nhiên êm ái kèm thanh gỗ định hình, tạo góc đọc sách chill cuối tuần.', 'Chiếc võng ghế được dệt từ sợi bông cotton thô dày dặn thoáng khí, kết hợp thanh gỗ sồi tự nhiên chắc chắn giúp căng rộng phom dáng không bị gò bó. Bộ sản phẩm kèm hai đệm ngồi êm ái, mang lại trải nghiệm đu đưa thư giãn tuyệt vời khi nhâm nhi tách trà hay đọc sách ngoài trời. Võng là điểm nhấn ấn tượng cho góc ban công chung cư rộng, giàn hoa sân thượng hay homestay phong cách Scandinavian lãng mạn. Bạn có thể tháo rời phần vải võng để giặt tay nhẹ nhàng khi bám bụi và bảo quản nơi khô ráo khi mưa lớn.', 1, 14, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Sợi cotton dệt tự nhiên, thanh gỗ sồi, đệm bông gòn"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "Vải võng 130 x 100 cm, Thanh gỗ dài 95 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "ban công, sân thượng"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng be viền tua rua", "Xám nhạt viền tua rua"]}], "totalElements": 1}', 2600, 2),
(1260, NOW(), NOW(), null, null, 'Băng ghế dài ban công gỗ Teak nan hở phong cách Scandinavian', 'NEST-NT-1260', 'bang-ghe-dai-ban-cong-go-teak-nan-ho-phong-cach-scandinavian', 'Băng ghế dài nan hở bằng gỗ teak tự nhiên chịu nắng mưa tốt, kiểu dáng thanh lịch tối giản cho ban công và sân vườn.', 'Băng ghế dài được sản xuất hoàn toàn từ gỗ teak tự nhiên với vân gỗ mộc mạc và hàm lượng dầu cao, giúp chống cong vênh mối mọt vượt trội trước nắng mưa. Thiết kế các nan gỗ hở thoáng khí hỗ trợ thoát nước nhanh sau cơn mưa, đem đến cảm giác ngồi vững chãi và thông thoáng. Sản phẩm là lựa chọn tinh tế để đặt sát lan can ban công chung cư, dọc lối đi sân vườn phong cách Scandinavian thanh lịch. Cách bảo dưỡng rất đơn giản: định kỳ lau sạch bụi bẩn và thoa một lớp dầu lau gỗ mộc chuyên dụng để giữ màu gỗ luôn tươi mới.', 1, 14, 4, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ teak tự nhiên phủ dầu bảo vệ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "110 x 40 x 45 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "ban công, sân thượng, sân vườn"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Chiều dài 110 cm", "Chiều dài 140 cm"]}], "totalElements": 1}', 9800, 2),
(1261, NOW(), NOW(), null, null, 'Bàn làm việc gỗ sồi tự nhiên chân vát bo góc phong cách Japandi', 'NEST-VP-1261', 'ban-lam-viec-go-soi-tu-nhien-chan-vat-bo-goc-phong-cach-japandi', 'Bàn làm việc chất liệu gỗ sồi tự nhiên với đường nét mộc mạc bo tròn tinh tế cho góc học tập và làm việc.', 'Chiếc bàn làm việc được hoàn thiện tỉ mỉ từ gỗ sồi tự nhiên chọn lọc với vân gỗ mộc mạc và sắc nét. Mặt bàn rộng rãi bo tròn 4 góc tạo cảm giác an toàn và thân thiện, chân trụ thuôn vát vững chãi đảm bảo độ chịu tải hoàn hảo. Sản phẩm mang lại sự tĩnh lặng và năng lượng tích cực cho góc văn phòng tại gia hay phòng đọc sách Japandi ấm cúng. Bạn nên lau chùi mặt bàn bằng khăn sợi ẩm mềm và thoa dầu dưỡng gỗ sáp tự nhiên định kỳ để giữ bề mặt luôn bền đẹp.', 1, 8, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi trắng tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "120 x 60 x 75 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["120 x 60 cm - Màu tự nhiên", "140 x 70 cm - Màu tự nhiên"]}], "totalElements": 1}', 22000, 2),
(1262, NOW(), NOW(), null, null, 'Bàn nâng hạ công thái học tự động mặt gỗ tần bì cao cấp', 'NEST-VP-1262', 'ban-nang-ha-cong-thai-hoc-tu-dong-mat-go-tan-bi-cao-cap', 'Bàn làm việc nâng hạ độ cao thông minh giúp thay đổi tư thế ngồi và đứng linh hoạt trong suốt ngày dài.', 'Bàn nâng hạ tự động sở hữu mặt bàn gỗ tần bì tự nhiên phủ sơn bảo vệ chống trầy xước, kết hợp cùng khung thép carbon sơn tĩnh điện bền bỉ. Động cơ kép vận hành êm ái cho phép chuyển đổi mượt mà giữa tư thế ngồi và đứng, giải tỏa áp lực cột sống hiệu quả khi làm việc thời gian dài. Thiết kế tinh gọn thích hợp cho không gian làm việc hiện đại hoặc Scandinavian tối giản. Vệ sinh khung chân kim loại bằng khăn khô và dùng khăn ẩm lau sạch mặt gỗ nhẹ nhàng.', 1, 8, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Mặt gỗ tần bì, khung thép sơn tĩnh điện"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "140 x 70 x 65-125 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Mặt gỗ sồi sáng - Khung trắng", "Mặt gỗ óc chó - Khung đen"]}], "totalElements": 1}', 34000, 2),
(1263, NOW(), NOW(), null, null, 'Ghế công thái học lưng lưới thoáng khí đỡ cột sống Japandi', 'NEST-VP-1263', 'ghe-cong-thai-hoc-lung-luoi-thoang-khi-do-cot-song-japandi', 'Ghế làm việc công thái học lưng lưới mềm mại nâng đỡ cột sống chuẩn khoa học, êm ái suốt ngày dài.', 'Mẫu ghế được nghiên cứu kỹ lưỡng nhằm mang lại tư thế ngồi chuẩn xác nhất, kết hợp hài hòa khung nhựa kỹ thuật bền nhẹ và lưới dệt thoáng khí đàn hồi cao. Đệm ngồi êm ái bọc vải nỉ cao cấp không giữ nhiệt, hỗ trợ thắt lưng điều chỉnh linh hoạt giúp giảm đau mỏi lưng và vai gáy. Chiếc ghế hoàn hảo cho phòng làm việc tại nhà thanh lịch, mang tinh thần thư thái của phong cách sống Bắc Âu. Bạn chỉ cần hút bụi định kỳ và lau khung ghế bằng khăn mềm.', 1, 8, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Lưới polyester, đệm cao su non, khung hợp kim"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "65 x 65 x 115-125 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Hiện đại"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Xám nhạt tối giản", "Đen than trầm ấm"]}], "totalElements": 1}', 14500, 2),
(1264, NOW(), NOW(), null, null, 'Ghế xoay văn phòng đệm vải nỉ chân kim loại phong cách Bắc Âu', 'NEST-VP-1264', 'ghe-xoay-van-phong-dem-vai-ni-chan-kim-loai-phong-cach-bac-au', 'Ghế xoay làm việc đệm nỉ êm ái với đường cong ôm trọn lưng, kết hợp vẻ đẹp Scandinavian ấm áp.', 'Chiếc ghế xoay làm việc bọc vải nỉ dệt thô cao cấp kết hợp lớp đệm bọt biển đúc nguyên khối êm ái, mang đến sự dễ chịu trọn vẹn khi bạn ngồi xử lý tài liệu. Phần lưng uốn cong nhẹ ôm lấy dáng người, chân xoay kim loại sơn mờ chịu tải vững vàng kèm bánh xe chống trượt trầy sàn gỗ. Ghế là điểm nhấn dịu dàng cho phòng làm việc phong cách Scandinavian thanh lịch. Nên bảo quản sản phẩm nơi khô ráo, tránh ánh nắng gắt trực tiếp và giặt khô định kỳ phần nệm.', 1, 8, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải nỉ dệt cao cấp, đệm mút PU, chân thép xoay"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "58 x 56 x 82-90 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu Be Sáng", "Màu Xám Tro"]}], "totalElements": 1}', 11000, 2),
(1265, NOW(), NOW(), null, null, 'Kệ màn hình máy tính gỗ tần bì kèm ngăn kéo để bàn làm việc', 'NEST-VP-1265', 'ke-man-hinh-may-tinh-go-tan-bi-kem-ngan-keo-de-ban-lam-viec', 'Kệ nâng màn hình gỗ tự nhiên kèm ngăn kéo tiện ích giúp tối ưu không gian và nâng tầm góc làm việc.', 'Sản phẩm được chế tác tỉ mỉ từ gỗ tần bì nguyên khối tự nhiên với vân mộc sáng đẹp và độ chịu lực cao. Kệ giúp nâng màn hình máy tính lên vừa tầm mắt, cải thiện tư thế ngồi làm việc thẳng thắn và giải phóng không gian bàn làm việc bên dưới để cất bàn phím ngăn nắp. Hộc ngăn kéo nhỏ xinh lưu trữ hoàn hảo bút thước và phụ kiện công nghệ. Sản phẩm rất phù hợp cho bàn làm việc phong cách Japandi. Vệ sinh đơn giản bằng khăn cotton sạch vắt ráo nước.', 1, 8, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tần bì tự nhiên sơn lau bóng mờ"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "55 x 22 x 10 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Gỗ Tần Bì Tự Nhiên", "Gỗ Sơn Màu Nâu Walnut"]}], "totalElements": 1}', 3200, 2),
(1266, NOW(), NOW(), null, null, 'Kệ đôi nâng màn hình gỗ sồi hai tầng phong cách mộc tối giản', 'NEST-VP-1266', 'ke-doi-nang-man-hinh-go-soi-hai-tang-phong-cach-moc-toi-gian', 'Kệ gỗ sồi nâng hai màn hình hoặc laptop, kiến tạo không gian làm việc rộng rãi và chuẩn công thái học.', 'Chiếc kệ nâng màn hình đôi chế tác từ gỗ sồi tự nhiên sở hữu chiều dài lý tưởng cho góc làm việc sử dụng 2 màn hình song song. Cấu trúc kệ hai tầng thông minh tạo thêm các khoang lưu trữ rộng rãi phía dưới cho sổ tay, chuột máy tính và sạc pin. Thiết kế đường nét thẳng mạch lạc tôn vinh chất mộc tinh túy của nội thất Japandi đương đại. Bạn chỉ cần đặt kệ trên mặt bàn phẳng, lau sạch bụi bẩn bằng khăn mềm khô ráo và tránh để chất lỏng đọng lâu.', 1, 8, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi tự nhiên cao cấp"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "105 x 23 x 12 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["Dài 105 cm - Gỗ Sồi Tự Nhiên", "Dài 120 cm - Gỗ Sồi Tự Nhiên"]}], "totalElements": 1}', 4800, 2),
(1267, NOW(), NOW(), null, null, 'Đèn treo màn hình máy tính bảo vệ mắt chống chói tự động', 'NEST-VP-1267', 'den-treo-man-hinh-may-tinh-bao-ve-mat-chong-choi-tu-dong', 'Đèn kẹp màn hình chống lóa mắt với cảm ứng điều chỉnh nhiệt độ màu, tiết kiệm trọn vẹn diện tích mặt bàn.', 'Đèn treo màn hình thông minh sở hữu thiết kế quang học phi đối xứng giúp ánh sáng chỉ rọi thẳng xuống bàn phím mà không gây phản chiếu lóa mắt lên màn hình. Vỏ hợp kim nhôm nhám nhẹ cùng nút cảm ứng nhạy bén cho phép chuyển đổi linh hoạt 3 dải màu ánh sáng từ ấm áp đến trắng tinh khiết. Đèn là lựa chọn lý tưởng cho góc làm việc tối giản phong cách Bắc Âu vào buổi đêm. Bảo quản bằng cách ngắt nguồn điện và lau sạch bụi bám trên thanh đèn bằng khăn vi sợi khô.', 1, 8, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Hợp kim nhôm sơn tĩnh điện, nhựa ABS"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "45 x 2.2 x 1.5 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Tối giản"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Đen Nhám Mờ", "Bạc Kim Loại"]}], "totalElements": 1}', 450, 2),
(1268, NOW(), NOW(), null, null, 'Khay tài liệu gỗ sồi 3 tầng để bàn ngăn nắp phong cách mộc', 'NEST-VP-1268', 'khay-tai-lieu-go-soi-3-tang-de-ban-ngan-nap-phong-cach-moc', 'Khay xếp tài liệu 3 tầng gỗ sồi tự nhiên lưu trữ giấy tờ khổ A4 gọn gàng và thẩm mỹ cho bàn làm việc.', 'Bộ khay đựng tài liệu 3 tầng được làm từ gỗ sồi tự nhiên với kỹ thuật ghép mộng mộc mạc và chuẩn xác. Các khay có thể trượt kéo hoặc xếp chồng vững chắc, chứa gọn giấy tờ cỡ A4, sổ tay và hợp đồng quan trọng, biến bàn làm việc bừa bộn thành góc làm việc chỉn chu ngăn nắp. Phong cách mộc mạc ấm áp mang đậm dấu ấn Wabi-Sabi và Japandi thanh tao. Cách bảo quản tốt nhất là lau bụi định kỳ bằng chổi lông gà hoặc khăn khô mềm mịn.', 1, 8, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ sồi trắng tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "34 x 26 x 24 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Gỗ Sồi Tự Nhiên Mộc", "Gỗ Sồi Lau Màu Trầm"]}], "totalElements": 1}', 2100, 2),
(1269, NOW(), NOW(), null, null, 'Bàn làm việc gỗ cao su tự nhiên ngăn kéo âm tối giản', 'NEST-VP-1269', 'ban-lam-viec-go-cao-su-tu-nhien-ngan-keo-am-toi-gian', 'Bàn làm việc gỗ cao su tự nhiên với thiết kế thanh mảnh và ngăn kéo ẩn tiện lợi.', 'Sản phẩm chế tác hoàn toàn từ gỗ cao su tự nhiên ghép thanh tiêu chuẩn xuất khẩu, phủ sơn PU mờ giữ trọn vân gỗ sáng ấm. Thiết kế chân côn thanh thoát kết hợp ngăn kéo trượt mượt mà, giúp không gian làm việc luôn ngăn nắp và thoáng đãng. Bàn phù hợp cho phòng làm việc gia đình, góc học tập căn hộ mang phong cách Scandinavian tươi sáng. Bạn nên lau mặt bàn định kỳ bằng khăn vải mềm hơi ẩm, tránh để bề mặt gỗ tiếp xúc trực tiếp với nước đọng hoặc vật quá nóng.', 1, 8, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ cao su tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "120 x 60 x 75 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu Gỗ Tự Nhiên", "Màu Nâu Óc Chó"]}], "totalElements": 1}', 18500, 2),
(1270, NOW(), NOW(), null, null, 'Bàn làm việc nâng hạ 2 động cơ mặt gỗ tre khung thép trắng', 'NEST-VP-1270', 'ban-lam-viec-nang-ha-2-dong-co-mat-go-tre-khung-thep-trang', 'Bàn nâng hạ chiều cao tự động mặt gỗ tre ép dẻo dai giúp bảo vệ cột sống hiệu quả.', 'Bàn nâng hạ trang bị mặt bàn gỗ tre tự nhiên ép 3 lớp chịu lực vượt trội, kết hợp bộ khung thép sơn tĩnh điện cứng cáp cùng hai mô-tơ vận hành êm ái. Mặt bàn bo tròn góc an toàn, tạo cảm giác dễ chịu và thư thái khi tì tay làm việc suốt ngày dài. Sản phẩm lý tưởng cho các setup văn phòng tại nhà Japandi hiện đại nhằm duy trì thói quen đứng ngồi linh hoạt. Hạn chế để nước thấm vào viền điện tử và lau sạch bụi bẩn bằng khăn khô mềm.', 1, 8, 8, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Mặt gỗ tre tự nhiên, chân thép sơn tĩnh điện"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "140 x 70 x 70-120 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["140 x 70 cm", "160 x 75 cm"]}], "totalElements": 1}', 32000, 2),
(1271, NOW(), NOW(), null, null, 'Ghế công thái học lưng đôi chống đau mỏi khung trắng nhã nhặn', 'NEST-VP-1271', 'ghe-cong-thai-hoc-lung-doi-chong-dau-moi-khung-trang-nha-nhan', 'Ghế công thái học tựa lưng đôi nâng đỡ cột sống tối ưu cho ngày dài làm việc êm ái.', 'Ghế công thái học lưng đôi được bọc vải lưới đàn hồi cao cấp nhập khẩu, mang lại cảm giác thoáng khí mát mẻ suốt nhiều giờ làm việc liên tục. Khung nhựa dẻo nguyên sinh trắng trang nhã, tích hợp đệm thắt lưng tự động ôm sát từng chuyển động của cột sống. Sản phẩm hoàn hảo cho không gian làm việc tối giản Bắc Âu, giúp giảm bớt căng thẳng vùng vai gáy. Vệ sinh phần lưới bằng máy hút bụi mini hoặc khăn ẩm vắt khô, tránh các chất tẩy rửa có tính kiềm mạnh.', 1, 8, 3, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Khung nhựa nguyên sinh, lưới đàn hồi cao cấp"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "65 x 65 x 115-125 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Xám Sáng Khung Trắng", "Đen Xám Khung Trắng"]}], "totalElements": 1}', 14200, 2),
(1272, NOW(), NOW(), null, null, 'Ghế làm việc xoay lưng nỉ đệm dày bo tròn phong cách Bắc Âu', 'NEST-VP-1272', 'ghe-lam-viec-xoay-lung-ni-dem-day-bo-tron-phong-cach-bac-au', 'Ghế xoay văn phòng bọc nỉ êm ái với thiết kế bo tròn tinh tế đậm chất Scandinavian.', 'Chiếc ghế xoay sở hữu lớp đệm mút đúc mật độ cao êm ái bọc vải nỉ cao cấp dệt sợi thoáng khí, mang đến trải nghiệm nâng đỡ thư giãn tuyệt vời. Kiểu dáng bo cong duyên dáng kết hợp trục xoay 360 độ và chân kim loại chắc chắn giúp di chuyển linh hoạt. Mẫu ghế thích hợp bài trí trong phòng làm việc tại nhà, phòng ngủ hoặc góc đọc sách ấm cúng phong cách Scandinavian. Để bảo quản bền đẹp, nên vệ sinh nỉ định kỳ bằng con lăn bụi hoặc giặt khô chuyên dụng.', 1, 8, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Vải nỉ cao cấp, đệm mút đúc, chân kim loại sơn tĩnh điện"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "60 x 58 x 82-92 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Đan Mạch"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Vải Nỉ Be Sáng", "Vải Nỉ Ghi Xám"]}], "totalElements": 1}', 9800, 2),
(1273, NOW(), NOW(), null, null, 'Kệ màn hình gỗ óc chó tích hợp rãnh đựng điện thoại tiện ích', 'NEST-VP-1273', 'ke-man-hinh-go-oc-cho-tich-hop-ranh-dung-dien-thoai-tien-ich', 'Kệ đỡ màn hình máy tính bằng gỗ khối tự nhiên giúp nâng cao tầm mắt chuẩn công thái học.', 'Kệ màn hình được gia công từ gỗ óc chó nguyên khối nhập khẩu với vân gỗ lượn sóng trầm ấm và các góc cạnh vát tỉ mỉ. Bề mặt kệ nâng màn hình lên đúng tầm mắt, giúp điều chỉnh tư thế ngồi thẳng lưng và giải phóng diện tích mặt bàn bên dưới. Thiết kế mộc mạc tinh tế đặc biệt hòa hợp với bàn làm việc phong cách Japandi hoặc Wabi-Sabi tao nhã. Bạn chỉ cần dùng khăn mềm lau sạch bụi và thỉnh thoảng thoa một lớp sáp ong tự nhiên để dưỡng gỗ bóng mượt.', 1, 8, 6, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ óc chó tự nhiên"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "55 x 22 x 9 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Gỗ Óc Chó Trầm", "Gỗ Tần Bì Sáng"]}], "totalElements": 1}', 2100, 2),
(1274, NOW(), NOW(), null, null, 'Khay đựng tài liệu A4 bằng mây đan thủ công viền gỗ mộc mạc', 'NEST-VP-1274', 'khay-dung-tai-lieu-a4-bang-may-dan-thu-cong-vien-go-moc-mac', 'Khay tài liệu A4 đan mây mộc mạc lưu trữ hồ sơ giấy tờ gọn gàng theo tinh thần Nhật Bản.', 'Khay tài liệu để bàn được hoàn thiện thủ công từ song mây tự nhiên kết hợp đáy gỗ dán chắc chắn, mang hơi thở mộc mạc và thanh bình vào góc làm việc. Kết cấu nan đan thanh thoát nhưng bền dai, vừa vặn lưu trữ tài liệu khổ A4, sách vở hoặc phụ kiện cá nhân gọn ghẽ. Vật dụng rất thích hợp cho những góc bàn làm việc Japandi tối giản hoặc Wabi-Sabi bình dị. Khi bảo quản, nên đặt khay ở nơi khô ráo, tránh ẩm ướt và định kỳ dùng chổi lông mềm quét bụi nan mây.', 1, 8, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Mây tự nhiên, gỗ ép"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "33 x 25 x 7 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Nhật Bản"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Wabi-Sabi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "size", "name": "Kích thước", "value": ["1 Tầng Đơn", "Bộ 2 Tầng Xếp Chồng"]}], "totalElements": 1}', 650, 2),
(1275, NOW(), NOW(), null, null, 'Kệ đựng hồ sơ tài liệu thép sơn tĩnh điện trắng tối giản', 'NEST-VP-1275', 'ke-dung-ho-so-tai-lieu-thep-son-tinh-dien-trang-toi-gian', 'Hộp đựng hồ sơ tài liệu đứng bằng thép sơn tĩnh điện lỗ thông thoáng hiện đại và bền bỉ.', 'Hộp đựng hồ sơ đứng làm từ thép tấm cao cấp dập lỗ thoáng khí, phủ lớp sơn tĩnh điện mờ mịn màng chống gỉ sét và trầy xước hiệu quả. Thiết kế thẳng đứng vững chãi giúp phân loại giấy tờ, tập hồ sơ hay tạp chí gọn gàng, tiết kiệm diện tích mặt bàn tối đa. Sản phẩm phù hợp với không gian làm việc hiện đại, văn phòng tại nhà phong cách Scandinavian trẻ trung. Vệ sinh khay rất đơn giản bằng khăn ẩm sạch, sau đó lau lại với khăn khô để duy trì độ sáng đẹp bền lâu.', 1, 8, 2, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Thép sơn tĩnh điện"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "30 x 26 x 32 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Thụy Điển"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Trắng Mờ", "Đen Nhám"]}], "totalElements": 1}', 1200, 2),
(1276, NOW(), NOW(), null, null, 'Đèn màn hình treo máy tính cảm ứng đổi 3 nhiệt độ màu nhôm mờ', 'NEST-VP-1276', 'den-man-hinh-treo-may-tinh-cam-ung-doi-3-nhiet-do-mau-nhom-mo', 'Đèn treo màn hình chống lóa mắt với nút chạm cảm ứng điều chỉnh quang thông mượt mà.', 'Đèn treo màn hình máy tính sở hữu thân vỏ hợp kim nhôm Anodized nhám mờ sang trọng, trang bị dải đèn LED chống ánh sáng xanh đạt chuẩn quốc tế. Cấu trúc quang học bất đối xứng rọi sáng vùng bàn phím mà không gây phản xạ chói lóa lên màn hình, bảo vệ mắt tối ưu. Thiết kế thanh thoát kẹp gọn lên cạnh màn hình, tạo nên không gian làm việc công nghệ hiện đại và tinh gọn. Lau thân đèn bằng vải sợi microfiber mềm mại khô ráo, tránh để dung dịch chất lỏng bắn vào cổng cắm nguồn.', 1, 8, 7, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Hợp kim nhôm Anodized, nhựa ABS"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "45 x 2.2 x 2.2 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Hiện đại"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "Phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Xám Bạc", "Đen Nhám"]}], "totalElements": 1}', 450, 2),
(1277, NOW(), NOW(), null, null, 'Ghế quỳ công thái học gỗ bạch dương uốn cong chống gù', 'NEST-VP-1277', 'ghe-quy-cong-thai-hoc-go-bach-duong-uon-cong-chong-gu', 'Ghế quỳ công thái học đệm nỉ êm ái, định hình tư thế ngồi thẳng tự nhiên và giảm áp lực lên cột sống khi làm việc.', 'Ghế quỳ công thái học được chế tác từ gỗ bạch dương uốn cong chịu lực tốt, kết hợp đệm bọc vải nỉ cao cấp thoáng khí, chống xẹp lún. Cấu trúc bập bênh thông minh phân bổ đều trọng lượng cơ thể lên xương chậu và ống chân, giúp lưng thẳng tự nhiên, ngăn ngừa đau mỏi cột sống khi ngồi lâu. Sản phẩm mang ngôn ngữ tối giản Bắc Âu, hòa hợp với phòng làm việc tại nhà hoặc góc đọc sách ấm cúng. Để bảo quản, bạn nên hút bụi bề mặt nỉ định kỳ và lau khung gỗ bằng khăn mềm khô ráo.', 1, 8, 5, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Khung gỗ bạch dương uốn nhiệt, đệm mút bọt biển bọc vải nỉ cao cấp"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "72 x 52 x 54 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Scandinavian"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Vải nỉ xám nhạt", "Vải nỉ be sáng", "Vải nỉ xanh rêu"]}], "totalElements": 1}', 6500, 2),
(1278, NOW(), NOW(), null, null, 'Kệ nâng màn hình gỗ tre ép tự nhiên tích hợp khe để bút', 'NEST-VP-1278', 'ke-nang-man-hinh-go-tre-ep-tu-nhien-tich-hop-khe-de-but', 'Kệ nâng màn hình gỗ tre tự nhiên giúp nâng tầm mắt làm việc chuẩn công thái học và giữ bàn làm việc luôn gọn gàng.', 'Kệ màn hình chế tác từ 100% gỗ tre tự nhiên xử lý ép nhiệt chống cong vênh, kháng mối mọt và phủ sơn bóng mờ chống thấm nước. Thiết kế tinh giản với các rãnh tiện ích để bút, điện thoại cùng khoảng trống rộng rãi phía dưới giúp cất gọn bàn phím cơ và chuột máy tính khi không sử dụng. Kệ mang hơi thở Japandi mộc mạc, phù hợp với mọi bàn làm việc văn phòng hoặc không gian cá nhân tại nhà. Vệ sinh kệ dễ dàng bằng khăn ẩm sạch và để nơi khô thoáng, tránh ánh nắng gắt.', 1, 8, 1, 1, 1, '{"content": [{"id": 1, "code": "material", "name": "Chất liệu", "value": "Gỗ tre ép khối tự nhiên xử lý sấy chống ẩm mốc"}, {"id": 2, "code": "dimension", "name": "Kích thước", "value": "56 x 24 x 9 cm"}, {"id": 3, "code": "origin", "name": "Xuất xứ", "value": "Việt Nam"}, {"id": 4, "code": "style", "name": "Phong cách", "value": "Japandi"}, {"id": 5, "code": "room", "name": "Không gian phù hợp", "value": "phòng làm việc"}], "totalElements": 5}', '{"content": [{"id": 1, "code": "color", "name": "Màu sắc", "value": ["Màu vàng tre tự nhiên", "Màu nâu óc chó"]}], "totalElements": 1}', 1800, 2);
